CREATE OR REPLACE PACKAGE BODY MGPA_INS_MGTIF2MGT
IS
	C_OFF		CONSTANT MAPA_META.FLG%TYPE := '0' ;
	C_ON		CONSTANT MAPA_META.FLG%TYPE := '1' ;

	C_NULL_VAL	CONSTANT MAPA_META.STR20%TYPE := MAC_STR.NULL_VAL ;

	G_LOG_NO	MAPA_META.BATCH_LOG_NO%TYPE ;
	G_LOG_SUB_KEY1	MAPA_META.BATCH_LOG_SUB_KEY1%TYPE ;
	G_LOG_SUB_KEY2	MAPA_META.BATCH_LOG_SUB_KEY2%TYPE ;

	G_TERM		MAPA_META.YM%TYPE ;

	G_CO_PARM	MAM_CO_PARM%ROWTYPE ;
	G_TMP_DPT	MAPA_META.COST_DPT_CD%TYPE ;
	G_LOT_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_SUBLOT_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_SNO1_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_SNO2_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_SNO3_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_SNO4_USE_TYP	MAPA_META.PS_USE_TYP%TYPE ;
	G_ACT_TRD_CALC_CTG	MAPA_META.CALC_CTG_CD%TYPE ;
	G_DEF_CALC_CTG	MAPA_META.CALC_CTG_CD%TYPE ;

	G_PARM_ITM_SUB_TYP	MAPA_META.PARM_VAL%TYPE := NULL ;

	--原価入出庫区分
	C_IO_FFR_PROV	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.FFR_PROV ;	--無償支給
	C_IO_ONR_PROV	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.ONR_PROV ;	--有償支給
	C_IO_STK_IN	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_IN ;	--入庫
	C_IO_STK_OUT	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_OUT ;	--出庫
	C_IO_STK_IO	CONSTANT MAPA_META.COST_IO_TYP%TYPE := MAC_COST_IO_TYP.STK_IO ;	--入出庫

	--会計伝票区分
	C_PURC_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_XPNS ; --経費購買
	C_PURC_RET_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_RET_XPNS ; --経費返品
	C_PURC_DSCNT_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_DSCNT_XPNS ; --経費値引
	C_PURC_XTRA_XPNS	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PURC_XTRA_XPNS ; --経費値増
	C_INPUT		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.INPUT ; --投入
	C_IN_ONR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.IN_ONR ; --投入(有償)
	C_FFR_PROV	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.FFR_PROV ;	--無償支給
	C_ONR_PROV	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.ONR_PROV ;	--有償支給
	C_FFR_PRVR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.FFR_PRVR ;	--無償支給戻
	C_ONR_PRVR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.ONR_PRVR ;	--有償支給戻
	C_INSP_SMPL	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.INSP_SMPL ; --検査抜取
	C_DISP_SCRP	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.DISP_SCRP ; --廃棄
	C_SO_STKTK	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SO_STKTK ;	--棚卸出庫
	C_IN_STKTK	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.IN_STKTK ;	--棚卸入庫
	C_PROD_ITM_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PROD_ITM_SO ; --販売倉入
	C_PROD_ITM_RET_SO CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.PROD_ITM_RET_SO ; --生産戻入
	C_DPT_XFR_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.DPT_XFR_SO ; --部門間移動
	C_OTH_CCN_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.OTH_CCN_SO ; --他勘定出庫
	C_OTH_CCN_GR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.OTH_CCN_GR ; --他勘定入庫
	C_STK_SW_SO	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.STK_SW_SO ; --在庫振替出庫
	C_STK_SW_GR	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.STK_SW_GR ; --在庫振替入庫
	C_SHIP		CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SHIP ;	--出荷
	C_SHIP_RET	CONSTANT MAPA_META.AC_SLIP_TYP%TYPE := MAC_AC_SLIP_TYP.SHIP_RET ;	--出荷返品

	C_PS_USE1	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.PRODSLS ;	--生産・販売データで使用する
	C_PS_USE2	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.PROD ;	--生産データのみ使用する
	C_PS_USE3	CONSTANT MAPA_META.PS_USE_TYP%TYPE := MAC_PS_USE_TYP.SLS ;	--販売データのみ使用する

	C_ACT1		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.NON ;	--対象外
	C_ACT2		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.ALL_SET ;	--設定
	C_ACT3		CONSTANT MAPA_META.ACT_SET_TYP%TYPE := MAC_ACT_SET_TYP.IN_SET ;	--受入のみ設定

	C_ASST1		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_SLS ;	 --自社(販売)
	C_ASST2		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.CO_PROD ; --自社(生産)
	C_ASST3		CONSTANT MAPA_META.ASST_TYP%TYPE := MAC_ASST_TYP.OTH ;	 --他社

	C_TRANS_ALC	CONSTANT MAPA_META.IO_TRANS_TYP%TYPE := MAC_IO_TRANS_TYP.ALC ;	--費用振替
	C_TRANS_INPT	CONSTANT MAPA_META.IO_TRANS_TYP%TYPE := MAC_IO_TRANS_TYP.INPT ;	--投入振替
	C_TRANS_GR	CONSTANT MAPA_META.IO_TRANS_TYP%TYPE := MAC_IO_TRANS_TYP.GR ;	--入庫振替
	C_TRANS_NON	CONSTANT MAPA_META.IO_TRANS_TYP%TYPE := MAC_IO_TRANS_TYP.NON ;	--対象外

	C_ASSET_MNG_MNG		CONSTANT MAPA_META.ASSET_MNG_TYP%TYPE := MAC_ASSET_MNG_TYP.MNG ;	 --資産管理する

	C_STR_TRD	CONSTANT MAPA_META.STR20%TYPE := MGC_STR.TRD_PREFIX ;

	C_NUM_SYS_ALC	CONSTANT MAPA_META.STR20%TYPE := MGC_NUM_SYS_TYP.ACT_ALC_AMT_KEY ;

	C_ALC_REC_PURC	CONSTANT MGPA_META.ALC_REC_TYP%TYPE := MGC_ALC_REC_TYP.PURC_ALC ;

	C_INPT_LOC_DPT		CONSTANT MAPA_META.INPT_LOC_TYP%TYPE := MAC_INPT_LOC_TYP.DPT ;	--部門構成
	C_INPT_LOC_LOC		CONSTANT MAPA_META.INPT_LOC_TYP%TYPE := MAC_INPT_LOC_TYP.LOC ;	--場所
	C_INPT_LOC_NON		CONSTANT MAPA_META.INPT_LOC_TYP%TYPE := MAC_INPT_LOC_TYP.NON ;	--指定なし
	C_INPT_LOC_MNG_DPT	CONSTANT MAPA_META.INPT_LOC_TYP%TYPE := MAC_INPT_LOC_TYP.MNG_DPT ;	--管理部門

	C_SET_TGT_INPT	CONSTANT MAPA_META.SET_TGT_TYP%TYPE := MAC_SET_TGT_TYP.INPT ;
	C_SET_TGT_IO	CONSTANT MAPA_META.SET_TGT_TYP%TYPE := MAC_SET_TGT_TYP.IO ;
	C_SET_TGT_SLS	CONSTANT MAPA_META.SET_TGT_TYP%TYPE := MAC_SET_TGT_TYP.SLS ;

	TYPE LIST_IO IS TABLE OF MGW_IO%ROWTYPE INDEX BY BINARY_INTEGER ;
	REC_IO		LIST_IO ;
	i		INTEGER := 0 ;

	C_MAX_CNT	CONSTANT INTEGER := 10000 ; --バルクインサートでの最大レコード数

	CURSOR CUR_ACT_IO (
		I_WG_CD IN MAPA_META.WG_CD%TYPE
		)
	IS
		SELECT	t.ROWID			ROW_ID,
			t.ACT_IO_ID, t.ACT_IO_ID_SUB,
			t.CALC_CTG_CD,
			t.WG_CD,
			t.YM, t.AC_DT,
			t.MNG_DPT_CD, t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
			t.COST_IO_TYP, t.AC_SLIP_TYP, t.AC_RSN_CD,
			t.OTHER_WG_CD, t.OTHER_DPT_CD,
			t.BP_CD, t.STK_BP_CD, t.ASST_TYP,
			t.QTY,
			t.ALC_WG_CD,
			t.ALC_DPT_CD, t.ALC_LOC_CD, t.ALC_OPER_CD, t.ALC_BP_CD,
			t.ALC_CTG_CD, t.ALC_ITM_CD, t.ALC_ITM_SUB1, t.ALC_ITM_SUB2, t.ALC_ITM_SUB3,
			t.ALC_LOT_NO, t.ALC_SUBLOT_NO, t.ALC_SNO1, t.ALC_SNO2, t.ALC_SNO3, t.ALC_SNO4,
			t.ALC_ITM_MFG_INST_NO,
			t.ZERO_EFFECT_FLG,
			m.IO_TRANS_TYP,
			m.ALC_AC_CD		M_ALC_AC_CD,
			m.ALC_AMT_FLG		M_ALC_AMT_FLG,
			m.ALC_WG_CD	M_ALC_WG_CD,
			m.DPT_FLG, m.DPT_CD	M_DPT_CD,
			m.LOC_FLG, m.LOC_CD	M_LOC_CD,
			m.OPER_FLG, m.OPER_CD	M_OPER_CD,
			m.BP_FLG, m.BP_CD	M_BP_CD,
			m.CTG_FLG, m.CTG_CD	M_CTG_CD,
			m.ITM_FLG, m.ITM_CD	M_ITM_CD,
			m.ITM_SUB1	M_ITM_SUB1, m.ITM_SUB2	M_ITM_SUB2, m.ITM_SUB3	M_ITM_SUB3,
			m.LOT_NO_FLG, m.LOT_NO	M_LOT_NO,
			m.SUBLOT_NO_FLG, m.SUBLOT_NO	M_SUBLOT_NO,
			m.SNO1_FLG, m.SNO1	M_SNO1,
			m.SNO2_FLG, m.SNO2	M_SNO2,
			m.SNO3_FLG, m.SNO3	M_SNO3,
			m.SNO4_FLG, m.SNO4	M_SNO4,
			m.ITM_MFG_INST_NO_FLG,
			NVL(m.INPT_LOC_TYP1, C_INPT_LOC_DPT) INPT_LOC_TYP1,
			m.INPT_LOC_TYP2,
			m.INPT_LOC_TYP3,
			m2.UNIT_CD,
			NVL(m2.DEC_PLACE, 0)	DEC_PLACE
		FROM	MGW_IO t, MAM_ACT_IO m, MAM_ITM_SRCH m2
		WHERE	0=0
		AND	t.WG_CD = I_WG_CD
		AND	t.AC_SLIP_TYP = m.AC_SLIP_TYP
		AND	(t.ITM_JNL_CD = m.ITM_JNL_CD OR m.ITM_JNL_CD IS NULL)
		AND	(t.AC_RSN_CD = m.AC_RSN_CD
			OR m.AC_RSN_CD IS NULL AND m.AC_RSN_NULL_FLG = C_OFF
			OR m.AC_RSN_CD IS NULL AND m.AC_RSN_NULL_FLG = C_ON AND t.AC_RSN_CD IS NULL)
		AND	(t.ALC_DPT_CD = m.TGT_DPT_CD OR m.TGT_DPT_CD IS NULL)
		AND	(t.ALC_LOC_CD = m.TGT_LOC_CD
			OR m.TGT_LOC_CD IS NULL AND m.LOC_NULL_FLG = C_OFF
			OR m.TGT_LOC_CD IS NULL AND m.LOC_NULL_FLG = C_ON AND t.ALC_LOC_CD IS NULL)
		AND	t.CALC_CTG_CD = m.CALC_CTG_CD
		AND	t.WG_CD = m.WG_CD
		AND	t.AC_DT BETWEEN m.ST_DT AND m.END_DT
		AND	t.COST_IO_TYP = C_IO_STK_OUT
		AND	t.TRD_GRP IS NULL
		AND	t.ALC_AC_CD IS NULL
		AND	(t.QTY <> 0 OR t.QTY = 0 AND t.ZERO_EFFECT_FLG = C_ON)
		AND	t.ITM_CD = m2.ITM_CD
		AND	t.ITM_SUB1 = m2.ITM_SUB1
		AND	t.ITM_SUB2 = m2.ITM_SUB2
		AND	t.ITM_SUB3 = m2.ITM_SUB3
		AND	m2.DEL_FLG = C_OFF
		AND	m2.RELEASE_FLG = C_ON
		ORDER BY NVL(t.ALC_DPT_CD, NVL(t.OTHER_DPT_CD, t.MNG_DPT_CD)),
				t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3, t.ROWID, m.PRIO
		;

PROCEDURE P_IFSUB (
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	出庫配賦費用の設定もしくは投入・入庫への振替の作成
<REMARKS>
	入出庫実績振替マスタによって出庫実績を振り替える
<ARGUMENTS>
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_FLG		MAPA_META.FLG%TYPE ;

	L_SUM_T		NUMBER ;
	L_NUM_ABS	NUMBER ;
	L_NUM_ABS2	NUMBER ;
	L_NUM_S		NUMBER ;
	L_NUM_S2	NUMBER ;

	L_DPT_CD	MAPA_META.COST_DPT_CD%TYPE ;
	L_DPT_FLG	MAPA_META.FLG%TYPE ;

	L_ITM_CD	MAPA_META.ITM_CD%TYPE ;
	L_DEC_PLACE	MAPA_META.DEC_PLACE%TYPE ;

	C_RND_TYP	CONSTANT MAPA_META.RND_TYP%TYPE := MAC_RND_TYP.RNDUP ;--切り上げ

	C_STR		CONSTANT MAPA_META.STR20%TYPE := FSC_MODULE_ID.CostManagement || MGC_STR.ACT_ID_DLM ;
	C_NUM_SYS_INPT	CONSTANT MAPA_META.STR20%TYPE := MGC_NUM_SYS_TYP.ACT_INPT_ID ;
	C_NUM_SYS_INPT_LENGTH	CONSTANT NUMBER := MGC_NUM_SYS_TYP.LENGTH(C_NUM_SYS_INPT) ;

	L_ROW_ID	ROWID ;
/************************************************************************/
PROCEDURE P_INS_INPT (
	I_REC	IN	CUR_ACT_IO%ROWTYPE,
	I_CNT	IN	NUMBER
)
/************************************************************************
<SYNOPSIS>
	投入振替のときの振替先投入実績をワークテーブルに作成する
<REMARKS>
	ワークテーブルの件数を取得する
<ARGUMENTS>
<IN>	I_REC
		入出庫実績と入出庫実績振替マスタを結合した結果
<IN>	I_CNT
		実行した回数
<HISTORY>
*************************************************************************/
AS
	L_INPT_LOC_TYP	MAPA_META.INPT_LOC_TYP%TYPE ;
BEGIN
	IF I_CNT = 1 THEN
		L_INPT_LOC_TYP := I_REC.INPT_LOC_TYP1 ;
	ELSIF I_CNT = 2 AND I_REC.INPT_LOC_TYP2 IS NOT NULL THEN
		L_INPT_LOC_TYP := I_REC.INPT_LOC_TYP2 ;
	ELSIF I_CNT = 3 AND I_REC.INPT_LOC_TYP2 IS NOT NULL AND I_REC.INPT_LOC_TYP3 IS NOT NULL THEN
		L_INPT_LOC_TYP := I_REC.INPT_LOC_TYP3 ;
	ELSE
		L_SUM_T := 0 ;
		RETURN ;
	END IF ;

	IF (L_DPT_CD IS NULL OR L_DPT_CD <> NVL(I_REC.ALC_DPT_CD, NVL(I_REC.OTHER_DPT_CD, I_REC.MNG_DPT_CD))) THEN
		L_DPT_CD := NVL(I_REC.ALC_DPT_CD, NVL(I_REC.OTHER_DPT_CD, I_REC.MNG_DPT_CD)) ;
		L_DPT_FLG := C_OFF ;
	END IF ;
	IF L_INPT_LOC_TYP = C_INPT_LOC_DPT AND I_REC.STK_BP_CD IS NULL AND L_DPT_FLG = C_OFF THEN
		MAPA_DPT_LOC.P_SET_DPT_LOC(G_TERM, L_DPT_CD) ;
		L_DPT_FLG := C_ON ;
	END IF ;

	--振替先の投入実績をワークテーブルに格納する
	DELETE MGW_ACT_INPT ;
	INSERT INTO MGW_ACT_INPT (
		PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
		ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		STK_BP_CD,
		QTY
		)
	SELECT	t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
		t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO, t1.OPER_ACT_NO,
		t1.LOC_CD, t1.STR_LN_CD,
		t1.STK_BP_CD,
		SUM(t1.QTY)
	FROM	MGT_ACT_INPT t1, MGT_INST_OPER t2
	WHERE	0=0
	AND	t1.CALC_CTG_CD = I_REC.CALC_CTG_CD
	AND	t1.WG_CD = I_REC.WG_CD
	AND	t1.YM = I_REC.YM
	AND	t1.ITM_CD = I_REC.ITM_CD
	AND	t1.ITM_SUB1 = I_REC.ITM_SUB1
	AND	t1.ITM_SUB2 = I_REC.ITM_SUB2
	AND	t1.ITM_SUB3 = I_REC.ITM_SUB3
	AND	t1.LOT_NO = I_REC.LOT_NO
	AND	t1.SUBLOT_NO = I_REC.SUBLOT_NO
	AND	t1.SNO1 = I_REC.SNO1
	AND	t1.SNO2 = I_REC.SNO2
	AND	t1.SNO3 = I_REC.SNO3
	AND	t1.SNO4 = I_REC.SNO4
	AND	t1.AC_SLIP_TYP IN (C_INPUT, C_IN_ONR)
	AND	t1.ASST_TYP = I_REC.ASST_TYP
	AND	t1.CALC_CTG_CD = t2.CALC_CTG_CD(+)
	AND	t1.PAR_ITM_CD = t2.ITM_CD(+)
	AND	t1.PAR_ITM_SUB1 = t2.ITM_SUB1(+)
	AND	t1.PAR_ITM_SUB2 = t2.ITM_SUB2(+)
	AND	t1.PAR_ITM_SUB3 = t2.ITM_SUB3(+)
	AND	t1.ITM_MFG_INST_NO = t2.ITM_MFG_INST_NO(+)
	AND	t1.MFG_ACT_NO = t2.MFG_ACT_NO(+)
	AND	t1.OPER_ACT_NO = t2.OPER_ACT_NO(+)
	AND	(
		I_REC.STK_BP_CD IS NOT NULL
			AND t1.STK_BP_CD IS NOT NULL
			AND I_REC.STK_BP_CD = t1.STK_BP_CD
			AND (
				L_INPT_LOC_TYP <> C_INPT_LOC_MNG_DPT
				OR
				L_INPT_LOC_TYP = C_INPT_LOC_MNG_DPT AND L_DPT_CD = t1.MNG_DPT_CD
			)
		OR I_REC.STK_BP_CD IS NULL
		AND t1.STK_BP_CD IS NULL
		AND	(
			L_INPT_LOC_TYP = C_INPT_LOC_NON
			OR
			L_INPT_LOC_TYP = C_INPT_LOC_LOC AND I_REC.ALC_LOC_CD = t1.LOC_CD
			OR
			L_INPT_LOC_TYP = C_INPT_LOC_MNG_DPT AND L_DPT_CD = t1.MNG_DPT_CD
			OR
			L_INPT_LOC_TYP = C_INPT_LOC_DPT
			AND EXISTS (
				SELECT	'X'
				FROM	MAW_DPT_LOC w
				WHERE	0=0
				AND	w.DPT_CD = L_DPT_CD
				AND	w.LOC_CD = t1.LOC_CD
				AND	(
					w.OPER_CD = t2.OPER_CD
					OR
					w.OPER_CD IS NULL AND w.OPER_NULL_FLG = C_OFF
					OR
					w.OPER_CD IS NULL AND w.OPER_NULL_FLG = C_ON AND t2.OPER_CD IS NULL
					)
				)
			)
		)
	AND	t1.QTY > 0
	GROUP BY
		t1.PAR_ITM_CD, t1.PAR_ITM_SUB1, t1.PAR_ITM_SUB2, t1.PAR_ITM_SUB3,
		t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO, t1.OPER_ACT_NO,
		t1.LOC_CD, t1.STR_LN_CD,
		t1.STK_BP_CD
	;

	SELECT	NVL(SUM(w.QTY), 0)
	INTO	L_SUM_T
	FROM	MGW_ACT_INPT w
	WHERE	0=0
	;
END P_INS_INPT ;
/************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IFSUB') ;

	L_ROW_ID := NULL ;
	L_DPT_CD := NULL ;
	L_DPT_FLG := C_OFF ;

	G_PARM_ITM_SUB_TYP := MAPA_COMM.F_GET_PARM('ITM_SUB_TYP') ;

	DELETE MGW_ACT_INPT2 ;

	FOR x IN CUR_ACT_IO(I_WG_CD)
	LOOP
		--優先順位の低いレコードは処理しない
		IF L_ROW_ID = x.ROW_ID THEN
			GOTO NEXT_OUT_LOOP ;
		ELSE
			L_ROW_ID := x.ROW_ID ;
		END IF ;

		IF x.IO_TRANS_TYP = C_TRANS_INPT THEN
			--投入への振替
			P_INS_INPT(x, 1) ;
			IF L_SUM_T = 0 THEN
				P_INS_INPT(x, 2) ;
				IF L_SUM_T = 0 THEN
					P_INS_INPT(x, 3) ;
				END IF ;
			END IF ;

			IF x.ZERO_EFFECT_FLG = C_ON AND x.QTY = 0 THEN
				IF L_SUM_T = 0 THEN
					GOTO TRANS_SKIP ;
				ELSE
					GOTO NEXT_OUT_LOOP ;
				END IF ;
			END IF ;

			IF L_SUM_T = 0 THEN
				--対応する投入実績が1件も存在しないため、投入への振替ができません。
				--配賦科目が設定されているときは配賦振替の処理を行います。
				--入出庫実績ＩＤ：{1} 品目：{2} 部門：{3} 数量：{4} 配賦科目：{5}
				FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0016', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
								x.ACT_IO_ID, MAPA_COMM.F_TO_DISP_ITM(x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3, G_PARM_ITM_SUB_TYP),
								L_DPT_CD, x.QTY, x.M_ALC_AC_CD) ;
				GOTO TRANS_SKIP ;
			END IF ;

			L_FLG := C_OFF ;
			L_NUM_ABS := ABS(x.QTY) ;
			L_NUM_ABS2 := 0 ;
			L_NUM_S	:= x.QTY ;

			FOR y IN (
				SELECT	w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
					w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
					w.LOC_CD, w.STR_LN_CD,
					w.STK_BP_CD,
					w.QTY
				FROM	MGW_ACT_INPT w
				WHERE	0=0
				ORDER BY w.QTY DESC
				)
			LOOP
				L_NUM_S2 := MAPA_CALC.F_RND(x.QTY * y.QTY / L_SUM_T, x.DEC_PLACE, C_RND_TYP) ;
				L_NUM_ABS2 := L_NUM_ABS2 + ABS(L_NUM_S2) ;

				IF L_NUM_ABS2 >= L_NUM_ABS THEN
					IF L_FLG = C_ON THEN
						EXIT ;
					ELSE
						L_NUM_S2 := L_NUM_S ;
						L_FLG := C_ON ;
					END IF ;
				END IF ;

				IF L_NUM_S2 <> 0 THEN
					INSERT INTO MGW_ACT_INPT2 (
						ACT_IO_ID, ACT_IO_ID_SUB,
						CALC_CTG_CD, WG_CD,
						YM, AC_DT,
						PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
						ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
						LOC_CD, STR_LN_CD,
						MNG_DPT_CD,
						ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
						LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
						AC_SLIP_TYP, AC_RSN_CD,
						BP_CD,
						STK_BP_CD, ASST_TYP,
						QTY
						)
					VALUES	(
						x.ACT_IO_ID, x.ACT_IO_ID_SUB,
						x.CALC_CTG_CD, x.WG_CD,
						x.YM, x.AC_DT,
						y.PAR_ITM_CD, y.PAR_ITM_SUB1, y.PAR_ITM_SUB2, y.PAR_ITM_SUB3,
						y.ITM_MFG_INST_NO, y.MFG_ACT_NO, y.OPER_ACT_NO,
						y.LOC_CD, y.STR_LN_CD,
						x.MNG_DPT_CD,
						x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
						x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
						x.AC_SLIP_TYP, x.AC_RSN_CD,
						x.BP_CD,
						y.STK_BP_CD, x.ASST_TYP,
						L_NUM_S2
						)
					;
					L_NUM_S  := L_NUM_S - L_NUM_S2 ;
				END IF ;
			END LOOP ;

			DELETE MGW_IO t WHERE t.ROWID = x.ROW_ID ;

			GOTO NEXT_OUT_LOOP ;

		ELSIF x.IO_TRANS_TYP = C_TRANS_GR THEN

			IF x.ZERO_EFFECT_FLG = C_ON AND x.QTY = 0 THEN
				GOTO NEXT_OUT_LOOP ;
			END IF ;

			--入庫への振替
			UPDATE	MGW_IO t
			SET	t.COST_IO_TYP = C_IO_STK_IN,
				t.QTY  = t.QTY * (-1),
				t.ALC_AC_CD = NULL, t.ALC_AMT_FLG = C_OFF, t.ALC_WG_CD = NULL,
				t.ALC_DPT_CD = NULL, t.ALC_LOC_CD = NULL, t.ALC_OPER_CD = NULL, t.ALC_BP_CD = NULL,
				t.ALC_CTG_CD = NULL, t.ALC_ITM_CD = NULL, t.ALC_ITM_SUB1 = NULL, t.ALC_ITM_SUB2 = NULL, t.ALC_ITM_SUB3 = NULL,
				t.ALC_LOT_NO = NULL, t.ALC_SUBLOT_NO = NULL, t.ALC_SNO1 = NULL, t.ALC_SNO2 = NULL,
				t.ALC_SNO3 = NULL, t.ALC_SNO4 = NULL, t.ALC_ITM_MFG_INST_NO = NULL, t.MFG_ACT_GRP = NULL
			WHERE	0=0
			AND	t.ROWID = x.ROW_ID
			;

			GOTO NEXT_OUT_LOOP ;

		ELSIF x.IO_TRANS_TYP = C_TRANS_NON THEN
			--対象外は処理しない
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		<<TRANS_SKIP>>
			NULL ;

		--配賦費用の設定
		IF x.M_ALC_AC_CD IS NULL THEN
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		UPDATE	MGW_IO t
		SET	t.ALC_AC_CD = x.M_ALC_AC_CD,
			t.ALC_AMT_FLG = x.M_ALC_AMT_FLG,
			t.ALC_WG_CD = NVL(x.M_ALC_WG_CD, NVL(x.ALC_WG_CD, x.WG_CD)),
			t.ALC_DPT_CD = DECODE(x.DPT_FLG, C_OFF, x.M_DPT_CD, x.ALC_DPT_CD),
			t.ALC_LOC_CD = DECODE(x.LOC_FLG, C_OFF, x.M_LOC_CD, x.ALC_LOC_CD),
			t.ALC_OPER_CD = DECODE(x.OPER_FLG, C_OFF, x.M_OPER_CD, x.ALC_OPER_CD),
			t.ALC_BP_CD = DECODE(x.BP_FLG, C_OFF, x.M_BP_CD, x.ALC_BP_CD),
			t.ALC_CTG_CD = DECODE(x.CTG_FLG, C_OFF, x.M_CTG_CD, x.ALC_CTG_CD),
			t.ALC_ITM_CD = DECODE(x.ITM_FLG, C_OFF, x.M_ITM_CD, x.ALC_ITM_CD),
			t.ALC_ITM_SUB1 = DECODE(x.ITM_FLG, C_OFF, x.M_ITM_SUB1, x.ALC_ITM_SUB1),
			t.ALC_ITM_SUB2 = DECODE(x.ITM_FLG, C_OFF, x.M_ITM_SUB2, x.ALC_ITM_SUB2),
			t.ALC_ITM_SUB3 = DECODE(x.ITM_FLG, C_OFF, x.M_ITM_SUB3, x.ALC_ITM_SUB3),
			t.ALC_LOT_NO = DECODE(x.LOT_NO_FLG, C_OFF, x.M_LOT_NO, x.ALC_LOT_NO),
			t.ALC_SUBLOT_NO = DECODE(x.SUBLOT_NO_FLG, C_OFF, x.M_SUBLOT_NO, x.ALC_SUBLOT_NO),
			t.ALC_SNO1 = DECODE(x.SNO1_FLG, C_OFF, x.M_SNO1, x.ALC_SNO1),
			t.ALC_SNO2 = DECODE(x.SNO2_FLG, C_OFF, x.M_SNO2, x.ALC_SNO2),
			t.ALC_SNO3 = DECODE(x.SNO3_FLG, C_OFF, x.M_SNO3, x.ALC_SNO3),
			t.ALC_SNO4 = DECODE(x.SNO4_FLG, C_OFF, x.M_SNO4, x.ALC_SNO4),
			t.ALC_ITM_MFG_INST_NO = DECODE(x.ITM_MFG_INST_NO_FLG, C_OFF, NULL, x.ALC_ITM_MFG_INST_NO)
		WHERE	0=0
		AND	t.ROWID = x.ROW_ID
		;

		<<NEXT_OUT_LOOP>>
			NULL ;
	END LOOP ;

	INSERT INTO MGT_ACT_INPT (
		ACT_INPT_ID, ACT_INPT_ID_SUB,
		CALC_CTG_CD, WG_CD,
		YM, AC_DT,
		PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
		ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		AC_SLIP_TYP, AC_RSN_CD,
		BP_CD,
		STK_BP_CD, ASST_TYP,
		QTY
		)
	SELECT	C_STR || LPAD(MAPA_NUM.F_GET_SEQ(C_NUM_SYS_INPT), C_NUM_SYS_INPT_LENGTH, '0'), '1',
		t.CALC_CTG_CD, t.WG_CD,
		t.YM, t.AC_DT,
		t.PAR_ITM_CD, t.PAR_ITM_SUB1, t.PAR_ITM_SUB2, t.PAR_ITM_SUB3,
		t.ITM_MFG_INST_NO, t.MFG_ACT_NO, t.OPER_ACT_NO,
		t.LOC_CD, t.STR_LN_CD,
		t.MNG_DPT_CD,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
		t.AC_SLIP_TYP, t.AC_RSN_CD,
		t.BP_CD,
		t.STK_BP_CD, t.ASST_TYP,
		t.QTY
	FROM (
		SELECT	w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.MNG_DPT_CD,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.AC_SLIP_TYP, w.AC_RSN_CD,
			w.BP_CD,
			w.STK_BP_CD, w.ASST_TYP,
			SUM(w.QTY)	QTY
		FROM	MGW_ACT_INPT2 w
		WHERE	0=0
		GROUP BY
			w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.MNG_DPT_CD,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.AC_SLIP_TYP, w.AC_RSN_CD,
			w.BP_CD,
			w.STK_BP_CD, w.ASST_TYP
		HAVING SUM(w.QTY) <> 0
		) t
	WHERE	0=0
	;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IFSUB') ;

END P_IFSUB ;

PROCEDURE INS_MGW_IO
/************************************************************************
<SYNOPSIS>
	MGW_IOを作成する
<REMARKS>
<ARGUMENTS>
<HISTORY>
*************************************************************************/
AS
/*************************************************************************/
BEGIN
	FORALL t IN 1..i
		INSERT INTO MGW_IO VALUES REC_IO(t) ;

	REC_IO.DELETE ;
	i := 0 ;
END ;

PROCEDURE P_IFSUB2 (
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	生販連携関連の入出庫実績をまとめる
<REMARKS>
	１．生販連携関連の入出庫実績をまとめる
	２．生産側の出庫が多ければ販売倉入(10701)とし、生産からの出庫・販売への入庫とする
		販売側の出庫が多ければ生産戻入(10712)とし、販売からの出庫・生産への入庫とする
<ARGUMENTS>
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_CNT		NUMBER ;

	L_TMP		MGW_WIO%ROWTYPE ;
	L_RSN		MAPA_META.AC_RSN_CD%TYPE ;
/*************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IFSUB2') ;

	--販売の生産戻入を生産のマイナスの生産戻入とする
	UPDATE	MGW_IO w
	SET	w.WG_CD	= w.OTHER_WG_CD,
		w.MNG_DPT_CD	= w.OTHER_DPT_CD,
		w.AC_SLIP_TYP	= DECODE(w.ZERO_EFFECT_FLG, C_OFF, C_PROD_ITM_SO, C_PROD_ITM_RET_SO),
		w.QTY		= w.QTY * (-1),
		w.AMT		= w.AMT * (-1),
		w.TRD_CUR_AMT	= w.TRD_CUR_AMT * (-1),
		w.OTHER_WG_CD = w.WG_CD,
		w.OTHER_DPT_CD	= w.MNG_DPT_CD
	WHERE	0=0
	AND	w.AC_SLIP_TYP = C_PROD_ITM_RET_SO
	AND	w.TRD_GRP IS NOT NULL
	;

	DELETE MGW_WIO w ;

	INSERT INTO MGW_WIO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, CALC_SEQ, ZERO_EFFECT_FLG
		)
	SELECT	w.ACT_IO_ID, '1',
		w.CALC_CTG_CD,
		w.WG_CD, w.YM, w.AC_DT,
		w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		CASE WHEN G_LOT_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.LOT_ACT_TYP, C_ACT1) = C_ACT2 THEN w.LOT_NO
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SUBLOT_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SUBLOT_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SUBLOT_NO
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO1_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO1_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO1
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO2_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO2_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO2
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO3_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO3_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO3
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO4_USE_TYP = C_PS_USE3 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO4_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO4
			ELSE C_NULL_VAL END
		END,
		C_IO_STK_OUT, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.OTHER_WG_CD, w.OTHER_DPT_CD,
		w.BP_CD, w.STK_BP_CD, C_ASST2,
		w.QTY, w.AMT,
		w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, NVL(m3.CALC_SEQ, 0), w.ZERO_EFFECT_FLG
	FROM	MGW_IO w, MAM_ITM_SRCH m, MAM_CALC_PTN m2, MAM_WG m3
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
	AND	w.TRD_GRP IS NOT NULL
	AND	w.ITM_CD = m.ITM_CD
	AND	w.ITM_SUB1 = m.ITM_SUB1
	AND	w.ITM_SUB2 = m.ITM_SUB2
	AND	w.ITM_SUB3 = m.ITM_SUB3
	AND	m.DEL_FLG = C_OFF
	AND	m.RELEASE_FLG = C_ON
	AND	m.CALC_PTN_CD = m2.CALC_PTN_CD(+)
	AND	m2.DEL_FLG(+) = C_OFF
	AND	w.WG_CD = m3.WG_CD(+)
	AND	m3.DEL_FLG(+) = C_OFF
	;

	INSERT INTO MGW_WIO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, CALC_SEQ, ZERO_EFFECT_FLG
		)
	SELECT	w.ACT_IO_ID, '2',
		w.CALC_CTG_CD,
		w.OTHER_WG_CD, w.YM, w.AC_DT,
		w.OTHER_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		CASE WHEN G_LOT_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.LOT_ACT_TYP, C_ACT1) = C_ACT2 THEN w.LOT_NO
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SUBLOT_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SUBLOT_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SUBLOT_NO
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO1_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO1_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO1
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO2_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO2_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO2
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO3_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO3_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO3
			ELSE C_NULL_VAL END
		END,
		CASE WHEN G_SNO4_USE_TYP = C_PS_USE2 THEN C_NULL_VAL
		ELSE CASE WHEN NVL(m2.SNO4_ACT_TYP, C_ACT1) = C_ACT2 THEN w.SNO4
			ELSE C_NULL_VAL END
		END,
		C_IO_STK_IN, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.WG_CD, w.MNG_DPT_CD,
		w.BP_CD, w.STK_BP_CD, C_ASST1,
		w.QTY, w.AMT,
		w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, NVL(m3.CALC_SEQ, 0), w.ZERO_EFFECT_FLG
	FROM	MGW_IO w, MAM_ITM_SRCH m, MAM_CALC_PTN m2, MAM_WG m3
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
	AND	w.TRD_GRP IS NOT NULL
	AND	w.ITM_CD = m.ITM_CD
	AND	w.ITM_SUB1 = m.ITM_SUB1
	AND	w.ITM_SUB2 = m.ITM_SUB2
	AND	w.ITM_SUB3 = m.ITM_SUB3
	AND	m.DEL_FLG = C_OFF
	AND	m.RELEASE_FLG = C_ON
	AND	m.CALC_PTN_CD = m2.CALC_PTN_CD(+)
	AND	m2.DEL_FLG(+) = C_OFF
	AND	w.OTHER_WG_CD = m3.WG_CD(+)
	AND	m3.DEL_FLG(+) = C_OFF
	;

	DELETE MGW_WIO2 w ;

	--生販連携の集計
	FOR x1 IN (
		SELECT	w.*
		FROM	MGW_WIO w
		WHERE	0=0
		AND	w.YM = I_YM
		AND	w.COST_IO_TYP = C_IO_STK_OUT
		ORDER BY ABS(w.QTY) DESC --数量の大きい(絶対値)データから処理
		)
	LOOP
		FOR x2 IN (
			SELECT	w.*
			FROM	MGW_WIO w
			WHERE	0=0
			AND	w.YM = x1.YM
			AND	w.COST_IO_TYP = C_IO_STK_IN
			AND	w.TRD_GRP = x1.TRD_GRP
			)
		LOOP
			IF x1.ZERO_EFFECT_FLG = C_ON THEN
				GOTO SKIP_ZERO ;
			END IF ;

			IF x1.QTY < 0 THEN
				L_TMP := x1 ;
				x1 := x2 ;
				x2 := L_TMP ;
				x1.QTY := x1.QTY * -1 ;
				x2.QTY := x2.QTY * -1 ;
				x1.AMT := x1.AMT * -1 ;
				x2.AMT := x2.AMT * -1 ;
				x1.TRD_CUR_AMT := x1.TRD_CUR_AMT * -1 ;
				x2.TRD_CUR_AMT := x2.TRD_CUR_AMT * -1 ;
			END IF ;

			L_CNT := 0 ;
			L_RSN := NULL ;
			FOR x3 IN (
				SELECT	w.GI_AC_RSN_CD	AC_RSN_CD
				FROM	MGW_WIO2 w
				WHERE	0=0
				AND	w.GI_CALC_CTG_CD = x2.CALC_CTG_CD
				AND	w.GI_WG_CD = x2.WG_CD
				AND	w.GI_MNG_DPT_CD = x2.MNG_DPT_CD
				AND	w.GI_ITM_CD	= x2.ITM_CD
				AND	w.GI_ITM_SUB1	= x2.ITM_SUB1
				AND	w.GI_ITM_SUB2	= x2.ITM_SUB2
				AND	w.GI_ITM_SUB3	= x2.ITM_SUB3
				AND	w.GI_LOT_NO	= x2.LOT_NO
				AND	w.GI_SUBLOT_NO	= x2.SUBLOT_NO
				AND	w.GI_SNO1	= x2.SNO1
				AND	w.GI_SNO2	= x2.SNO2
				AND	w.GI_SNO3	= x2.SNO3
				AND	w.GI_SNO4	= x2.SNO4
				AND	(w.GI_BP_CD = x2.BP_CD OR w.GI_BP_CD IS NULL AND x2.BP_CD IS NULL)
				AND	(w.GI_STK_BP_CD = x2.STK_BP_CD OR w.GI_STK_BP_CD IS NULL AND x2.STK_BP_CD IS NULL)
				AND	w.GI_ASST_TYP	= x2.ASST_TYP
				AND	(w.GI_TRD_CUR_CD = x2.TRD_CUR_CD OR w.GI_TRD_CUR_CD IS NULL AND x2.TRD_CUR_CD IS NULL)
				AND	(w.GI_XRATE = x2.XRATE OR w.GI_XRATE IS NULL AND x2.XRATE IS NULL)
				AND	w.GI_ZERO_EFFECT_FLG = C_OFF
				AND	w.GR_CALC_CTG_CD = x1.CALC_CTG_CD
				AND	w.GR_WG_CD = x1.WG_CD
				AND	w.GR_MNG_DPT_CD	= x1.MNG_DPT_CD
				AND	w.GR_ITM_CD	= x1.ITM_CD
				AND	w.GR_ITM_SUB1	= x1.ITM_SUB1
				AND	w.GR_ITM_SUB2	= x1.ITM_SUB2
				AND	w.GR_ITM_SUB3	= x1.ITM_SUB3
				AND	w.GR_LOT_NO	= x1.LOT_NO
				AND	w.GR_SUBLOT_NO	= x1.SUBLOT_NO
				AND	w.GR_SNO1	= x1.SNO1
				AND	w.GR_SNO2	= x1.SNO2
				AND	w.GR_SNO3	= x1.SNO3
				AND	w.GR_SNO4	= x1.SNO4
				AND	(w.GR_BP_CD = x1.BP_CD OR w.GR_BP_CD IS NULL AND x1.BP_CD IS NULL)
				AND	(w.GR_STK_BP_CD = x1.STK_BP_CD OR w.GR_STK_BP_CD IS NULL AND x1.STK_BP_CD IS NULL)
				AND	w.GR_ASST_TYP	= x1.ASST_TYP
				AND	(w.GR_TRD_CUR_CD = x1.TRD_CUR_CD OR w.GR_TRD_CUR_CD IS NULL AND x1.TRD_CUR_CD IS NULL)
				AND	(w.GR_XRATE = x1.XRATE OR w.GR_XRATE IS NULL AND x1.XRATE IS NULL)
				AND	w.GR_ZERO_EFFECT_FLG = C_OFF
				)
			LOOP
				IF NVL(x2.AC_RSN_CD, C_NULL_VAL) = NVL(x3.AC_RSN_CD, C_NULL_VAL) OR L_CNT = 0 THEN
					L_RSN := x3.AC_RSN_CD ;
				END IF ;
				L_CNT := L_CNT + 1 ;
			END LOOP ;

			<<SKIP_ZERO>>

			IF L_CNT = 0 OR x1.ZERO_EFFECT_FLG = C_ON THEN
				--相手が存在しない場合はそのまま作成する
				INSERT INTO MGW_WIO2 (
					GI_ACT_IO_ID, GI_ACT_IO_ID_SUB,
					GI_CALC_CTG_CD, GI_WG_CD, GI_YM, GI_AC_DT,
					GI_MNG_DPT_CD, GI_ITM_CD, GI_ITM_SUB1, GI_ITM_SUB2, GI_ITM_SUB3,
					GI_LOT_NO, GI_SUBLOT_NO, GI_SNO1, GI_SNO2, GI_SNO3, GI_SNO4,
					GI_COST_IO_TYP, GI_AC_SLIP_TYP, GI_AC_RSN_CD,
					GI_BP_CD, GI_STK_BP_CD, GI_ASST_TYP,
					GI_QTY, GI_AMT,
					GI_TRD_CUR_CD, GI_TRD_CUR_AMT, GI_XRATE,
					GI_TRD_GRP, GI_REC_EVAL_TYP, GI_CALC_SEQ, GI_ZERO_EFFECT_FLG,
					GR_ACT_IO_ID, GR_ACT_IO_ID_SUB,
					GR_CALC_CTG_CD, GR_WG_CD, GR_YM, GR_AC_DT,
					GR_MNG_DPT_CD, GR_ITM_CD, GR_ITM_SUB1, GR_ITM_SUB2, GR_ITM_SUB3,
					GR_LOT_NO, GR_SUBLOT_NO, GR_SNO1, GR_SNO2, GR_SNO3, GR_SNO4,
					GR_COST_IO_TYP, GR_AC_SLIP_TYP, GR_AC_RSN_CD,
					GR_BP_CD, GR_STK_BP_CD, GR_ASST_TYP,
					GR_QTY, GR_AMT,
					GR_TRD_CUR_CD, GR_TRD_CUR_AMT, GR_XRATE,
					GR_TRD_GRP, GR_REC_EVAL_TYP, GR_CALC_SEQ, GR_ZERO_EFFECT_FLG
					)
				VALUES	(
					x1.ACT_IO_ID, x1.ACT_IO_ID_SUB,
					x1.CALC_CTG_CD, x1.WG_CD, x1.YM, x1.AC_DT,
					x1.MNG_DPT_CD, x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
					x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
					x1.COST_IO_TYP, x1.AC_SLIP_TYP, x1.AC_RSN_CD,
					x1.BP_CD, x1.STK_BP_CD, x1.ASST_TYP,
					x1.QTY, x1.AMT,
					x1.TRD_CUR_CD, x1.TRD_CUR_AMT, x1.XRATE,
					x1.TRD_GRP, x1.REC_EVAL_TYP, x1.CALC_SEQ, x1.ZERO_EFFECT_FLG,
					x2.ACT_IO_ID, x2.ACT_IO_ID_SUB,
					x2.CALC_CTG_CD, x2.WG_CD, x2.YM, x2.AC_DT,
					x2.MNG_DPT_CD, x2.ITM_CD, x2.ITM_SUB1, x2.ITM_SUB2, x2.ITM_SUB3,
					x2.LOT_NO, x2.SUBLOT_NO, x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
					x2.COST_IO_TYP, x2.AC_SLIP_TYP, x2.AC_RSN_CD,
					x2.BP_CD, x2.STK_BP_CD, x2.ASST_TYP,
					x2.QTY, x2.AMT,
					x2.TRD_CUR_CD, x2.TRD_CUR_AMT, x2.XRATE,
					x2.TRD_GRP, x2.REC_EVAL_TYP, x2.CALC_SEQ, x2.ZERO_EFFECT_FLG
					) ;
			ELSE
				--相手が存在する場合は集計のため反転して作成する
				INSERT INTO MGW_WIO2 (
					GI_ACT_IO_ID, GI_ACT_IO_ID_SUB,
					GI_CALC_CTG_CD, GI_WG_CD, GI_YM, GI_AC_DT,
					GI_MNG_DPT_CD, GI_ITM_CD, GI_ITM_SUB1, GI_ITM_SUB2, GI_ITM_SUB3,
					GI_LOT_NO, GI_SUBLOT_NO, GI_SNO1, GI_SNO2, GI_SNO3, GI_SNO4,
					GI_COST_IO_TYP, GI_AC_SLIP_TYP, GI_AC_RSN_CD,
					GI_BP_CD, GI_STK_BP_CD, GI_ASST_TYP,
					GI_QTY, GI_AMT,
					GI_TRD_CUR_CD, GI_TRD_CUR_AMT, GI_XRATE,
					GI_TRD_GRP, GI_REC_EVAL_TYP, GI_CALC_SEQ, GI_ZERO_EFFECT_FLG,
					GR_ACT_IO_ID, GR_ACT_IO_ID_SUB,
					GR_CALC_CTG_CD, GR_WG_CD, GR_YM, GR_AC_DT,
					GR_MNG_DPT_CD, GR_ITM_CD, GR_ITM_SUB1, GR_ITM_SUB2, GR_ITM_SUB3,
					GR_LOT_NO, GR_SUBLOT_NO, GR_SNO1, GR_SNO2, GR_SNO3, GR_SNO4,
					GR_COST_IO_TYP, GR_AC_SLIP_TYP, GR_AC_RSN_CD,
					GR_BP_CD, GR_STK_BP_CD, GR_ASST_TYP,
					GR_QTY, GR_AMT,
					GR_TRD_CUR_CD, GR_TRD_CUR_AMT, GR_XRATE,
					GR_TRD_GRP, GR_REC_EVAL_TYP, GR_CALC_SEQ, GR_ZERO_EFFECT_FLG
					)
				VALUES	(
					x2.ACT_IO_ID, x2.ACT_IO_ID_SUB,
					x2.CALC_CTG_CD, x2.WG_CD, x2.YM, x2.AC_DT,
					x2.MNG_DPT_CD, x2.ITM_CD, x2.ITM_SUB1, x2.ITM_SUB2, x2.ITM_SUB3,
					x2.LOT_NO, x2.SUBLOT_NO, x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
					x2.COST_IO_TYP, x2.AC_SLIP_TYP, L_RSN,
					x2.BP_CD, x2.STK_BP_CD, x2.ASST_TYP,
					(-1) * x2.QTY, (-1) * x2.AMT,
					x2.TRD_CUR_CD, (-1) * x2.TRD_CUR_AMT, x2.XRATE,
					x2.TRD_GRP, x2.REC_EVAL_TYP, x2.CALC_SEQ, x2.ZERO_EFFECT_FLG,
					x1.ACT_IO_ID, x1.ACT_IO_ID_SUB,
					x1.CALC_CTG_CD, x1.WG_CD, x1.YM, x1.AC_DT,
					x1.MNG_DPT_CD, x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
					x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
					x1.COST_IO_TYP, x1.AC_SLIP_TYP, L_RSN,
					x1.BP_CD, x1.STK_BP_CD, x1.ASST_TYP,
					(-1) * x1.QTY, (-1) * x1.AMT,
					x1.TRD_CUR_CD, (-1) * x1.TRD_CUR_AMT, x1.XRATE,
					x1.TRD_GRP, x1.REC_EVAL_TYP, x1.CALC_SEQ, x1.ZERO_EFFECT_FLG
					) ;
			END IF ;
		END LOOP ;
	END LOOP ;

	DELETE	MGW_IO w
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
	AND	w.TRD_GRP IS NOT NULL
	;

	--MGW_WIO2からMGW_IOへ作成
	i := 0 ;
	REC_IO.DELETE ;
	FOR x3 IN (
		SELECT	MAX(w.GI_ACT_IO_ID) GI_ACT_IO_ID,
			w.GI_CALC_CTG_CD, w.GI_WG_CD, w.GI_YM, MAX(w.GI_AC_DT) GI_AC_DT,
			w.GI_MNG_DPT_CD, w.GI_ITM_CD, w.GI_ITM_SUB1, w.GI_ITM_SUB2, w.GI_ITM_SUB3,
			w.GI_LOT_NO, w.GI_SUBLOT_NO, w.GI_SNO1, w.GI_SNO2, w.GI_SNO3, w.GI_SNO4,
			w.GI_AC_SLIP_TYP, w.GI_AC_RSN_CD,
			w.GI_BP_CD, w.GI_STK_BP_CD, w.GI_ASST_TYP,
			SUM(w.GI_QTY) GI_QTY, SUM(w.GI_AMT) GI_AMT,
			w.GI_TRD_CUR_CD, SUM(w.GI_TRD_CUR_AMT) GI_TRD_CUR_AMT, w.GI_XRATE,
			MAX(w.GI_TRD_GRP) GI_TRD_GRP, w.GI_REC_EVAL_TYP,
			w.GI_CALC_SEQ, w.GI_ZERO_EFFECT_FLG,
			MAX(w.GR_ACT_IO_ID) GR_ACT_IO_ID,
			w.GR_CALC_CTG_CD, w.GR_WG_CD, w.GR_YM, MAX(w.GR_AC_DT) GR_AC_DT,
			w.GR_MNG_DPT_CD, w.GR_ITM_CD, w.GR_ITM_SUB1, w.GR_ITM_SUB2, w.GR_ITM_SUB3,
			w.GR_LOT_NO, w.GR_SUBLOT_NO, w.GR_SNO1, w.GR_SNO2, w.GR_SNO3, w.GR_SNO4,
			w.GR_AC_SLIP_TYP, w.GR_AC_RSN_CD,
			w.GR_BP_CD, w.GR_STK_BP_CD, w.GR_ASST_TYP,
			SUM(w.GR_QTY) GR_QTY, SUM(w.GR_AMT) GR_AMT,
			w.GR_TRD_CUR_CD, SUM(w.GR_TRD_CUR_AMT) GR_TRD_CUR_AMT, w.GR_XRATE,
			MAX(w.GR_TRD_GRP) GR_TRD_GRP, w.GR_REC_EVAL_TYP,
			w.GR_CALC_SEQ, w.GR_ZERO_EFFECT_FLG
		FROM	MGW_WIO2 w
		WHERE	0=0
		GROUP BY w.GI_CALC_CTG_CD, w.GI_WG_CD, w.GI_YM,
			w.GI_MNG_DPT_CD, w.GI_ITM_CD, w.GI_ITM_SUB1, w.GI_ITM_SUB2, w.GI_ITM_SUB3,
			w.GI_LOT_NO, w.GI_SUBLOT_NO, w.GI_SNO1, w.GI_SNO2, w.GI_SNO3, w.GI_SNO4,
			w.GI_AC_SLIP_TYP, w.GI_AC_RSN_CD,
			w.GI_BP_CD, w.GI_STK_BP_CD, w.GI_ASST_TYP,
			w.GI_TRD_CUR_CD, w.GI_XRATE, w.GI_REC_EVAL_TYP,
			w.GI_CALC_SEQ, w.GI_ZERO_EFFECT_FLG,
			w.GR_CALC_CTG_CD, w.GR_WG_CD, w.GR_YM,
			w.GR_MNG_DPT_CD, w.GR_ITM_CD, w.GR_ITM_SUB1, w.GR_ITM_SUB2, w.GR_ITM_SUB3,
			w.GR_LOT_NO, w.GR_SUBLOT_NO, w.GR_SNO1, w.GR_SNO2, w.GR_SNO3, w.GR_SNO4,
			w.GR_AC_SLIP_TYP, w.GR_AC_RSN_CD,
			w.GR_BP_CD, w.GR_STK_BP_CD, w.GR_ASST_TYP,
			w.GR_TRD_CUR_CD, w.GR_XRATE, w.GR_REC_EVAL_TYP,
			w.GR_CALC_SEQ, w.GR_ZERO_EFFECT_FLG
		)
	LOOP
		IF x3.GI_WG_CD <> I_WG_CD THEN
			GOTO SKIP_OUT ;
		END IF ;

		i := i + 1 ;
		--出庫関連
		REC_IO(i).ACT_IO_ID	:= x3.GI_ACT_IO_ID ;
		REC_IO(i).CALC_CTG_CD	:= x3.GI_CALC_CTG_CD ;
		REC_IO(i).WG_CD		:= x3.GI_WG_CD ;
		REC_IO(i).YM		:= x3.GI_YM ;
		REC_IO(i).AC_DT		:= x3.GI_AC_DT ;
		REC_IO(i).MNG_DPT_CD	:= x3.GI_MNG_DPT_CD ;
		REC_IO(i).ITM_CD	:= x3.GI_ITM_CD ;
		REC_IO(i).ITM_SUB1	:= x3.GI_ITM_SUB1 ;
		REC_IO(i).ITM_SUB2	:= x3.GI_ITM_SUB2 ;
		REC_IO(i).ITM_SUB3	:= x3.GI_ITM_SUB3 ;
		REC_IO(i).LOT_NO	:= x3.GI_LOT_NO ;
		REC_IO(i).SUBLOT_NO	:= x3.GI_SUBLOT_NO ;
		REC_IO(i).SNO1		:= x3.GI_SNO1 ;
		REC_IO(i).SNO2		:= x3.GI_SNO2 ;
		REC_IO(i).SNO3		:= x3.GI_SNO3 ;
		REC_IO(i).SNO4		:= x3.GI_SNO4 ;
		REC_IO(i).AC_RSN_CD	:= x3.GI_AC_RSN_CD ;
		REC_IO(i).OTHER_WG_CD	:= x3.GR_WG_CD ;
		REC_IO(i).OTHER_DPT_CD	:= x3.GR_MNG_DPT_CD ;
		REC_IO(i).BP_CD		:= x3.GI_BP_CD ;
		REC_IO(i).STK_BP_CD	:= x3.GI_STK_BP_CD ;
		REC_IO(i).ASST_TYP	:= x3.GI_ASST_TYP ;
		REC_IO(i).TRD_CUR_CD	:= x3.GI_TRD_CUR_CD ;
		REC_IO(i).XRATE		:= x3.GI_XRATE ;
		REC_IO(i).TRD_GRP	:= x3.GI_TRD_GRP ;
		REC_IO(i).REC_EVAL_TYP	:= x3.GI_REC_EVAL_TYP ;
		REC_IO(i).ITM_JNL_CD	:= C_NULL_VAL ;
		REC_IO(i).ALC_AMT_FLG	:= C_OFF ;
		REC_IO(i).ZERO_EFFECT_FLG := x3.GI_ZERO_EFFECT_FLG ;

		IF x3.GI_CALC_SEQ = x3.GR_CALC_SEQ
			AND	(
				x3.GI_AC_SLIP_TYP = C_PROD_ITM_SO AND x3.GI_QTY >= 0
				OR
				x3.GI_AC_SLIP_TYP = C_PROD_ITM_RET_SO AND x3.GI_QTY > 0
				)
			OR
			x3.GI_CALC_SEQ < x3.GR_CALC_SEQ
		THEN
			--出庫関連をC_IO_STK_OUTで作成する
			REC_IO(i).ACT_IO_ID_SUB	:= '1' ;
			REC_IO(i).COST_IO_TYP := C_IO_STK_OUT ;
			IF x3.GI_ASST_TYP = C_ASST2 THEN
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_SO ;
			ELSE
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_RET_SO ;
			END IF ;
			REC_IO(i).QTY := x3.GI_QTY ;
			REC_IO(i).AMT := x3.GI_AMT ;
			REC_IO(i).TRD_CUR_AMT := x3.GI_TRD_CUR_AMT ;
		ELSE
			--出庫関連をC_IO_STK_INで作成する
			REC_IO(i).ACT_IO_ID_SUB	:= '2' ;
			REC_IO(i).COST_IO_TYP := C_IO_STK_IN ;
			IF x3.GI_ASST_TYP = C_ASST1 THEN
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_SO ;
			ELSE
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_RET_SO ;
			END IF ;
			REC_IO(i).QTY := (-1) * x3.GI_QTY ;
			REC_IO(i).AMT := (-1) * x3.GI_AMT ;
			REC_IO(i).TRD_CUR_AMT := (-1) * x3.GI_TRD_CUR_AMT ;
		END IF ;

		<<SKIP_OUT>>

		IF x3.GR_WG_CD <> I_WG_CD THEN
			GOTO SKIP_IN ;
		END IF ;

		i := i + 1 ;
		--入庫関連
		REC_IO(i).ACT_IO_ID	:= x3.GR_ACT_IO_ID ;
		REC_IO(i).CALC_CTG_CD	:= x3.GR_CALC_CTG_CD ;
		REC_IO(i).WG_CD		:= x3.GR_WG_CD ;
		REC_IO(i).YM		:= x3.GR_YM ;
		REC_IO(i).AC_DT		:= x3.GR_AC_DT ;
		REC_IO(i).MNG_DPT_CD	:= x3.GR_MNG_DPT_CD ;
		REC_IO(i).ITM_CD	:= x3.GR_ITM_CD ;
		REC_IO(i).ITM_SUB1	:= x3.GR_ITM_SUB1 ;
		REC_IO(i).ITM_SUB2	:= x3.GR_ITM_SUB2 ;
		REC_IO(i).ITM_SUB3	:= x3.GR_ITM_SUB3 ;
		REC_IO(i).LOT_NO	:= x3.GR_LOT_NO ;
		REC_IO(i).SUBLOT_NO	:= x3.GR_SUBLOT_NO ;
		REC_IO(i).SNO1		:= x3.GR_SNO1 ;
		REC_IO(i).SNO2		:= x3.GR_SNO2 ;
		REC_IO(i).SNO3		:= x3.GR_SNO3 ;
		REC_IO(i).SNO4		:= x3.GR_SNO4 ;
		REC_IO(i).AC_RSN_CD	:= x3.GR_AC_RSN_CD ;
		REC_IO(i).OTHER_WG_CD	:= x3.GI_WG_CD ;
		REC_IO(i).OTHER_DPT_CD	:= x3.GI_MNG_DPT_CD ;
		REC_IO(i).BP_CD		:= x3.GR_BP_CD ;
		REC_IO(i).STK_BP_CD	:= x3.GR_STK_BP_CD ;
		REC_IO(i).ASST_TYP	:= x3.GR_ASST_TYP ;
		REC_IO(i).TRD_CUR_CD	:= x3.GR_TRD_CUR_CD ;
		REC_IO(i).XRATE		:= x3.GR_XRATE ;
		REC_IO(i).TRD_GRP	:= x3.GR_TRD_GRP ;
		REC_IO(i).REC_EVAL_TYP	:= x3.GR_REC_EVAL_TYP ;
		REC_IO(i).ITM_JNL_CD	:= C_NULL_VAL ;
		REC_IO(i).ALC_AMT_FLG	:= C_OFF ;
		REC_IO(i).ZERO_EFFECT_FLG := x3.GR_ZERO_EFFECT_FLG ;

		IF x3.GI_CALC_SEQ = x3.GR_CALC_SEQ
			AND	(
				x3.GR_AC_SLIP_TYP = C_PROD_ITM_SO AND x3.GR_QTY >= 0
				OR
				x3.GR_AC_SLIP_TYP = C_PROD_ITM_RET_SO AND x3.GR_QTY > 0
				)
			OR
			x3.GI_CALC_SEQ < x3.GR_CALC_SEQ
		THEN
			--入庫関連をC_IO_STK_INで作成する
			REC_IO(i).ACT_IO_ID_SUB	:= '2' ;
			REC_IO(i).COST_IO_TYP := C_IO_STK_IN ;
			IF x3.GR_ASST_TYP = C_ASST1 THEN
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_SO ;
			ELSE
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_RET_SO ;
			END IF ;
			REC_IO(i).QTY := x3.GR_QTY ;
			REC_IO(i).AMT := x3.GR_AMT ;
			REC_IO(i).TRD_CUR_AMT := x3.GR_TRD_CUR_AMT ;
		ELSE
			--入庫関連をC_IO_STK_OUTで作成する
			REC_IO(i).ACT_IO_ID_SUB	:= '1' ;
			REC_IO(i).COST_IO_TYP := C_IO_STK_OUT ;
			IF x3.GR_ASST_TYP = C_ASST2 THEN
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_SO ;
			ELSE
				REC_IO(i).AC_SLIP_TYP := C_PROD_ITM_RET_SO ;
			END IF ;
			REC_IO(i).QTY := (-1) * x3.GR_QTY ;
			REC_IO(i).AMT := (-1) * x3.GR_AMT ;
			REC_IO(i).TRD_CUR_AMT := (-1) * x3.GR_TRD_CUR_AMT ;
		END IF ;

		<<SKIP_IN>>

		IF i > C_MAX_CNT THEN
			INS_MGW_IO() ;
		END IF ;
	END LOOP ;

	IF i > 0 THEN
		INS_MGW_IO() ;
	END IF ;

	DELETE	MGW_IO w
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
	AND	w.TRD_GRP IS NULL
	AND	w.WG_CD <> I_WG_CD
	;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IFSUB2') ;

END P_IFSUB2 ;

PROCEDURE P_IFSUB3 (
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	部門間移動の入出庫実績を集計する
<REMARKS>
	１．部門間移動の入出庫実績をまとめる
	２．まとめた結果マイナス数量となったときは符号を反転し、管理部門と相手部門を入れ替える
	３．計算順序の小さいＷＧから大きいＷＧへ移動するようなデータを作成する

	TMP_DPT_CDが設定されているときは、部門間出庫のレコードを出庫元部門から
	TMP_DPT_CDへの出庫、TMP_DPT_CDから相手部門への出庫のレコードを作成後に集計する
<ARGUMENTS>
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_CNT		NUMBER ;
	L_ROWID		ROWID ;

	L_WG		MGT_ACT_IO.WG_CD%TYPE ;
	L_DPT		MGT_ACT_IO.MNG_DPT_CD%TYPE ;
/*************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IFSUB3') ;

	IF G_TMP_DPT IS NULL THEN
		GOTO SKIP_DPT ;
	END IF ;

	--G_TMP_DPTがNOT NULLのときはG_TMP_DPTを中継する振替とする
	FOR x IN (
		SELECT	w.ROWID		ROW_ID,
			w.ACT_IO_ID, w.ACT_IO_ID_SUB,
			w.CALC_CTG_CD, w.WG_CD, w.YM, w.AC_DT,
			w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.COST_IO_TYP, w.AC_SLIP_TYP, w.AC_RSN_CD,
			w.OTHER_WG_CD, w.OTHER_DPT_CD,
			w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
			w.QTY, w.AMT,
			w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
			w.TRD_GRP, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG,
			NVL(m1.CALC_SEQ, 0)	CALC_SEQ,
			NVL(m2.CALC_SEQ, 0)	OTHER_CALC_SEQ
		FROM	MGW_IO w, MAM_WG m1, MAM_WG m2
		WHERE	0=0
		AND	w.YM = I_YM
		AND	w.AC_SLIP_TYP = C_DPT_XFR_SO
		AND	(w.WG_CD = I_WG_CD OR w.OTHER_WG_CD = I_WG_CD)
		AND	(w.WG_CD <> w.OTHER_WG_CD OR w.MNG_DPT_CD <> w.OTHER_DPT_CD)
		AND	w.ZERO_EFFECT_FLG = C_OFF
		AND	w.WG_CD = m1.WG_CD(+)
		AND	m1.DEL_FLG(+) = C_OFF
		AND	w.OTHER_WG_CD = m2.WG_CD(+)
		AND	m2.DEL_FLG(+) = C_OFF
		)
	LOOP
		IF x.CALC_SEQ <> x.OTHER_CALC_SEQ THEN
			GOTO SKIP_TMP_DPT ;
		END IF ;

		INSERT INTO MGW_IO (
			ACT_IO_ID, ACT_IO_ID_SUB,
			CALC_CTG_CD, WG_CD, YM, AC_DT,
			MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
			LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
			COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
			OTHER_WG_CD, OTHER_DPT_CD,
			BP_CD, STK_BP_CD, ASST_TYP,
			QTY, AMT,
			TRD_CUR_CD, TRD_CUR_AMT, XRATE,
			TRD_GRP, REC_EVAL_TYP, ZERO_EFFECT_FLG,
			ITM_JNL_CD
			)
		VALUES	(
			x.ACT_IO_ID, 'X',
			x.CALC_CTG_CD, x.OTHER_WG_CD, x.YM, x.AC_DT,
			G_TMP_DPT, x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.COST_IO_TYP, x.AC_SLIP_TYP, x.AC_RSN_CD,
			x.OTHER_WG_CD, x.OTHER_DPT_CD,
			x.BP_CD, x.STK_BP_CD, x.ASST_TYP,
			x.QTY, x.AMT,
			x.TRD_CUR_CD, x.TRD_CUR_AMT, x.XRATE,
			C_STR_TRD || x.TRD_GRP, x.REC_EVAL_TYP, x.ZERO_EFFECT_FLG,
			C_NULL_VAL
			)
		;

		UPDATE	MGW_IO w
		SET	w.OTHER_WG_CD = x.WG_CD,
			w.OTHER_DPT_CD = G_TMP_DPT
		WHERE	w.ROWID = x.ROW_ID
		;

		<<SKIP_TMP_DPT>>
			NULL ;
	END LOOP ;

	<<SKIP_DPT>>
		NULL ;

	DELETE MGW_WIO w ;

	FOR y IN (
		SELECT	t.*,
			NVL(m1.CALC_SEQ, 0)	CALC_SEQ,
			NVL(m2.CALC_SEQ, 0)	OTHER_CALC_SEQ
		FROM	(
			SELECT	MAX(w.ACT_IO_ID)	ACT_IO_ID,
				MAX(w.ACT_IO_ID_SUB)	ACT_IO_ID_SUB,
				w.CALC_CTG_CD, w.WG_CD, w.YM,
				MAX(w.AC_DT)	AC_DT,
				w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
				w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
				w.COST_IO_TYP, w.AC_SLIP_TYP, w.AC_RSN_CD,
				w.OTHER_WG_CD, w.OTHER_DPT_CD,
				w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
				SUM(w.QTY)	QTY,
				SUM(w.AMT)	AMT,
				w.TRD_CUR_CD,
				SUM(w.TRD_CUR_AMT)	TRD_CUR_AMT,
				w.XRATE,
				MAX(w.TRD_GRP)	TRD_GRP,
				w.REC_EVAL_TYP,
				w.ZERO_EFFECT_FLG
			FROM	MGW_IO w
			WHERE	0=0
			AND	w.YM = I_YM
			AND	w.AC_SLIP_TYP = C_DPT_XFR_SO
			AND	(w.WG_CD = I_WG_CD OR w.OTHER_WG_CD = I_WG_CD)
			AND	(w.WG_CD <> w.OTHER_WG_CD OR w.MNG_DPT_CD <> w.OTHER_DPT_CD)
			AND	w.ZERO_EFFECT_FLG = C_OFF
			GROUP BY w.CALC_CTG_CD, w.WG_CD, w.YM,
				w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
				w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
				w.COST_IO_TYP, w.AC_SLIP_TYP, w.AC_RSN_CD,
				w.OTHER_WG_CD, w.OTHER_DPT_CD,
				w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
				w.TRD_CUR_CD,
				w.XRATE,
				w.REC_EVAL_TYP,
				w.ZERO_EFFECT_FLG
			) t,
			MAM_WG m1, MAM_WG m2
		WHERE	0=0
		AND	t.WG_CD = m1.WG_CD(+)
		AND	m1.DEL_FLG(+) = C_OFF
		AND	t.OTHER_WG_CD = m2.WG_CD(+)
		AND	m2.DEL_FLG(+) = C_OFF
		ORDER BY ABS(t.QTY) DESC, t.ACT_IO_ID, t.ACT_IO_ID_SUB --数量の大きい(絶対値)データから処理
		)
	LOOP
		IF y.QTY < 0 THEN
			L_WG := y.WG_CD ;
			L_DPT := y.MNG_DPT_CD ;
			y.WG_CD := y.OTHER_WG_CD ;
			y.MNG_DPT_CD := y.OTHER_DPT_CD ;
			y.OTHER_WG_CD := L_WG ;
			y.OTHER_DPT_CD := L_DPT ;
			y.QTY := y.QTY * -1 ;
			y.AMT := y.AMT * -1 ;
			y.TRD_CUR_AMT := y.TRD_CUR_AMT * -1 ;
		END IF ;

		L_CNT := 0 ;
		L_ROWID := NULL ;
		FOR y2 IN (
			SELECT	w.ROWID		ROW_ID,
				w.AC_RSN_CD
			FROM	MGW_WIO w
			WHERE	0=0
			AND	w.CALC_CTG_CD	= y.CALC_CTG_CD
			AND	w.WG_CD	= y.OTHER_WG_CD
			AND	w.MNG_DPT_CD	= y.OTHER_DPT_CD
			AND	w.OTHER_WG_CD = y.WG_CD
			AND	w.OTHER_DPT_CD	= y.MNG_DPT_CD
			AND	w.YM		= y.YM
			AND	w.ITM_CD	= y.ITM_CD
			AND	w.ITM_SUB1	= y.ITM_SUB1
			AND	w.ITM_SUB2	= y.ITM_SUB2
			AND	w.ITM_SUB3	= y.ITM_SUB3
			AND	w.LOT_NO	= y.LOT_NO
			AND	w.SUBLOT_NO	= y.SUBLOT_NO
			AND	w.SNO1		= y.SNO1
			AND	w.SNO2		= y.SNO2
			AND	w.SNO3		= y.SNO3
			AND	w.SNO4		= y.SNO4
			AND	(w.BP_CD = y.BP_CD OR w.BP_CD IS NULL AND y.BP_CD IS NULL)
			AND	(w.STK_BP_CD = y.STK_BP_CD OR w.STK_BP_CD IS NULL AND y.STK_BP_CD IS NULL)
			AND	w.ASST_TYP	= y.ASST_TYP
			AND	(w.TRD_CUR_CD = y.TRD_CUR_CD OR w.TRD_CUR_CD IS NULL AND y.TRD_CUR_CD IS NULL)
			AND	(w.XRATE = y.XRATE OR w.XRATE IS NULL AND y.XRATE IS NULL)
			)
		LOOP
			IF NVL(y.AC_RSN_CD, C_NULL_VAL) = NVL(y2.AC_RSN_CD, C_NULL_VAL) OR L_CNT = 0 THEN
				L_ROWID := y2.ROW_ID ;
				IF L_CNT > 0 THEN
					EXIT ;
				END IF ;
			END IF ;
			L_CNT := L_CNT + 1 ;
		END LOOP ;

		IF L_ROWID IS NULL THEN
			INSERT INTO MGW_WIO (
				ACT_IO_ID, ACT_IO_ID_SUB,
				CALC_CTG_CD, WG_CD, YM, AC_DT,
				MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
				LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
				COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
				OTHER_WG_CD, OTHER_DPT_CD,
				BP_CD, STK_BP_CD, ASST_TYP,
				QTY, AMT,
				TRD_CUR_CD, TRD_CUR_AMT, XRATE,
				TRD_GRP, REC_EVAL_TYP,
				CALC_SEQ, OTHER_CALC_SEQ, ZERO_EFFECT_FLG
				)
			VALUES	(
				y.ACT_IO_ID, y.ACT_IO_ID_SUB,
				y.CALC_CTG_CD, y.WG_CD, y.YM, y.AC_DT,
				y.MNG_DPT_CD, y.ITM_CD, y.ITM_SUB1, y.ITM_SUB2, y.ITM_SUB3,
				y.LOT_NO, y.SUBLOT_NO, y.SNO1, y.SNO2, y.SNO3, y.SNO4,
				y.COST_IO_TYP, y.AC_SLIP_TYP, y.AC_RSN_CD,
				y.OTHER_WG_CD, y.OTHER_DPT_CD,
				y.BP_CD, y.STK_BP_CD, y.ASST_TYP,
				y.QTY, y.AMT,
				y.TRD_CUR_CD, y.TRD_CUR_AMT, y.XRATE,
				y.TRD_GRP, y.REC_EVAL_TYP,
				y.CALC_SEQ, y.OTHER_CALC_SEQ, y.ZERO_EFFECT_FLG
				)
				;
		ELSE
			UPDATE	MGW_WIO w
			SET	w.QTY = w.QTY + (-1) * y.QTY,
				w.AMT = DECODE(w.AMT, NULL,
						(-1) * y.AMT,
						w.AMT + (-1) * NVL(y.AMT, 0)),
				w.TRD_CUR_AMT = DECODE(w.TRD_CUR_AMT, NULL,
							(-1) * y.TRD_CUR_AMT,
							w.TRD_CUR_AMT + (-1) * NVL(y.TRD_CUR_AMT, 0))
			WHERE	0=0
			AND	w.ROWID = L_ROWID
			;
		END IF ;
	END LOOP ;

	INSERT INTO MGW_WIO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP,
		CALC_SEQ, OTHER_CALC_SEQ, ZERO_EFFECT_FLG
		)
	SELECT	w.ACT_IO_ID, w.ACT_IO_ID_SUB,
		w.CALC_CTG_CD, w.WG_CD, w.YM, w.AC_DT,
		w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
		w.COST_IO_TYP, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.OTHER_WG_CD, w.OTHER_DPT_CD,
		w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
		w.QTY, w.AMT,
		w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP,
		NVL(m1.CALC_SEQ, 0), NVL(m2.CALC_SEQ, 0), w.ZERO_EFFECT_FLG
	FROM	MGW_IO w, MAM_WG m1, MAM_WG m2
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.AC_SLIP_TYP = C_DPT_XFR_SO
	AND	(w.WG_CD = I_WG_CD OR w.OTHER_WG_CD = I_WG_CD)
	AND	(w.WG_CD <> w.OTHER_WG_CD OR w.MNG_DPT_CD <> w.OTHER_DPT_CD)
	AND	w.ZERO_EFFECT_FLG = C_ON
	AND	w.WG_CD = m1.WG_CD(+)
	AND	m1.DEL_FLG(+) = C_OFF
	AND	w.OTHER_WG_CD = m2.WG_CD(+)
	AND	m2.DEL_FLG(+) = C_OFF
	;

	DELETE	MGW_IO w
	WHERE	w.YM = I_YM
	AND	w.AC_SLIP_TYP = C_DPT_XFR_SO
	;

	-- 同じ計算順序で数量が０以上または異なる計算順序で出庫元の計算順序が小さい場合の出庫データ
	INSERT INTO MGW_IO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, ZERO_EFFECT_FLG,
		ITM_JNL_CD
		)
	SELECT	w.ACT_IO_ID, '1' || w.ACT_IO_ID_SUB,
		w.CALC_CTG_CD, w.WG_CD, w.YM, w.AC_DT,
		w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
		C_IO_STK_OUT, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.OTHER_WG_CD, w.OTHER_DPT_CD,
		w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
		w.QTY, w.AMT,
		w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG,
		C_NULL_VAL
	FROM	MGW_WIO w
	WHERE	0=0
	AND	w.WG_CD = I_WG_CD
	AND	(w.CALC_SEQ = w.OTHER_CALC_SEQ AND w.QTY >= 0 OR w.CALC_SEQ < w.OTHER_CALC_SEQ)
	;

	-- 同じ計算順序で数量が０以上または異なる計算順序で出庫元の計算順序が小さい場合の入庫データ
	INSERT INTO MGW_IO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, ZERO_EFFECT_FLG,
		ITM_JNL_CD
		)
	SELECT	w.ACT_IO_ID, '2' || w.ACT_IO_ID_SUB,
		w.CALC_CTG_CD, w.OTHER_WG_CD, w.YM, w.AC_DT,
		w.OTHER_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
		C_IO_STK_IN, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.WG_CD, w.MNG_DPT_CD,
		w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
		w.QTY, w.AMT,
		w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG,
		C_NULL_VAL
	FROM	MGW_WIO w
	WHERE	0=0
	AND	w.OTHER_WG_CD = I_WG_CD
	AND	(w.CALC_SEQ = w.OTHER_CALC_SEQ AND w.QTY >= 0 OR w.CALC_SEQ < w.OTHER_CALC_SEQ)
	;

	-- 同じ計算順序で数量が０未満または異なる計算順序で出庫元の計算順序が大きい場合の出庫データ
	INSERT INTO MGW_IO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, ZERO_EFFECT_FLG,
		ITM_JNL_CD
		)
	SELECT	w.ACT_IO_ID, '1' || w.ACT_IO_ID_SUB,
		w.CALC_CTG_CD, w.OTHER_WG_CD, w.YM, w.AC_DT,
		w.OTHER_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
		C_IO_STK_OUT, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.WG_CD, w.MNG_DPT_CD,
		w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
		(-1) * w.QTY, (-1) * w.AMT,
		w.TRD_CUR_CD, (-1) * w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG,
		C_NULL_VAL
	FROM	MGW_WIO w
	WHERE	0=0
	AND	w.OTHER_WG_CD = I_WG_CD
	AND	(w.CALC_SEQ = w.OTHER_CALC_SEQ AND w.QTY < 0 OR w.CALC_SEQ > w.OTHER_CALC_SEQ)
	;

	-- 同じ計算順序で数量が０未満または異なる計算順序で出庫元の計算順序が大きい場合の入庫データ
	INSERT INTO MGW_IO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD, OTHER_DPT_CD,
		BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, REC_EVAL_TYP, ZERO_EFFECT_FLG,
		ITM_JNL_CD
		)
	SELECT	w.ACT_IO_ID, '2' || w.ACT_IO_ID_SUB,
		w.CALC_CTG_CD, w.WG_CD, w.YM, w.AC_DT,
		w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
		w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
		C_IO_STK_IN, w.AC_SLIP_TYP, w.AC_RSN_CD,
		w.OTHER_WG_CD, w.OTHER_DPT_CD,
		w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
		(-1) * w.QTY, (-1) * w.AMT,
		w.TRD_CUR_CD, (-1) * w.TRD_CUR_AMT, w.XRATE,
		w.TRD_GRP, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG,
		C_NULL_VAL
	FROM	MGW_WIO w
	WHERE	0=0
	AND	w.WG_CD = I_WG_CD
	AND	(w.CALC_SEQ = w.OTHER_CALC_SEQ AND w.QTY < 0 OR w.CALC_SEQ > w.OTHER_CALC_SEQ)
	;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IFSUB3') ;

END P_IFSUB3 ;

PROCEDURE P_IFSUB4 (
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	品目間振替の入出庫実績を集計する
<REMARKS>
	１．同一の振替情報は出庫数から入庫数を差し引く
	２．品目振替をまとめる
<ARGUMENTS>
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_QTY_S		MAPA_META.QTY%TYPE ;
	L_AMT_S		MAPA_META.MONEY%TYPE ;
	L_TAMT_S	MAPA_META.MONEY%TYPE ;

	L_CNT		NUMBER ;
	L_CNT2		NUMBER ;

	L_TMP		MGW_IO%ROWTYPE ;
	L_RSN		MAPA_META.AC_RSN_CD%TYPE ;
/************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IFSUB4') ;

	--同一の振替情報は出庫数から入庫数を差し引く
	FOR x1 IN (
		SELECT	w.ROWID	ROW_ID,
			w.CALC_CTG_CD, w.WG_CD, w.YM,
			w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
			w.QTY, w.AMT,
			w.TRD_CUR_CD, w.TRD_CUR_AMT, w.XRATE,
			w.TRD_GRP
		FROM	MGW_IO w
		WHERE	0=0
		AND	w.YM = I_YM
		AND	w.TRD_GRP IS NOT NULL
		AND	w.AC_SLIP_TYP = C_STK_SW_SO
		AND	w.ZERO_EFFECT_FLG = C_OFF
		)
	LOOP
		L_QTY_S := x1.QTY ;
		L_AMT_S := x1.AMT ;
		L_TAMT_S := x1.TRD_CUR_AMT ;

		FOR x2 IN (
			SELECT	w.ROWID	ROW_ID,
				w.QTY,
				w.AMT,
				w.TRD_CUR_AMT
			FROM	MGW_IO w
			WHERE	0=0
			AND	w.CALC_CTG_CD	= x1.CALC_CTG_CD
			AND	w.WG_CD		= x1.WG_CD
			AND	w.MNG_DPT_CD	= x1.MNG_DPT_CD
			AND	w.YM		= x1.YM
			AND	w.ITM_CD	= x1.ITM_CD
			AND	w.ITM_SUB1	= x1.ITM_SUB1
			AND	w.ITM_SUB2	= x1.ITM_SUB2
			AND	w.ITM_SUB3	= x1.ITM_SUB3
			AND	w.LOT_NO	= x1.LOT_NO
			AND	w.SUBLOT_NO	= x1.SUBLOT_NO
			AND	w.SNO1		= x1.SNO1
			AND	w.SNO2		= x1.SNO2
			AND	w.SNO3		= x1.SNO3
			AND	w.SNO4		= x1.SNO4
			AND	(w.BP_CD = x1.BP_CD OR w.BP_CD IS NULL AND x1.BP_CD IS NULL)
			AND	(w.STK_BP_CD = x1.STK_BP_CD OR w.STK_BP_CD IS NULL AND x1.STK_BP_CD IS NULL)
			AND	w.ASST_TYP = x1.ASST_TYP
			AND	(w.TRD_CUR_CD = x1.TRD_CUR_CD OR w.TRD_CUR_CD IS NULL AND x1.TRD_CUR_CD IS NULL)
			AND	(w.XRATE = x1.XRATE OR w.XRATE IS NULL AND x1.XRATE IS NULL)
			AND	w.TRD_GRP = x1.TRD_GRP
			AND	w.AC_SLIP_TYP = C_STK_SW_GR
			AND	w.ZERO_EFFECT_FLG = C_OFF
			)
		LOOP

			IF L_QTY_S < x2.QTY THEN
				L_QTY_S := x2.QTY - L_QTY_S ;

				IF L_AMT_S IS NULL THEN
					L_AMT_S := x2.AMT ;
				ELSE
					L_AMT_S := NVL(x2.AMT, 0) - L_AMT_S ;
				END IF ;

				IF L_TAMT_S IS NULL THEN
					L_TAMT_S := x2.TRD_CUR_AMT ;
				ELSE
					L_TAMT_S := NVL(x2.TRD_CUR_AMT, 0) - L_TAMT_S ;
				END IF ;

				UPDATE	MGW_IO w
				SET	w.QTY = L_QTY_S,
					w.AMT = L_AMT_S,
					w.TRD_CUR_AMT = L_TAMT_S
				WHERE	0=0
				AND	w.ROWID = x2.ROW_ID
				;

				L_QTY_S := 0 ;

				IF L_AMT_S IS NOT NULL THEN
					L_AMT_S := 0 ;
				END IF ;

				IF L_TAMT_S IS NOT NULL THEN
					L_TAMT_S := 0 ;
				END IF ;
			ELSE

				DELETE MGW_IO w WHERE w.ROWID = x2.ROW_ID ;
				L_QTY_S := L_QTY_S - x2.QTY ;

				IF L_AMT_S IS NULL THEN
					L_AMT_S := (-1) * x2.AMT ;
				ELSE
					L_AMT_S := L_AMT_S - NVL(x2.AMT, 0) ;
				END IF ;

				IF L_TAMT_S IS NULL THEN
					L_TAMT_S := (-1) * x2.TRD_CUR_AMT ;
				ELSE
					L_TAMT_S := L_TAMT_S - NVL(x2.TRD_CUR_AMT, 0) ;
				END IF ;

			END IF ;

			IF L_QTY_S = 0 AND (L_AMT_S IS NULL OR L_AMT_S = 0)
			AND (L_TAMT_S IS NULL OR L_TAMT_S = 0)
			THEN
				EXIT ;
			END IF ;

		END LOOP ;

		SELECT	COUNT(*)
		INTO	L_CNT
		FROM	MGW_IO w
		WHERE	0=0
		AND	w.YM = x1.YM
		AND	w.AC_SLIP_TYP = C_STK_SW_SO
		AND	w.ROWID <> x1.ROW_ID
		AND	w.TRD_GRP = x1.TRD_GRP
		AND	w.ZERO_EFFECT_FLG = C_OFF
		;

		IF L_CNT <> 0 AND L_QTY_S = 0
		AND (L_AMT_S IS NULL OR L_AMT_S = 0)
		AND (L_TAMT_S IS NULL OR L_TAMT_S = 0)
		THEN
			--入庫もなく数量も０のときは無効にする
			DELETE MGW_IO w WHERE w.ROWID = x1.ROW_ID ;
		ELSE
			--数量、金額を更新する
			UPDATE	MGW_IO w
			SET	w.QTY = L_QTY_S,
				w.AMT = L_AMT_S,
				w.TRD_CUR_AMT = L_TAMT_S
			WHERE	0=0
			AND	w.ROWID = x1.ROW_ID
			;
		END IF ;
	END LOOP ;

	DELETE MGW_WIO2 w ;

	--品目振替の集計
	FOR x1 IN (
		SELECT	w.*
		FROM	MGW_IO w
		WHERE	0=0
		AND	w.YM = I_YM
		AND	w.AC_SLIP_TYP = C_STK_SW_SO
		AND	w.TRD_GRP IS NOT NULL
		AND	w.ZERO_EFFECT_FLG = C_OFF
		ORDER BY ABS(w.QTY) DESC --数量の大きい(絶対値)データから処理
		)
	LOOP
		--1:1の振替のみ対応
		SELECT	SUM(DECODE(w.AC_SLIP_TYP, C_STK_SW_SO, 1, 0)),
			SUM(DECODE(w.AC_SLIP_TYP, C_STK_SW_GR, 1, 0))
		INTO	L_CNT, L_CNT2
		FROM	MGW_IO w
		WHERE	0=0
		AND	w.YM = x1.YM
		AND	w.AC_SLIP_TYP IN (C_STK_SW_SO, C_STK_SW_GR)
		AND	w.TRD_GRP = x1.TRD_GRP
		AND	w.ZERO_EFFECT_FLG = C_OFF
		AND	(x1.QTY >= 0 AND w.QTY >= 0 OR x1.QTY < 0 AND w.QTY < 0)
		;

		IF L_CNT = 1 AND L_CNT2 = 1 THEN
			--1:1はMGW_WIO2に作成する
			FOR x2 IN (
				SELECT	w.*
				FROM	MGW_IO w
				WHERE	0=0
				AND	w.YM = x1.YM
				AND	w.AC_SLIP_TYP = C_STK_SW_GR
				AND	w.TRD_GRP = x1.TRD_GRP
				AND	w.ZERO_EFFECT_FLG = C_OFF
				AND	(x1.QTY >= 0 AND w.QTY >= 0 OR x1.QTY < 0 AND w.QTY < 0)
				)
			LOOP
				IF x1.QTY < 0 AND x2.QTY < 0 THEN
					L_TMP := x1 ;
					x1 := x2 ;
					x2 := L_TMP ;
					x1.QTY := x1.QTY * -1 ;
					x2.QTY := x2.QTY * -1 ;
					x1.AMT := x1.AMT * -1 ;
					x2.AMT := x2.AMT * -1 ;
					x1.TRD_CUR_AMT := x1.TRD_CUR_AMT * -1 ;
					x2.TRD_CUR_AMT := x2.TRD_CUR_AMT * -1 ;
				END IF ;

				L_CNT := 0 ;
				L_RSN := NULL ;
				FOR x3 IN (
					SELECT	w.GI_AC_RSN_CD	AC_RSN_CD
					FROM	MGW_WIO2 w
					WHERE	0=0
					AND	w.GI_CALC_CTG_CD = x2.CALC_CTG_CD
					AND	w.GI_WG_CD = x2.WG_CD
					AND	w.GI_MNG_DPT_CD = x2.MNG_DPT_CD
					AND	w.GI_ITM_CD	= x2.ITM_CD
					AND	w.GI_ITM_SUB1	= x2.ITM_SUB1
					AND	w.GI_ITM_SUB2	= x2.ITM_SUB2
					AND	w.GI_ITM_SUB3	= x2.ITM_SUB3
					AND	w.GI_LOT_NO	= x2.LOT_NO
					AND	w.GI_SUBLOT_NO	= x2.SUBLOT_NO
					AND	w.GI_SNO1	= x2.SNO1
					AND	w.GI_SNO2	= x2.SNO2
					AND	w.GI_SNO3	= x2.SNO3
					AND	w.GI_SNO4	= x2.SNO4
					AND	(w.GI_BP_CD = x2.BP_CD OR w.GI_BP_CD IS NULL AND x2.BP_CD IS NULL)
					AND	(w.GI_STK_BP_CD = x2.STK_BP_CD OR w.GI_STK_BP_CD IS NULL AND x2.STK_BP_CD IS NULL)
					AND	w.GI_ASST_TYP	= x2.ASST_TYP
					AND	(w.GI_TRD_CUR_CD = x2.TRD_CUR_CD OR w.GI_TRD_CUR_CD IS NULL AND x2.TRD_CUR_CD IS NULL)
					AND	(w.GI_XRATE = x2.XRATE OR w.GI_XRATE IS NULL AND x2.XRATE IS NULL)
					AND	w.GR_CALC_CTG_CD = x1.CALC_CTG_CD
					AND	w.GR_WG_CD = x1.WG_CD
					AND	w.GR_MNG_DPT_CD	= x1.MNG_DPT_CD
					AND	w.GR_ITM_CD	= x1.ITM_CD
					AND	w.GR_ITM_SUB1	= x1.ITM_SUB1
					AND	w.GR_ITM_SUB2	= x1.ITM_SUB2
					AND	w.GR_ITM_SUB3	= x1.ITM_SUB3
					AND	w.GR_LOT_NO	= x1.LOT_NO
					AND	w.GR_SUBLOT_NO	= x1.SUBLOT_NO
					AND	w.GR_SNO1	= x1.SNO1
					AND	w.GR_SNO2	= x1.SNO2
					AND	w.GR_SNO3	= x1.SNO3
					AND	w.GR_SNO4	= x1.SNO4
					AND	(w.GR_BP_CD = x1.BP_CD OR w.GR_BP_CD IS NULL AND x1.BP_CD IS NULL)
					AND	(w.GR_STK_BP_CD = x1.STK_BP_CD OR w.GR_STK_BP_CD IS NULL AND x1.STK_BP_CD IS NULL)
					AND	w.GR_ASST_TYP	= x1.ASST_TYP
					AND	(w.GR_TRD_CUR_CD = x1.TRD_CUR_CD OR w.GR_TRD_CUR_CD IS NULL AND x1.TRD_CUR_CD IS NULL)
					AND	(w.GR_XRATE = x1.XRATE OR w.GR_XRATE IS NULL AND x1.XRATE IS NULL)
					)
				LOOP
					IF NVL(x2.AC_RSN_CD, C_NULL_VAL) = NVL(x3.AC_RSN_CD, C_NULL_VAL) OR L_CNT = 0 THEN
						L_RSN := x3.AC_RSN_CD ;
					END IF ;
					L_CNT := L_CNT + 1 ;
				END LOOP ;

				IF L_CNT = 0 THEN
					--相手が存在しない場合はそのまま作成する
					INSERT INTO MGW_WIO2 (
						GI_ACT_IO_ID, GI_ACT_IO_ID_SUB,
						GI_CALC_CTG_CD, GI_WG_CD, GI_YM, GI_AC_DT,
						GI_MNG_DPT_CD, GI_ITM_CD, GI_ITM_SUB1, GI_ITM_SUB2, GI_ITM_SUB3,
						GI_LOT_NO, GI_SUBLOT_NO, GI_SNO1, GI_SNO2, GI_SNO3, GI_SNO4,
						GI_COST_IO_TYP, GI_AC_SLIP_TYP, GI_AC_RSN_CD,
						GI_BP_CD, GI_STK_BP_CD, GI_ASST_TYP,
						GI_QTY, GI_AMT,
						GI_TRD_CUR_CD, GI_TRD_CUR_AMT, GI_XRATE,
						GI_TRD_GRP, GI_REC_EVAL_TYP, GI_ZERO_EFFECT_FLG,
						GR_ACT_IO_ID, GR_ACT_IO_ID_SUB,
						GR_CALC_CTG_CD, GR_WG_CD, GR_YM, GR_AC_DT,
						GR_MNG_DPT_CD, GR_ITM_CD, GR_ITM_SUB1, GR_ITM_SUB2, GR_ITM_SUB3,
						GR_LOT_NO, GR_SUBLOT_NO, GR_SNO1, GR_SNO2, GR_SNO3, GR_SNO4,
						GR_COST_IO_TYP, GR_AC_SLIP_TYP, GR_AC_RSN_CD,
						GR_BP_CD, GR_STK_BP_CD, GR_ASST_TYP,
						GR_QTY, GR_AMT,
						GR_TRD_CUR_CD, GR_TRD_CUR_AMT, GR_XRATE,
						GR_TRD_GRP, GR_REC_EVAL_TYP, GR_ZERO_EFFECT_FLG
						)
					VALUES	(
						x1.ACT_IO_ID, x1.ACT_IO_ID_SUB,
						x1.CALC_CTG_CD, x1.WG_CD, x1.YM, x1.AC_DT,
						x1.MNG_DPT_CD, x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
						x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
						x1.COST_IO_TYP, x1.AC_SLIP_TYP, x1.AC_RSN_CD,
						x1.BP_CD, x1.STK_BP_CD, x1.ASST_TYP,
						x1.QTY, x1.AMT,
						x1.TRD_CUR_CD, x1.TRD_CUR_AMT, x1.XRATE,
						x1.TRD_GRP, x1.REC_EVAL_TYP, x1.ZERO_EFFECT_FLG,
						x2.ACT_IO_ID, x2.ACT_IO_ID_SUB,
						x2.CALC_CTG_CD, x2.WG_CD, x2.YM, x2.AC_DT,
						x2.MNG_DPT_CD, x2.ITM_CD, x2.ITM_SUB1, x2.ITM_SUB2, x2.ITM_SUB3,
						x2.LOT_NO, x2.SUBLOT_NO, x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
						x2.COST_IO_TYP, x2.AC_SLIP_TYP, x2.AC_RSN_CD,
						x2.BP_CD, x2.STK_BP_CD, x2.ASST_TYP,
						x2.QTY, x2.AMT,
						x2.TRD_CUR_CD, x2.TRD_CUR_AMT, x2.XRATE,
						x2.TRD_GRP, x2.REC_EVAL_TYP, x2.ZERO_EFFECT_FLG
						) ;
				ELSE
					--相手が存在する場合は集計のため反転して作成する
					INSERT INTO MGW_WIO2 (
						GI_ACT_IO_ID, GI_ACT_IO_ID_SUB,
						GI_CALC_CTG_CD, GI_WG_CD, GI_YM, GI_AC_DT,
						GI_MNG_DPT_CD, GI_ITM_CD, GI_ITM_SUB1, GI_ITM_SUB2, GI_ITM_SUB3,
						GI_LOT_NO, GI_SUBLOT_NO, GI_SNO1, GI_SNO2, GI_SNO3, GI_SNO4,
						GI_COST_IO_TYP, GI_AC_SLIP_TYP, GI_AC_RSN_CD,
						GI_BP_CD, GI_STK_BP_CD, GI_ASST_TYP,
						GI_QTY, GI_AMT,
						GI_TRD_CUR_CD, GI_TRD_CUR_AMT, GI_XRATE,
						GI_TRD_GRP, GI_REC_EVAL_TYP, GI_ZERO_EFFECT_FLG,
						GR_ACT_IO_ID, GR_ACT_IO_ID_SUB,
						GR_CALC_CTG_CD, GR_WG_CD, GR_YM, GR_AC_DT,
						GR_MNG_DPT_CD, GR_ITM_CD, GR_ITM_SUB1, GR_ITM_SUB2, GR_ITM_SUB3,
						GR_LOT_NO, GR_SUBLOT_NO, GR_SNO1, GR_SNO2, GR_SNO3, GR_SNO4,
						GR_COST_IO_TYP, GR_AC_SLIP_TYP, GR_AC_RSN_CD,
						GR_BP_CD, GR_STK_BP_CD, GR_ASST_TYP,
						GR_QTY, GR_AMT,
						GR_TRD_CUR_CD, GR_TRD_CUR_AMT, GR_XRATE,
						GR_TRD_GRP, GR_REC_EVAL_TYP, GR_ZERO_EFFECT_FLG
						)
					VALUES	(
						x2.ACT_IO_ID, x2.ACT_IO_ID_SUB,
						x2.CALC_CTG_CD, x2.WG_CD, x2.YM, x2.AC_DT,
						x2.MNG_DPT_CD, x2.ITM_CD, x2.ITM_SUB1, x2.ITM_SUB2, x2.ITM_SUB3,
						x2.LOT_NO, x2.SUBLOT_NO, x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
						x2.COST_IO_TYP, x2.AC_SLIP_TYP, L_RSN,
						x2.BP_CD, x2.STK_BP_CD, x2.ASST_TYP,
						(-1) * x2.QTY, (-1) * x2.AMT,
						x2.TRD_CUR_CD, (-1) * x2.TRD_CUR_AMT, x2.XRATE,
						x2.TRD_GRP, x2.REC_EVAL_TYP, x2.ZERO_EFFECT_FLG,
						x1.ACT_IO_ID, x1.ACT_IO_ID_SUB,
						x1.CALC_CTG_CD, x1.WG_CD, x1.YM, x1.AC_DT,
						x1.MNG_DPT_CD, x1.ITM_CD, x1.ITM_SUB1, x1.ITM_SUB2, x1.ITM_SUB3,
						x1.LOT_NO, x1.SUBLOT_NO, x1.SNO1, x1.SNO2, x1.SNO3, x1.SNO4,
						x1.COST_IO_TYP, x1.AC_SLIP_TYP, L_RSN,
						x1.BP_CD, x1.STK_BP_CD, x1.ASST_TYP,
						(-1) * x1.QTY, (-1) * x1.AMT,
						x1.TRD_CUR_CD, (-1) * x1.TRD_CUR_AMT, x1.XRATE,
						x1.TRD_GRP, x1.REC_EVAL_TYP, x1.ZERO_EFFECT_FLG
						) ;
				END IF ;
			END LOOP ;
		END IF ;
	END LOOP ;

	--MGW_WIO2に作成したデータはMGW_IOから削除する
	DELETE	MGW_IO t
	WHERE	0=0
	AND	EXISTS (
			SELECT	'X'
			FROM	MGW_WIO2 w
			WHERE	0=0
			AND	w.GI_ACT_IO_ID = t.ACT_IO_ID
			AND	w.GI_ACT_IO_ID_SUB = t.ACT_IO_ID_SUB
		)
	;

	DELETE	MGW_IO t
	WHERE	0=0
	AND	EXISTS (
			SELECT	'X'
			FROM	MGW_WIO2 w
			WHERE	0=0
			AND	w.GR_ACT_IO_ID = t.ACT_IO_ID
			AND	w.GR_ACT_IO_ID_SUB = t.ACT_IO_ID_SUB
		)
	;

	--MGW_WIO2からMGW_IOへ作成
	i := 0 ;
	REC_IO.DELETE ;
	FOR x3 IN (
		SELECT	MAX(w.GI_ACT_IO_ID) GI_ACT_IO_ID,
			MAX(w.GI_ACT_IO_ID_SUB) GI_ACT_IO_ID_SUB,
			w.GI_CALC_CTG_CD, w.GI_WG_CD, w.GI_YM, MAX(w.GI_AC_DT) GI_AC_DT,
			w.GI_MNG_DPT_CD, w.GI_ITM_CD, w.GI_ITM_SUB1, w.GI_ITM_SUB2, w.GI_ITM_SUB3,
			w.GI_LOT_NO, w.GI_SUBLOT_NO, w.GI_SNO1, w.GI_SNO2, w.GI_SNO3, w.GI_SNO4,
			w.GI_AC_RSN_CD,
			w.GI_BP_CD, w.GI_STK_BP_CD, w.GI_ASST_TYP,
			SUM(w.GI_QTY) GI_QTY, SUM(w.GI_AMT) GI_AMT,
			w.GI_TRD_CUR_CD, SUM(w.GI_TRD_CUR_AMT) GI_TRD_CUR_AMT, w.GI_XRATE,
			MAX(w.GI_TRD_GRP) GI_TRD_GRP, w.GI_REC_EVAL_TYP, w.GI_ZERO_EFFECT_FLG,
			MAX(w.GR_ACT_IO_ID) GR_ACT_IO_ID,
			MAX(w.GR_ACT_IO_ID_SUB) GR_ACT_IO_ID_SUB,
			w.GR_CALC_CTG_CD, w.GR_WG_CD, w.GR_YM, MAX(w.GR_AC_DT) GR_AC_DT,
			w.GR_MNG_DPT_CD, w.GR_ITM_CD, w.GR_ITM_SUB1, w.GR_ITM_SUB2, w.GR_ITM_SUB3,
			w.GR_LOT_NO, w.GR_SUBLOT_NO, w.GR_SNO1, w.GR_SNO2, w.GR_SNO3, w.GR_SNO4,
			w.GR_AC_RSN_CD,
			w.GR_BP_CD, w.GR_STK_BP_CD, w.GR_ASST_TYP,
			SUM(w.GR_QTY) GR_QTY, SUM(w.GR_AMT) GR_AMT,
			w.GR_TRD_CUR_CD, SUM(w.GR_TRD_CUR_AMT) GR_TRD_CUR_AMT, w.GR_XRATE,
			MAX(w.GR_TRD_GRP) GR_TRD_GRP, w.GR_REC_EVAL_TYP, w.GR_ZERO_EFFECT_FLG
		FROM	MGW_WIO2 w
		WHERE	0=0
		GROUP BY w.GI_CALC_CTG_CD, w.GI_WG_CD, w.GI_YM,
			w.GI_MNG_DPT_CD, w.GI_ITM_CD, w.GI_ITM_SUB1, w.GI_ITM_SUB2, w.GI_ITM_SUB3,
			w.GI_LOT_NO, w.GI_SUBLOT_NO, w.GI_SNO1, w.GI_SNO2, w.GI_SNO3, w.GI_SNO4,
			w.GI_AC_RSN_CD,
			w.GI_BP_CD, w.GI_STK_BP_CD, w.GI_ASST_TYP,
			w.GI_TRD_CUR_CD, w.GI_XRATE, w.GI_REC_EVAL_TYP, w.GI_ZERO_EFFECT_FLG,
			w.GR_CALC_CTG_CD, w.GR_WG_CD, w.GR_YM,
			w.GR_MNG_DPT_CD, w.GR_ITM_CD, w.GR_ITM_SUB1, w.GR_ITM_SUB2, w.GR_ITM_SUB3,
			w.GR_LOT_NO, w.GR_SUBLOT_NO, w.GR_SNO1, w.GR_SNO2, w.GR_SNO3, w.GR_SNO4,
			w.GR_AC_RSN_CD,
			w.GR_BP_CD, w.GR_STK_BP_CD, w.GR_ASST_TYP,
			w.GR_TRD_CUR_CD, w.GR_XRATE, w.GR_REC_EVAL_TYP, w.GR_ZERO_EFFECT_FLG
		)
	LOOP
		i := i + 1 ;
		--出庫関連
		REC_IO(i).ACT_IO_ID	:= x3.GI_ACT_IO_ID ;
		REC_IO(i).ACT_IO_ID_SUB	:= x3.GI_ACT_IO_ID_SUB ;
		REC_IO(i).CALC_CTG_CD	:= x3.GI_CALC_CTG_CD ;
		REC_IO(i).WG_CD		:= x3.GI_WG_CD ;
		REC_IO(i).YM		:= x3.GI_YM ;
		REC_IO(i).AC_DT		:= x3.GI_AC_DT ;
		REC_IO(i).MNG_DPT_CD	:= x3.GI_MNG_DPT_CD ;
		REC_IO(i).ITM_CD	:= x3.GI_ITM_CD ;
		REC_IO(i).ITM_SUB1	:= x3.GI_ITM_SUB1 ;
		REC_IO(i).ITM_SUB2	:= x3.GI_ITM_SUB2 ;
		REC_IO(i).ITM_SUB3	:= x3.GI_ITM_SUB3 ;
		REC_IO(i).LOT_NO	:= x3.GI_LOT_NO ;
		REC_IO(i).SUBLOT_NO	:= x3.GI_SUBLOT_NO ;
		REC_IO(i).SNO1		:= x3.GI_SNO1 ;
		REC_IO(i).SNO2		:= x3.GI_SNO2 ;
		REC_IO(i).SNO3		:= x3.GI_SNO3 ;
		REC_IO(i).SNO4		:= x3.GI_SNO4 ;
		REC_IO(i).AC_RSN_CD	:= x3.GI_AC_RSN_CD ;
		REC_IO(i).OTHER_WG_CD	:= x3.GR_WG_CD ;
		REC_IO(i).OTHER_DPT_CD	:= x3.GR_MNG_DPT_CD ;
		REC_IO(i).BP_CD		:= x3.GI_BP_CD ;
		REC_IO(i).STK_BP_CD	:= x3.GI_STK_BP_CD ;
		REC_IO(i).ASST_TYP	:= x3.GI_ASST_TYP ;
		REC_IO(i).TRD_CUR_CD	:= x3.GI_TRD_CUR_CD ;
		REC_IO(i).XRATE		:= x3.GI_XRATE ;
		REC_IO(i).TRD_GRP	:= x3.GI_TRD_GRP ;
		REC_IO(i).REC_EVAL_TYP	:= x3.GI_REC_EVAL_TYP ;
		REC_IO(i).ITM_JNL_CD	:= C_NULL_VAL ;
		REC_IO(i).ALC_AMT_FLG	:= C_OFF ;
		REC_IO(i).ZERO_EFFECT_FLG := x3.GI_ZERO_EFFECT_FLG ;

		IF x3.GI_QTY > 0 THEN
			--出庫関連をC_IO_STK_OUTで作成する
			REC_IO(i).COST_IO_TYP := C_IO_STK_OUT ;
			REC_IO(i).AC_SLIP_TYP := C_STK_SW_SO ;
			REC_IO(i).QTY := x3.GI_QTY ;
			REC_IO(i).AMT := x3.GI_AMT ;
			REC_IO(i).TRD_CUR_AMT := x3.GI_TRD_CUR_AMT ;
		ELSE
			--出庫関連をC_IO_STK_INで作成する
			REC_IO(i).COST_IO_TYP := C_IO_STK_IN ;
			REC_IO(i).AC_SLIP_TYP := C_STK_SW_GR ;
			REC_IO(i).QTY := (-1) * x3.GI_QTY ;
			REC_IO(i).AMT := (-1) * x3.GI_AMT ;
			REC_IO(i).TRD_CUR_AMT := (-1) * x3.GI_TRD_CUR_AMT ;
		END IF ;

		i := i + 1 ;
		--入庫関連
		REC_IO(i).ACT_IO_ID	:= x3.GR_ACT_IO_ID ;
		REC_IO(i).ACT_IO_ID_SUB	:= x3.GR_ACT_IO_ID_SUB ;
		REC_IO(i).CALC_CTG_CD	:= x3.GR_CALC_CTG_CD ;
		REC_IO(i).WG_CD		:= x3.GR_WG_CD ;
		REC_IO(i).YM		:= x3.GR_YM ;
		REC_IO(i).AC_DT		:= x3.GR_AC_DT ;
		REC_IO(i).MNG_DPT_CD	:= x3.GR_MNG_DPT_CD ;
		REC_IO(i).ITM_CD	:= x3.GR_ITM_CD ;
		REC_IO(i).ITM_SUB1	:= x3.GR_ITM_SUB1 ;
		REC_IO(i).ITM_SUB2	:= x3.GR_ITM_SUB2 ;
		REC_IO(i).ITM_SUB3	:= x3.GR_ITM_SUB3 ;
		REC_IO(i).LOT_NO	:= x3.GR_LOT_NO ;
		REC_IO(i).SUBLOT_NO	:= x3.GR_SUBLOT_NO ;
		REC_IO(i).SNO1		:= x3.GR_SNO1 ;
		REC_IO(i).SNO2		:= x3.GR_SNO2 ;
		REC_IO(i).SNO3		:= x3.GR_SNO3 ;
		REC_IO(i).SNO4		:= x3.GR_SNO4 ;
		REC_IO(i).AC_RSN_CD	:= x3.GR_AC_RSN_CD ;
		REC_IO(i).OTHER_WG_CD	:= x3.GI_WG_CD ;
		REC_IO(i).OTHER_DPT_CD	:= x3.GI_MNG_DPT_CD ;
		REC_IO(i).BP_CD		:= x3.GR_BP_CD ;
		REC_IO(i).STK_BP_CD	:= x3.GR_STK_BP_CD ;
		REC_IO(i).ASST_TYP	:= x3.GR_ASST_TYP ;
		REC_IO(i).TRD_CUR_CD	:= x3.GR_TRD_CUR_CD ;
		REC_IO(i).XRATE		:= x3.GR_XRATE ;
		REC_IO(i).TRD_GRP	:= x3.GR_TRD_GRP ;
		REC_IO(i).REC_EVAL_TYP	:= x3.GR_REC_EVAL_TYP ;
		REC_IO(i).ITM_JNL_CD	:= C_NULL_VAL ;
		REC_IO(i).ALC_AMT_FLG	:= C_OFF ;
		REC_IO(i).ZERO_EFFECT_FLG := x3.GR_ZERO_EFFECT_FLG ;

		IF x3.GI_QTY > 0 THEN
			--入庫関連をC_IO_STK_INで作成する
			REC_IO(i).COST_IO_TYP := C_IO_STK_IN ;
			REC_IO(i).AC_SLIP_TYP := C_STK_SW_GR ;
			REC_IO(i).QTY := x3.GR_QTY ;
			REC_IO(i).AMT := x3.GR_AMT ;
			REC_IO(i).TRD_CUR_AMT := x3.GR_TRD_CUR_AMT ;
		ELSE
			--入庫関連をC_IO_STK_OUTで作成する
			REC_IO(i).COST_IO_TYP := C_IO_STK_OUT ;
			REC_IO(i).AC_SLIP_TYP := C_STK_SW_SO ;
			REC_IO(i).QTY := (-1) * x3.GR_QTY ;
			REC_IO(i).AMT := (-1) * x3.GR_AMT ;
			REC_IO(i).TRD_CUR_AMT := (-1) * x3.GR_TRD_CUR_AMT ;
		END IF ;

		IF i > C_MAX_CNT THEN
			INS_MGW_IO() ;
		END IF ;
	END LOOP ;

	IF i > 0 THEN
		INS_MGW_IO() ;
	END IF ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IFSUB4') ;

END P_IFSUB4 ;

PROCEDURE P_IO_TO_INPT (
	I_CALC_CTG	IN	MAPA_META.CALC_CTG_CD%TYPE,
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	投入実績への振替の作成
<REMARKS>
	入出庫実績ＩＦを振り替える
<ARGUMENTS>
<IN>	I_CALC_CTG
		計算カテゴリＣＤ
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_FLG		MAPA_META.FLG%TYPE ;

	L_SUM_T		NUMBER ;
	L_NUM_ABS	NUMBER ;
	L_NUM_ABS2	NUMBER ;
	L_NUM_S		NUMBER ;
	L_NUM_S2	NUMBER ;
	L_CNT		NUMBER ;

	C_RND_TYP	CONSTANT MAPA_META.RND_TYP%TYPE := MAC_RND_TYP.RNDUP ;--切り上げ

	C_STR		CONSTANT MAPA_META.STR20%TYPE := FSC_MODULE_ID.CostManagement || MGC_STR.ACT_ID_DLM ;
	C_NUM_SYS_INPT	CONSTANT MAPA_META.STR20%TYPE := MGC_NUM_SYS_TYP.ACT_INPT_ID ;
	C_NUM_SYS_INPT_LENGTH	CONSTANT NUMBER := MGC_NUM_SYS_TYP.LENGTH(C_NUM_SYS_INPT) ;

	TYPE ACT_MFG_IF_REC IS RECORD (
		CALC_CTG_CD		MAPA_META.CALC_CTG_CD%TYPE,
		WG_CD			MAPA_META.WG_CD%TYPE,
		YM				MAPA_META.YM%TYPE,
		AC_DT			MAPA_META.DT%TYPE,
		ITM_CD			MAPA_META.ITM_CD%TYPE,
		ITM_SUB1		MAPA_META.ITM_SUB1%TYPE,
		ITM_SUB2		MAPA_META.ITM_SUB2%TYPE,
		ITM_SUB3		MAPA_META.ITM_SUB3%TYPE,
		ITM_MFG_INST_NO	MAPA_META.ITM_MFG_INST_NO%TYPE,
		MFG_ACT_NO		MAPA_META.MFG_ACT_NO%TYPE,
		OPER_ACT_NO		MAPA_META.OPER_ACT_NO%TYPE,
		LOT_NO			MAPA_META.LOT_NO%TYPE,
		SUBLOT_NO		MAPA_META.SUBLOT_NO%TYPE,
		LOC_CD			MAPA_META.LOC_CD%TYPE,
		STR_LN_CD		MAPA_META.STR_LN_CD%TYPE,
		QTY				MAPA_META.QTY%TYPE,
		AMT				MAPA_META.MONEY%TYPE,
		EXPNS_CD		MAPA_META.EXPNS_CD%TYPE,
		MFG_ACT_GRP		MGPA_META.MFG_ACT_GRP%TYPE,
		BOM_PTN			MAPA_META.BOM_PTN%TYPE,
		OPER_PTN		MAPA_META.OPER_PTN%TYPE,
		OPER_CD			MAPA_META.OPER_CD%TYPE,
		OPER_SEQ		MAPA_META.OPER_SEQ%TYPE,
		SPPL_CD			MAPA_META.BP_CD%TYPE
	) ;

	TYPE LIST_ACT_MFG_IF IS TABLE OF ACT_MFG_IF_REC INDEX BY BINARY_INTEGER ;
	ACT_MFG_IF	LIST_ACT_MFG_IF ;
	ACT_MFG_IF_SUB	LIST_ACT_MFG_IF ;
/************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IO_TO_INPT') ;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MGW_IO w
	WHERE	0=0
	AND	w.MFG_ACT_GRP IS NOT NULL
	AND	w.QTY <> 0
	;

	IF L_CNT = 0 THEN
		GOTO PROD_END ;
	END IF ;

	ACT_MFG_IF.DELETE ;
	SELECT	t1.CALC_CTG_CD, t1.WG_CD, t1.YM, t1.AC_DT, t1.ITM_CD,
		t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3, t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO,
		NVL(t3.OPER_ACT_NO, C_NULL_VAL) OPER_ACT_NO, t1.LOT_NO, t1.SUBLOT_NO, t1.LOC_CD, t1.STR_LN_CD,
		SUM(t1.QTY), SUM(t1.AMT), t1.EXPNS_CD, t1.MFG_ACT_GRP, NVL(t1.BOM_PTN, t2.BOM_PTN) BOM_PTN,
		t1.OPER_PTN, t3.OPER_CD, t3.OPER_SEQ, m1.SPPL_CD
	BULK COLLECT INTO ACT_MFG_IF
	FROM	MGT_ACT_MFG_IF t1, MGT_ITM_DTL t2, MGT_INST_OPER t3, MAM_LOC m1
	WHERE	0=0
	AND	t1.YM = I_YM
	AND	t1.WG_CD = I_WG_CD
	AND	t1.CALC_CTG_CD = I_CALC_CTG
	AND	t1.MFG_ACT_GRP IS NOT NULL
	AND	t1.ITM_CD = t2.ITM_CD(+)
	AND	t1.ITM_SUB1 = t2.ITM_SUB1(+)
	AND	t1.ITM_SUB2 = t2.ITM_SUB2(+)
	AND	t1.ITM_SUB3 = t2.ITM_SUB3(+)
	AND	t1.LOC_CD = t2.LOC_CD(+)
	AND	t2.SPPL_CD(+) = C_NULL_VAL
	AND	t2.RQST_WG_CD(+) = C_NULL_VAL
	AND	t2.TERM(+) = G_TERM
	AND	t1.WG_CD = t2.WG_CD(+)
	AND	t2.CALC_CTG_CD(+) = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
	AND	t2.NON_CALC_FLG(+) = C_OFF
	AND	t1.ITM_CD = t3.ITM_CD(+)
	AND	t1.ITM_SUB1 = t3.ITM_SUB1(+)
	AND	t1.ITM_SUB2 = t3.ITM_SUB2(+)
	AND	t1.ITM_SUB3 = t3.ITM_SUB3(+)
	AND	t1.ITM_MFG_INST_NO = t3.ITM_MFG_INST_NO(+)
	AND	t1.MFG_ACT_NO = t3.MFG_ACT_NO(+)
	AND	t1.WG_CD = t3.WG_CD(+)
	AND	t1.CALC_CTG_CD = t3.CALC_CTG_CD(+)
	AND	t1.LOC_CD = m1.LOC_CD(+)
	GROUP BY
		t1.CALC_CTG_CD, t1.WG_CD, t1.YM, t1.AC_DT, t1.ITM_CD,
		t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3, t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO,
		t3.OPER_ACT_NO, t1.LOT_NO, t1.SUBLOT_NO, t1.LOC_CD, t1.STR_LN_CD,
		t1.EXPNS_CD, t1.MFG_ACT_GRP, NVL(t1.BOM_PTN, t2.BOM_PTN),
		t1.OPER_PTN, t3.OPER_CD, t3.OPER_SEQ, m1.SPPL_CD
	;

	IF ACT_MFG_IF.COUNT = 0 THEN
		GOTO PROD_END ;
	END IF ;

	DELETE MGW_ACT_INPT2 ;

	FOR x IN (
		SELECT	t.ROWID	ROW_ID,
			t.ACT_IO_ID, t.ACT_IO_ID_SUB,
			t.CALC_CTG_CD,
			t.WG_CD,
			t.YM, t.AC_DT,
			t.MNG_DPT_CD, t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
			t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
			t.COST_IO_TYP, t.AC_SLIP_TYP, t.AC_RSN_CD,
			t.OTHER_WG_CD, t.OTHER_DPT_CD,
			t.BP_CD, t.STK_BP_CD, t.ASST_TYP,
			t.QTY,
			t.ZERO_EFFECT_FLG,
			t.MFG_ACT_GRP,
			NVL(m.DEC_PLACE, 0)	DEC_PLACE
		FROM	MGW_IO t, MAM_ITM_SRCH m
		WHERE	0=0
		AND	t.MFG_ACT_GRP IS NOT NULL
		AND	t.QTY <> 0
		AND	t.ITM_CD = m.ITM_CD(+)
		AND	t.ITM_SUB1 = m.ITM_SUB1(+)
		AND	t.ITM_SUB2 = m.ITM_SUB2(+)
		AND	t.ITM_SUB3 = m.ITM_SUB3(+)
		AND	m.DEL_FLG(+) = C_OFF
		AND	m.RELEASE_FLG(+) = C_ON
		)
	LOOP
		--投入への製造実績グループにもとづく振替
		L_CNT := 0 ;
		ACT_MFG_IF_SUB.DELETE ;
		FOR n IN ACT_MFG_IF.FIRST..ACT_MFG_IF.LAST LOOP
			IF ACT_MFG_IF(n).MFG_ACT_GRP <> x.MFG_ACT_GRP THEN
				CONTINUE ;
			ELSIF NVL(ACT_MFG_IF(n).SPPL_CD, C_NULL_VAL) <> NVL(x.STK_BP_CD, C_NULL_VAL) THEN
				CONTINUE ;
			END IF ;
			L_CNT := L_CNT + 1 ;
			ACT_MFG_IF_SUB(L_CNT) := ACT_MFG_IF(n) ;
		END LOOP ;

		IF ACT_MFG_IF_SUB.COUNT = 0 THEN
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0050', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
							x.ACT_IO_ID, x.MFG_ACT_GRP, x.STK_BP_CD,
							MAPA_COMM.F_TO_DISP_ITM(x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3, G_PARM_ITM_SUB_TYP),
							x.QTY) ;
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		--原価ＢＯＭを展開して子品目毎の投入予定数量を取得
		DELETE MGW_ACT_MFG_BOM ;

		FORALL n IN ACT_MFG_IF_SUB.FIRST..ACT_MFG_IF_SUB.LAST
			INSERT INTO MGW_ACT_MFG_BOM (
				PAR_ITM_CD,
				PAR_ITM_SUB1,
				PAR_ITM_SUB2,
				PAR_ITM_SUB3,
				ITM_MFG_INST_NO,
				MFG_ACT_NO,
				OPER_ACT_NO,
				LOC_CD,
				STR_LN_CD,
				BP_CD,
				MFG_ACT_GRP,
				ITM_CD,
				ITM_SUB1,
				ITM_SUB2,
				ITM_SUB3,
				EXPNS_CD,
				QTY
				)
			SELECT	ACT_MFG_IF_SUB(n).ITM_CD,
				ACT_MFG_IF_SUB(n).ITM_SUB1,
				ACT_MFG_IF_SUB(n).ITM_SUB2,
				ACT_MFG_IF_SUB(n).ITM_SUB3,
				ACT_MFG_IF_SUB(n).ITM_MFG_INST_NO,
				ACT_MFG_IF_SUB(n).MFG_ACT_NO,
				ACT_MFG_IF_SUB(n).OPER_ACT_NO,
				ACT_MFG_IF_SUB(n).LOC_CD,
				ACT_MFG_IF_SUB(n).STR_LN_CD,
				ACT_MFG_IF_SUB(n).SPPL_CD,
				ACT_MFG_IF_SUB(n).MFG_ACT_GRP,
				t.CHD_ITM_CD,
				t.CHD_ITM_SUB1,
				t.CHD_ITM_SUB2,
				t.CHD_ITM_SUB3,
				t.EXPNS_CD,
				MAPA_CALC.F_RND(t.CHD_RQMT_QTY / t.PAR_RQMT_QTY * ACT_MFG_IF_SUB(n).QTY, x.DEC_PLACE, C_RND_TYP)
			FROM	MGT_BOM t
			WHERE	0=0
			AND	t.PAR_ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
			AND	t.PAR_ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
			AND	t.PAR_ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
			AND	t.PAR_ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
			AND	t.BOM_PTN = ACT_MFG_IF_SUB(n).BOM_PTN
			AND (
				t.OPER_CD = ACT_MFG_IF_SUB(n).OPER_CD AND t.OPER_SEQ = ACT_MFG_IF_SUB(n).OPER_SEQ
				OR
				ACT_MFG_IF_SUB(n).OPER_CD IS NULL
				)
			AND	t.ALT_GRP_CD IS NULL
			AND	t.TERM = G_TERM
			AND	t.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
			AND	t.WG_CD = ACT_MFG_IF_SUB(n).WG_CD
			AND	t.CHD_ITM_CD = x.ITM_CD
			AND	t.CHD_ITM_SUB1 = x.ITM_SUB1
			AND	t.CHD_ITM_SUB2 = x.ITM_SUB2
			AND	t.CHD_ITM_SUB3 = x.ITM_SUB3
			AND	t.NON_CALC_FLG = C_OFF
			;

		FORALL n IN ACT_MFG_IF_SUB.FIRST..ACT_MFG_IF_SUB.LAST
			INSERT INTO MGW_ACT_MFG_BOM (
				PAR_ITM_CD,
				PAR_ITM_SUB1,
				PAR_ITM_SUB2,
				PAR_ITM_SUB3,
				ITM_MFG_INST_NO,
				MFG_ACT_NO,
				OPER_ACT_NO,
				LOC_CD,
				STR_LN_CD,
				BP_CD,
				MFG_ACT_GRP,
				ITM_CD,
				ITM_SUB1,
				ITM_SUB2,
				ITM_SUB3,
				EXPNS_CD,
				QTY
				)
			SELECT	ACT_MFG_IF_SUB(n).ITM_CD,
				ACT_MFG_IF_SUB(n).ITM_SUB1,
				ACT_MFG_IF_SUB(n).ITM_SUB2,
				ACT_MFG_IF_SUB(n).ITM_SUB3,
				ACT_MFG_IF_SUB(n).ITM_MFG_INST_NO,
				ACT_MFG_IF_SUB(n).MFG_ACT_NO,
				ACT_MFG_IF_SUB(n).OPER_ACT_NO,
				ACT_MFG_IF_SUB(n).LOC_CD,
				ACT_MFG_IF_SUB(n).STR_LN_CD,
				ACT_MFG_IF_SUB(n).SPPL_CD,
				ACT_MFG_IF_SUB(n).MFG_ACT_GRP,
				t.CHD_ITM_CD,
				t.CHD_ITM_SUB1,
				t.CHD_ITM_SUB2,
				t.CHD_ITM_SUB3,
				t.EXPNS_CD,
				MAPA_CALC.F_RND(t.CHD_RQMT_QTY / t.PAR_RQMT_QTY * ACT_MFG_IF_SUB(n).QTY, x.DEC_PLACE, C_RND_TYP)
			FROM	MGT_BOM t
			WHERE	0=0
			AND	t.PAR_ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
			AND	t.PAR_ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
			AND	t.PAR_ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
			AND	t.PAR_ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
			AND	t.BOM_PTN = ACT_MFG_IF_SUB(n).BOM_PTN
			AND (
				t.OPER_CD = ACT_MFG_IF_SUB(n).OPER_CD AND t.OPER_SEQ = ACT_MFG_IF_SUB(n).OPER_SEQ
				OR
				ACT_MFG_IF_SUB(n).OPER_CD IS NULL
				)
			AND	t.ALT_GRP_CD IS NULL
			AND	t.TERM = G_TERM
			AND	t.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
			AND	t.WG_CD = C_NULL_VAL
			AND	t.CHD_ITM_CD = x.ITM_CD
			AND	t.CHD_ITM_SUB1 = x.ITM_SUB1
			AND	t.CHD_ITM_SUB2 = x.ITM_SUB2
			AND	t.CHD_ITM_SUB3 = x.ITM_SUB3
			AND	t.NON_CALC_FLG = C_OFF
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MGT_BOM w
					WHERE	0=0
					AND	w.PAR_ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
					AND	w.PAR_ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
					AND	w.PAR_ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
					AND	w.PAR_ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
					AND	w.BOM_PTN = ACT_MFG_IF_SUB(n).BOM_PTN
					AND	w.ALT_GRP_CD IS NULL
					AND	w.TERM = G_TERM
					AND	w.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
					AND	w.WG_CD = ACT_MFG_IF_SUB(n).WG_CD
					AND	w.NON_CALC_FLG = C_OFF
				)
			;

		SELECT	COUNT(*), NVL(SUM(w.QTY), 0)
		INTO	L_CNT, L_SUM_T
		FROM	MGW_ACT_MFG_BOM w
		WHERE	0=0
		;

		IF L_CNT = 0 OR L_SUM_T = 0 THEN
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0048', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
							x.ACT_IO_ID, x.MFG_ACT_GRP, x.STK_BP_CD,
							MAPA_COMM.F_TO_DISP_ITM(x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3, G_PARM_ITM_SUB_TYP),
							x.QTY) ;
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		--製造実績ＢＯＭワークの数量が大きい順に、入出庫実績ＩＦの数量を按分する
		L_FLG := C_OFF ;
		L_NUM_ABS := ABS(x.QTY) ;
		L_NUM_ABS2 := 0 ;
		L_NUM_S := x.QTY ;

		FOR y IN (
			SELECT	w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
				w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
				w.LOC_CD, w.STR_LN_CD, w.BP_CD,
				w.EXPNS_CD, w.QTY
			FROM	MGW_ACT_MFG_BOM w
			WHERE	0=0
			ORDER BY w.QTY DESC
			)
		LOOP
			L_NUM_S2 := MAPA_CALC.F_RND(x.QTY * y.QTY / L_SUM_T, x.DEC_PLACE, C_RND_TYP) ;
			L_NUM_ABS2 := L_NUM_ABS2 + ABS(L_NUM_S2) ;
			IF L_NUM_ABS2 >= L_NUM_ABS THEN
				IF L_FLG = C_ON THEN
					EXIT ;
				ELSE
					L_NUM_S2 := L_NUM_S ;
					L_FLG := C_ON ;
				END IF ;
			END IF ;
			IF L_NUM_S2 <> 0 THEN
				INSERT INTO MGW_ACT_INPT2 (
					ACT_IO_ID, ACT_IO_ID_SUB,
					CALC_CTG_CD, WG_CD,
					YM, AC_DT,
					PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
					ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
					LOC_CD, STR_LN_CD,
					MNG_DPT_CD,
					ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
					LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
					AC_SLIP_TYP, AC_RSN_CD,
					BP_CD,
					STK_BP_CD, ASST_TYP, MFG_ACT_GRP,
					EXPNS_CD, QTY
					)
				VALUES	(
					x.ACT_IO_ID, x.ACT_IO_ID_SUB,
					x.CALC_CTG_CD, x.WG_CD,
					x.YM, x.AC_DT,
					y.PAR_ITM_CD, y.PAR_ITM_SUB1, y.PAR_ITM_SUB2, y.PAR_ITM_SUB3,
					y.ITM_MFG_INST_NO, y.MFG_ACT_NO, y.OPER_ACT_NO,
					y.LOC_CD, y.STR_LN_CD,
					x.MNG_DPT_CD,
					x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
					x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
					x.AC_SLIP_TYP, x.AC_RSN_CD,
					x.BP_CD,
					y.BP_CD, x.ASST_TYP, x.MFG_ACT_GRP,
					y.EXPNS_CD, L_NUM_S2
					)
				;
				L_NUM_S := L_NUM_S - L_NUM_S2 ;
			END IF ;
		END LOOP ;

		DELETE MGW_IO t WHERE t.ROWID = x.ROW_ID ;

		<<NEXT_OUT_LOOP>>
			NULL ;
	END LOOP ;

	INSERT INTO MGT_ACT_INPT (
		ACT_INPT_ID, ACT_INPT_ID_SUB,
		CALC_CTG_CD, WG_CD,
		YM, AC_DT,
		PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
		ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		AC_SLIP_TYP, AC_RSN_CD,
		BP_CD,
		STK_BP_CD, ASST_TYP, MFG_ACT_GRP,
		EXPNS_CD, QTY
		)
	SELECT	C_STR || LPAD(MAPA_NUM.F_GET_SEQ(C_NUM_SYS_INPT), C_NUM_SYS_INPT_LENGTH, '0'), '1',
		t.CALC_CTG_CD, t.WG_CD,
		t.YM, t.AC_DT,
		t.PAR_ITM_CD, t.PAR_ITM_SUB1, t.PAR_ITM_SUB2, t.PAR_ITM_SUB3,
		t.ITM_MFG_INST_NO, t.MFG_ACT_NO, t.OPER_ACT_NO,
		t.LOC_CD, t.STR_LN_CD,
		t.MNG_DPT_CD,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
		CASE
			WHEN t.ASST_TYP = C_ASST3 THEN C_IN_ONR
			ELSE C_INPUT
		END, t.AC_RSN_CD,
		t.BP_CD,
		t.STK_BP_CD, t.ASST_TYP, t.MFG_ACT_GRP,
		t.EXPNS_CD, t.QTY
	FROM (
		SELECT	w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.MNG_DPT_CD,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.AC_SLIP_TYP, w.AC_RSN_CD,
			w.BP_CD,
			w.STK_BP_CD, w.ASST_TYP, w.MFG_ACT_GRP,
			w.EXPNS_CD, SUM(w.QTY)	QTY
		FROM	MGW_ACT_INPT2 w
		WHERE	0=0
		GROUP BY
			w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.PAR_ITM_CD, w.PAR_ITM_SUB1, w.PAR_ITM_SUB2, w.PAR_ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.MNG_DPT_CD,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.AC_SLIP_TYP, w.AC_RSN_CD,
			w.BP_CD,
			w.STK_BP_CD, w.ASST_TYP, w.MFG_ACT_GRP,
			w.EXPNS_CD
		HAVING SUM(w.QTY) <> 0
		) t
	WHERE	0=0
	;

	<<PROD_END>>
		NULL ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IO_TO_INPT') ;

END P_IO_TO_INPT ;

PROCEDURE P_OTHER_WK_TO_INST_WK (
	I_CALC_CTG	IN	MAPA_META.CALC_CTG_CD%TYPE,
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE
)
/************************************************************************
<SYNOPSIS>
	指図工数実績への振替の作成
<REMARKS>
	指図外工数実績ＩＦを振り替える
<ARGUMENTS>
<IN>	I_CALC_CTG
		計算カテゴリＣＤ
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<HISTORY>
*************************************************************************/
AS
	L_FLG		MAPA_META.FLG%TYPE ;

	L_SUM_T		NUMBER ;
	L_NUM_ABS	NUMBER ;
	L_NUM_ABS2	NUMBER ;
	L_NUM_S		NUMBER ;
	L_NUM_S2	NUMBER ;
	L_CNT		NUMBER ;

	C_RND_TYP	CONSTANT MAPA_META.RND_TYP%TYPE := MAC_RND_TYP.RNDUP ;--切り上げ

	C_STR		CONSTANT MAPA_META.STR20%TYPE := FSC_MODULE_ID.CostManagement || MGC_STR.ACT_ID_DLM ;
	C_NUM_SYS_INST_WK	CONSTANT MAPA_META.STR20%TYPE := MGC_NUM_SYS_TYP.ACT_INST_WK_ID ;
	C_NUM_SYS_INST_WK_LENGTH	CONSTANT NUMBER := MGC_NUM_SYS_TYP.LENGTH(C_NUM_SYS_INST_WK) ;

	TYPE ACT_MFG_IF_REC IS RECORD (
		CALC_CTG_CD		MAPA_META.CALC_CTG_CD%TYPE,
		WG_CD			MAPA_META.WG_CD%TYPE,
		YM				MAPA_META.YM%TYPE,
		AC_DT			MAPA_META.DT%TYPE,
		ITM_CD			MAPA_META.ITM_CD%TYPE,
		ITM_SUB1		MAPA_META.ITM_SUB1%TYPE,
		ITM_SUB2		MAPA_META.ITM_SUB2%TYPE,
		ITM_SUB3		MAPA_META.ITM_SUB3%TYPE,
		ITM_MFG_INST_NO	MAPA_META.ITM_MFG_INST_NO%TYPE,
		MFG_ACT_NO		MAPA_META.MFG_ACT_NO%TYPE,
		OPER_ACT_NO		MAPA_META.OPER_ACT_NO%TYPE,
		LOT_NO			MAPA_META.LOT_NO%TYPE,
		SUBLOT_NO		MAPA_META.SUBLOT_NO%TYPE,
		LOC_CD			MAPA_META.LOC_CD%TYPE,
		STR_LN_CD		MAPA_META.STR_LN_CD%TYPE,
		QTY				MAPA_META.QTY%TYPE,
		MFG_ACT_GRP		MGPA_META.MFG_ACT_GRP%TYPE,
		OPER_PTN		MAPA_META.OPER_PTN%TYPE,
		OPER_CD			MAPA_META.OPER_CD%TYPE,
		OPER_SEQ		MAPA_META.OPER_SEQ%TYPE
	) ;

	TYPE LIST_ACT_MFG_IF IS TABLE OF ACT_MFG_IF_REC INDEX BY BINARY_INTEGER ;
	ACT_MFG_IF	LIST_ACT_MFG_IF ;
	ACT_MFG_IF_SUB	LIST_ACT_MFG_IF ;
/************************************************************************/
BEGIN
	--処理を開始しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_OTHER_WK_TO_INST_WK') ;

	INSERT INTO MGW_ACT_OTHER_WK_IF (
		DATA_LNO,
		CALC_CTG_CD,
		WG_CD,
		YM,
		AC_DT,
		DPT_CD,
		CTG_CD,
		LOC_CD,
		OPER_CD,
		LOT_NO,
		SUBLOT_NO,
		SNO1,
		SNO2,
		SNO3,
		SNO4,
		WK_COST_CD,
		WK_RSN_CD,
		WK_COST,
		MFG_ACT_GRP
		)
	SELECT	t.DATA_LNO,
		t.CALC_CTG_CD,
		t.WG_CD,
		t.YM,
		t.AC_DT,
		t.DPT_CD,
		t.CTG_CD,
		t.LOC_CD,
		t.OPER_CD,
		t.LOT_NO,
		t.SUBLOT_NO,
		t.SNO1,
		t.SNO2,
		t.SNO3,
		t.SNO4,
		t.WK_COST_CD,
		t.WK_RSN_CD,
		t.WK_COST,
		t.MFG_ACT_GRP
	FROM	MGT_ACT_OTHER_WK_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.WG_CD = I_WG_CD
	AND	t.CALC_CTG_CD = I_CALC_CTG
	;

	SELECT	COUNT(*)
	INTO	L_CNT
	FROM	MGW_ACT_OTHER_WK_IF w
	WHERE	0=0
	AND	w.MFG_ACT_GRP IS NOT NULL
	;

	IF L_CNT = 0 THEN
		GOTO PROD_END ;
	END IF ;

	ACT_MFG_IF.DELETE ;
	SELECT	t1.CALC_CTG_CD, t1.WG_CD, t1.YM, t1.AC_DT, t1.ITM_CD,
		t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3, t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO,
		NVL(t3.OPER_ACT_NO, C_NULL_VAL) OPER_ACT_NO, t1.LOT_NO, t1.SUBLOT_NO, t1.LOC_CD, t1.STR_LN_CD,
		SUM(t1.QTY), t1.MFG_ACT_GRP, NVL(t1.OPER_PTN, t2.OPER_PTN) OPER_PTN,
		t3.OPER_CD, t3.OPER_SEQ
	BULK COLLECT INTO ACT_MFG_IF
	FROM	MGT_ACT_MFG_IF t1, MGT_ITM_DTL t2, MGT_INST_OPER t3
	WHERE	0=0
	AND	t1.YM = I_YM
	AND	t1.WG_CD = I_WG_CD
	AND	t1.MFG_ACT_GRP IS NOT NULL
	AND	t1.CALC_CTG_CD = I_CALC_CTG
	AND	t1.ITM_CD = t2.ITM_CD(+)
	AND	t1.ITM_SUB1 = t2.ITM_SUB1(+)
	AND	t1.ITM_SUB2 = t2.ITM_SUB2(+)
	AND	t1.ITM_SUB3 = t2.ITM_SUB3(+)
	AND	t1.LOC_CD = t2.LOC_CD(+)
	AND	t2.SPPL_CD(+) = C_NULL_VAL
	AND	t2.RQST_WG_CD(+) = C_NULL_VAL
	AND	t2.TERM(+) = G_TERM
	AND	t1.WG_CD = t2.WG_CD(+)
	AND	t2.CALC_CTG_CD(+) = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
	AND	t2.NON_CALC_FLG(+) = C_OFF
	AND	t1.ITM_CD = t3.ITM_CD(+)
	AND	t1.ITM_SUB1 = t3.ITM_SUB1(+)
	AND	t1.ITM_SUB2 = t3.ITM_SUB2(+)
	AND	t1.ITM_SUB3 = t3.ITM_SUB3(+)
	AND	t1.ITM_MFG_INST_NO = t3.ITM_MFG_INST_NO(+)
	AND	t1.MFG_ACT_NO = t3.MFG_ACT_NO(+)
	AND	t1.WG_CD = t3.WG_CD(+)
	AND	t1.CALC_CTG_CD = t3.CALC_CTG_CD(+)
	GROUP BY
		t1.CALC_CTG_CD, t1.WG_CD, t1.YM, t1.AC_DT, t1.ITM_CD,
		t1.ITM_SUB1, t1.ITM_SUB2, t1.ITM_SUB3, t1.ITM_MFG_INST_NO, t1.MFG_ACT_NO,
		t3.OPER_ACT_NO, t1.LOT_NO, t1.SUBLOT_NO, t1.LOC_CD, t1.STR_LN_CD,
		t1.MFG_ACT_GRP, NVL(t1.OPER_PTN, t2.OPER_PTN),
		t3.OPER_CD, t3.OPER_SEQ
	;

	IF ACT_MFG_IF.COUNT = 0 THEN
		GOTO PROD_END ;
	END IF ;

	FOR x IN (
		SELECT	t.ROWID	ROW_ID, t.DATA_LNO,
			t.CALC_CTG_CD, t.WG_CD, t.YM, t.AC_DT,
			t.WK_COST_CD, t.WK_COST, t.WK_RSN_CD, t.MFG_ACT_GRP,
			NVL(m.DEC_PLACE, 0)	DEC_PLACE
		FROM	MGW_ACT_OTHER_WK_IF t, MAM_WK_COST m
		WHERE	0=0
		AND	t.MFG_ACT_GRP IS NOT NULL
		AND	t.WK_COST <> 0
		AND	t.WK_COST_CD = m.WK_COST_CD(+)
		)
	LOOP
		--指図工数への製造実績グループにもとづく振替
		L_CNT := 0 ;
		ACT_MFG_IF_SUB.DELETE ;
		FOR n IN ACT_MFG_IF.FIRST..ACT_MFG_IF.LAST LOOP
			IF ACT_MFG_IF(n).MFG_ACT_GRP <> x.MFG_ACT_GRP THEN
				CONTINUE ;
			END IF ;
			L_CNT := L_CNT + 1 ;
			ACT_MFG_IF_SUB(L_CNT) := ACT_MFG_IF(n) ;
		END LOOP ;

		IF ACT_MFG_IF_SUB.COUNT = 0 THEN
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0051', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
							TO_CHAR(x.DATA_LNO), x.MFG_ACT_GRP, x.WK_COST_CD, x.WK_COST) ;
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		--原価品目工数情報から工数管理毎の予定工数を取得
		DELETE MGW_ACT_MFG_ITM_WK ;

		FORALL n IN ACT_MFG_IF_SUB.FIRST..ACT_MFG_IF_SUB.LAST
			INSERT INTO MGW_ACT_MFG_ITM_WK (
				ITM_CD,
				ITM_SUB1,
				ITM_SUB2,
				ITM_SUB3,
				ITM_MFG_INST_NO,
				MFG_ACT_NO,
				OPER_ACT_NO,
				LOC_CD,
				STR_LN_CD,
				MFG_ACT_GRP,
				WK_COST_CD,
				WK_COST
				)
			SELECT	ACT_MFG_IF_SUB(n).ITM_CD,
				ACT_MFG_IF_SUB(n).ITM_SUB1,
				ACT_MFG_IF_SUB(n).ITM_SUB2,
				ACT_MFG_IF_SUB(n).ITM_SUB3,
				ACT_MFG_IF_SUB(n).ITM_MFG_INST_NO,
				ACT_MFG_IF_SUB(n).MFG_ACT_NO,
				ACT_MFG_IF_SUB(n).OPER_ACT_NO,
				ACT_MFG_IF_SUB(n).LOC_CD,
				ACT_MFG_IF_SUB(n).STR_LN_CD,
				ACT_MFG_IF_SUB(n).MFG_ACT_GRP,
				t.WK_COST_CD,
				MAPA_CALC.F_RND(t.WK_COST / t.BASE_QTY * ACT_MFG_IF_SUB(n).QTY, x.DEC_PLACE, C_RND_TYP)
			FROM	MGT_ITM_WK t
			WHERE	0=0
			AND	t.ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
			AND	t.ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
			AND	t.ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
			AND	t.ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
			AND	t.LOC_CD = ACT_MFG_IF_SUB(n).LOC_CD
			AND	t.OPER_PTN = NVL(ACT_MFG_IF_SUB(n).OPER_PTN, C_NULL_VAL)
			AND (
				t.OPER_CD = ACT_MFG_IF_SUB(n).OPER_CD AND t.OPER_SEQ = ACT_MFG_IF_SUB(n).OPER_SEQ
				OR
				ACT_MFG_IF_SUB(n).OPER_CD IS NULL
				)
			AND	t.TERM = G_TERM
			AND	t.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
			AND	t.WG_CD = ACT_MFG_IF_SUB(n).WG_CD
			AND	t.WK_COST_CD = x.WK_COST_CD
			AND	t.NON_CALC_FLG = C_OFF
			;

		FORALL n IN ACT_MFG_IF_SUB.FIRST..ACT_MFG_IF_SUB.LAST
			INSERT INTO MGW_ACT_MFG_ITM_WK (
				ITM_CD,
				ITM_SUB1,
				ITM_SUB2,
				ITM_SUB3,
				ITM_MFG_INST_NO,
				MFG_ACT_NO,
				OPER_ACT_NO,
				LOC_CD,
				STR_LN_CD,
				MFG_ACT_GRP,
				WK_COST_CD,
				WK_COST
				)
			SELECT	ACT_MFG_IF_SUB(n).ITM_CD,
				ACT_MFG_IF_SUB(n).ITM_SUB1,
				ACT_MFG_IF_SUB(n).ITM_SUB2,
				ACT_MFG_IF_SUB(n).ITM_SUB3,
				ACT_MFG_IF_SUB(n).ITM_MFG_INST_NO,
				ACT_MFG_IF_SUB(n).MFG_ACT_NO,
				ACT_MFG_IF_SUB(n).OPER_ACT_NO,
				ACT_MFG_IF_SUB(n).LOC_CD,
				ACT_MFG_IF_SUB(n).STR_LN_CD,
				ACT_MFG_IF_SUB(n).MFG_ACT_GRP,
				t.WK_COST_CD,
				MAPA_CALC.F_RND(t.WK_COST / t.BASE_QTY * ACT_MFG_IF_SUB(n).QTY, x.DEC_PLACE, C_RND_TYP)
			FROM	MGT_ITM_WK t
			WHERE	0=0
			AND	t.ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
			AND	t.ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
			AND	t.ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
			AND	t.ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
			AND	t.LOC_CD = C_NULL_VAL
			AND	t.OPER_PTN = NVL(ACT_MFG_IF_SUB(n).OPER_PTN, C_NULL_VAL)
			AND (
				t.OPER_CD = ACT_MFG_IF_SUB(n).OPER_CD AND t.OPER_SEQ = ACT_MFG_IF_SUB(n).OPER_SEQ
				OR
				ACT_MFG_IF_SUB(n).OPER_CD IS NULL
				)
			AND	t.TERM = G_TERM
			AND	t.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
			AND	t.WG_CD = C_NULL_VAL
			AND	t.WK_COST_CD = x.WK_COST_CD
			AND	t.NON_CALC_FLG = C_OFF
			AND	NOT EXISTS (
					SELECT	'X'
					FROM	MGT_ITM_WK w
					WHERE	0=0
					AND	w.ITM_CD = ACT_MFG_IF_SUB(n).ITM_CD
					AND	w.ITM_SUB1 = ACT_MFG_IF_SUB(n).ITM_SUB1
					AND	w.ITM_SUB2 = ACT_MFG_IF_SUB(n).ITM_SUB2
					AND	w.ITM_SUB3 = ACT_MFG_IF_SUB(n).ITM_SUB3
					AND	w.OPER_PTN = NVL(ACT_MFG_IF_SUB(n).OPER_PTN, C_NULL_VAL)
					AND	w.TERM = G_TERM
					AND	w.CALC_CTG_CD = NVL(G_ACT_TRD_CALC_CTG, G_DEF_CALC_CTG)
					AND	w.WG_CD = ACT_MFG_IF_SUB(n).WG_CD
					AND	w.NON_CALC_FLG = C_OFF
				)
			;

		SELECT	COUNT(*), NVL(SUM(w.WK_COST), 0)
		INTO	L_CNT, L_SUM_T
		FROM	MGW_ACT_MFG_ITM_WK w
		WHERE	0=0
		;

		IF L_CNT = 0 OR L_SUM_T = 0 THEN
			FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0049', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
							TO_CHAR(x.DATA_LNO), x.MFG_ACT_GRP, x.WK_COST_CD, x.WK_COST) ;
			GOTO NEXT_OUT_LOOP ;
		END IF ;

		--製造実績品目工数ワークの数量が大きい順に、指図外工数ＩＦの数量を按分する
		L_FLG := C_OFF ;
		L_NUM_ABS := ABS(x.WK_COST) ;
		L_NUM_ABS2 := 0 ;
		L_NUM_S := x.WK_COST ;

		FOR y IN (
			SELECT	w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
				w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
				w.LOC_CD, w.STR_LN_CD,
				w.WK_COST_CD,
				w.WK_COST
			FROM	MGW_ACT_MFG_ITM_WK w
			WHERE	0=0
			ORDER BY w.WK_COST DESC
			)
		LOOP
			L_NUM_S2 := MAPA_CALC.F_RND(x.WK_COST * y.WK_COST / L_SUM_T, x.DEC_PLACE, C_RND_TYP) ;
			L_NUM_ABS2 := L_NUM_ABS2 + ABS(L_NUM_S2) ;
			IF L_NUM_ABS2 >= L_NUM_ABS THEN
				IF L_FLG = C_ON THEN
					EXIT ;
				ELSE
					L_NUM_S2 := L_NUM_S ;
					L_FLG := C_ON ;
				END IF ;
			END IF ;
			IF L_NUM_S2 <> 0 THEN
				INSERT INTO MGW_ACT_INST_WK (
					CALC_CTG_CD, WG_CD,
					YM, AC_DT,
					ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
					ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
					LOC_CD, STR_LN_CD,
					WK_COST_CD, WK_RSN_CD,
					WK_COST
					)
				VALUES	(
					x.CALC_CTG_CD, x.WG_CD,
					x.YM, x.AC_DT,
					y.ITM_CD, y.ITM_SUB1, y.ITM_SUB2, y.ITM_SUB3,
					y.ITM_MFG_INST_NO, y.MFG_ACT_NO, y.OPER_ACT_NO,
					y.LOC_CD, y.STR_LN_CD,
					y.WK_COST_CD, x.WK_RSN_CD,
					L_NUM_S2
					)
				;
				L_NUM_S := L_NUM_S - L_NUM_S2 ;
			END IF ;
		END LOOP ;

		DELETE MGW_ACT_OTHER_WK_IF t WHERE t.ROWID = x.ROW_ID ;

		<<NEXT_OUT_LOOP>>
			NULL ;
	END LOOP ;

	INSERT INTO MGT_ACT_INST_WK (
		ACT_INST_WK_ID,
		CALC_CTG_CD, WG_CD,
		YM, AC_DT,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO, MFG_ACT_NO, OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		WK_COST_CD, WK_RSN_CD,
		WK_COST
		)
	SELECT	C_STR || LPAD(MAPA_NUM.F_GET_SEQ(C_NUM_SYS_INST_WK), C_NUM_SYS_INST_WK_LENGTH, '0'),
		t.CALC_CTG_CD, t.WG_CD,
		t.YM, t.AC_DT,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.ITM_MFG_INST_NO, t.MFG_ACT_NO, t.OPER_ACT_NO,
		t.LOC_CD, t.STR_LN_CD,
		t.WK_COST_CD, t.WK_RSN_CD,
		t.WK_COST
	FROM (
		SELECT	w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.WK_COST_CD, w.WK_RSN_CD,
			SUM(w.WK_COST)	WK_COST
		FROM	MGW_ACT_INST_WK	w
		WHERE	0=0
		GROUP BY
			w.CALC_CTG_CD, w.WG_CD,
			w.YM, w.AC_DT,
			w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.ITM_MFG_INST_NO, w.MFG_ACT_NO, w.OPER_ACT_NO,
			w.LOC_CD, w.STR_LN_CD,
			w.WK_COST_CD, w.WK_RSN_CD
		HAVING SUM(w.WK_COST) <> 0
		) t
	WHERE	0=0
	;

	<<PROD_END>>
		NULL ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_OTHER_WK_TO_INST_WK') ;

END P_OTHER_WK_TO_INST_WK ;

PROCEDURE P_IF (
	I_CALC_CTG	IN	MAPA_META.CALC_CTG_CD%TYPE,
	I_WG_CD		IN	MAPA_META.WG_CD%TYPE,
	I_YM		IN	MAPA_META.YM%TYPE,
	I_MFG		IN	MAPA_META.FLG%TYPE,
	I_TRAN		IN	MAPA_META.FLG%TYPE,
	I_STK		IN	MAPA_META.FLG%TYPE,
	I_DEL		IN	MAPA_META.FLG%TYPE
)
/************************************************************************
<SYNOPSIS>
	原価実績インターフェースデータから原価実績データの作成処理を行う
<REMARKS>
	I_DELが設定されているときは対象データの削除処理を行う
<ARGUMENTS>
<IN>	I_CALC_CTG
		計算カテゴリＣＤ
<IN>	I_WG_CD
		ワーキンググループＣＤ
<IN>	I_YM
		対象年月
<IN>	I_MFG
		製造実績関連(製造、購買、投入、工数) 0:実行しない 1:実行する
<IN>	I_TRAN
		入出庫関連(入出庫、売上) 0:実行しない 1:実行する
<IN>	I_STK
		在庫情報 0:実行しない 1:実行する
<IN>	I_DEL
		削除 0:取込処理を実行 1:削除処理を実行
<HISTORY>
*************************************************************************/
AS
	C_OK		CONSTANT INTEGER := 0 ;
	C_ERR1		CONSTANT INTEGER := 1 ;

	L_RC		INTEGER ;
	L_MSG		FCPA_ERR.MSG_BINDER ;

	L_CNT		NUMBER	;

	L_TS		MAPA_META.SYS_TS%TYPE ;
	L_USR		MAPA_META.FCM_USR_ID%TYPE ;

	L_STKTK_SUM		MAPA_META.FLG%TYPE ;
	L_OTH_CCN_SUM		MAPA_META.FLG%TYPE ;
	L_YM			MAPA_META.YM%TYPE ;
	L_CALC_CTG		MAPA_META.CALC_CTG_CD%TYPE ;
	L_WG_CD			MAPA_META.WG_CD%TYPE ;

	CURSOR ITM IS
		SELECT	w.TBL	TBL,
			w.ITM_CD	ITM_CD,
			w.ITM_SUB1	ITM_SUB1,
			w.ITM_SUB2	ITM_SUB2,
			w.ITM_SUB3	ITM_SUB3
		FROM	(
			SELECT	DISTINCT
				'MGT_ACT_MFG_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_MFG_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INST_WIP_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_INST_WIP_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_PURC_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_PURC_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INPT_IF'	TBL,
				t.PAR_ITM_CD	ITM_CD,
				t.PAR_ITM_SUB1	ITM_SUB1,
				t.PAR_ITM_SUB2	ITM_SUB2,
				t.PAR_ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_INPT_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INPT_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_INPT_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INST_WK_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_INST_WK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.ALC_ITM_CD	ITM_CD,
				t.ALC_ITM_SUB1	ITM_SUB1,
				t.ALC_ITM_SUB2	ITM_SUB2,
				t.ALC_ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_ITM_CD IS NOT NULL
			AND	I_TRAN	= C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_STK_IF'	TBL,
				t.ITM_CD	ITM_CD,
				t.ITM_SUB1	ITM_SUB1,
				t.ITM_SUB2	ITM_SUB2,
				t.ITM_SUB3	ITM_SUB3
			FROM	MGT_ACT_STK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_STK = C_ON
			) w
		WHERE	0=0
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_ITM_SRCH m
				WHERE	0=0
				AND	m.ITM_CD = w.ITM_CD
				AND	m.ITM_SUB1 = w.ITM_SUB1
				AND	m.ITM_SUB2 = w.ITM_SUB2
				AND	m.ITM_SUB3 = w.ITM_SUB3
				AND	m.DEL_FLG = C_OFF
				AND	m.RELEASE_FLG = C_ON
				)
		;
	ITM_R		ITM%ROWTYPE ;

	CURSOR LOC IS
		SELECT	w.TBL	TBL,
			w.LOC	LOC
		FROM	(
			SELECT	DISTINCT
				'MGT_ACT_MFG_IF'	TBL,
				t.LOC_CD	LOC
			FROM	MGT_ACT_MFG_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_PURC_IF'	TBL,
				t.ALC_LOC_CD	LOC
			FROM	MGT_ACT_PURC_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_LOC_CD IS NOT NULL
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INST_WIP_IF'	TBL,
				t.LOC_CD	LOC
			FROM	MGT_ACT_INST_WIP_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INPT_IF'	TBL,
				t.LOC_CD	LOC
			FROM	MGT_ACT_INPT_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INST_WK_IF'	TBL,
				t.LOC_CD	LOC
			FROM	MGT_ACT_INST_WK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_OTHER_WK_IF'	TBL,
				t.LOC_CD	LOC
			FROM	MGT_ACT_OTHER_WK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.LOC_CD IS NOT NULL
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.ALC_LOC_CD	LOC
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_LOC_CD IS NOT NULL
			AND	I_TRAN = C_ON
			) w
		WHERE	0=0
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_LOC m
				WHERE	0=0
				AND	m.LOC_CD = w.LOC
				AND	m.DEL_FLG = C_OFF
				)
		;
	LOC_R	LOC%ROWTYPE;

	CURSOR BP IS
		SELECT	w.TBL	TBL,
			w.BP	BP
		FROM	(
			SELECT	DISTINCT
				'MGT_ACT_PURC_IF'	TBL,
				t.SPPL_CD		BP
			FROM	MGT_ACT_PURC_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.CST_CD	BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.CST_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.DLV_CD		BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.DLV_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.STK_BP_CD		BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.STK_BP_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.DEST_CD1		BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.DEST_CD1 IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.DEST_CD2		BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.DEST_CD2 IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.DEST_CD3		BP
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.DEST_CD3 IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.BP_CD		BP
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.BP_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.STK_BP_CD	BP
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.STK_BP_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.ALC_BP_CD	BP
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_BP_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_STK_IF'	TBL,
				t.BP_CD		BP
			FROM	MGT_ACT_STK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.BP_CD IS NOT NULL
			AND	I_STK = C_ON
			) w
		WHERE	0=0
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_BP m
				WHERE	0=0
				AND	m.BP_CD = w.BP
				AND	m.DEL_FLG = C_OFF
				)
		;
	BP_R	BP%ROWTYPE;

	CURSOR DPT IS
		SELECT	w.TBL	TBL,
			w.DPT	DPT
		FROM	(
			SELECT	DISTINCT
				'MGT_ACT_PURC_IF'	TBL,
				t.MNG_DPT_CD	DPT
			FROM	MGT_ACT_PURC_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_PURC_IF'	TBL,
				t.ALC_DPT_CD	DPT
			FROM	MGT_ACT_PURC_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_INPT_IF'	TBL,
				t.MNG_DPT_CD	DPT
			FROM	MGT_ACT_INPT_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_OTHER_WK_IF'	TBL,
				t.DPT_CD	DPT
			FROM	MGT_ACT_OTHER_WK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.DPT_CD IS NOT NULL
			AND	I_MFG = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.MNG_DPT_CD	DPT
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.SLS_DPT_CD	DPT
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.SLS_DPT_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_SLS_IF'	TBL,
				t.ALC_DPT_CD	DPT
			FROM	MGT_ACT_SLS_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_DPT_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.MNG_DPT_CD	DPT
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.OTHER_DPT_CD	DPT
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.OTHER_DPT_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_IO_IF'	TBL,
				t.ALC_DPT_CD	DPT
			FROM	MGT_ACT_IO_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	t.ALC_DPT_CD IS NOT NULL
			AND	I_TRAN = C_ON
			UNION ALL
			SELECT	DISTINCT
				'MGT_ACT_STK_IF'	TBL,
				t.MNG_DPT_CD	DPT
			FROM	MGT_ACT_STK_IF t
			WHERE	0=0
			AND	t.YM = I_YM
			AND	t.CALC_CTG_CD = I_CALC_CTG
			AND	t.WG_CD = I_WG_CD
			AND	I_STK = C_ON
			) w
		WHERE	0=0
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MAM_COST_DPT m
				WHERE	0=0
				AND	m.DPT_CD = w.DPT
				AND	m.TERM = G_TERM
				AND	m.DEL_FLG = C_OFF
				)
		;
	DPT_R	DPT%ROWTYPE ;
/*************************************************************************/
PROCEDURE P_CTG_WG_YM_ERR
AS
BEGIN
	L_MSG := FCPA_ERR.MSG_BINDER(L_CALC_CTG, L_WG_CD, FCPA_DATE_UTIL.F_TO_CHAR(L_YM, FCPA_DATE_UTIL.Y4M)) ;
	FCPA_ERR.RAISE_APP_ERR('MGBBD0043', L_MSG) ;
END ;
/*************************************************************************/
BEGIN
	--処理を開始しました。
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0001', 'MGPA_INS_MGTIF2MGT.P_IF') ;

	L_RC := C_OK ;

	L_TS := FCPA_DATE_UTIL.F_MCSYSTIMESTAMP ;
	L_USR := NVL(FCPA_CONTEXT.F_GET_USERID, FCPA_CONTEXT.F_GET_OS_USR) ;

	--期の取得
	G_TERM := MAPA_TERM.F_GET_TERM_NE(I_YM) ;

	--IFパラメータの取得
	G_CO_PARM := MGPA_CO_PARM.F_GET_REC ;
	G_TMP_DPT := G_CO_PARM.TMP_DPT_CD ;
	L_STKTK_SUM := G_CO_PARM.STKTK_SUM_FLG ;
	L_OTH_CCN_SUM := G_CO_PARM.OTH_CCN_SUM_FLG ;
	G_LOT_USE_TYP := NVL(G_CO_PARM.LOT_USE_TYP, C_PS_USE1) ;
	G_SUBLOT_USE_TYP := NVL(G_CO_PARM.SUBLOT_USE_TYP, C_PS_USE1) ;
	G_SNO1_USE_TYP := NVL(G_CO_PARM.SNO1_USE_TYP, C_PS_USE1) ;
	G_SNO2_USE_TYP := NVL(G_CO_PARM.SNO2_USE_TYP, C_PS_USE1) ;
	G_SNO3_USE_TYP := NVL(G_CO_PARM.SNO3_USE_TYP, C_PS_USE1) ;
	G_SNO4_USE_TYP := NVL(G_CO_PARM.SNO4_USE_TYP, C_PS_USE1) ;
	G_ACT_TRD_CALC_CTG := G_CO_PARM.ACT_TRD_CALC_CTG_CD ;
	G_DEF_CALC_CTG := G_CO_PARM.DEF_CALC_CTG_CD ;

	IF I_MFG = C_ON THEN
		--経費配賦振替マスタによる振替処理が可能かチェック
		SELECT	MAX(t.WG_CD)
		INTO	L_WG_CD
		FROM	MGT_ACT_ALC_AMT t
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.ALC_REC_TYP = C_ALC_REC_PURC
		AND	t.PRE_ALC_FIN_FLG = C_ON
		AND	t.TRD_WG_CD = I_WG_CD
		AND	t.CALC_CTG_CD = I_CALC_CTG
		;

		IF L_WG_CD IS NOT NULL THEN
			L_MSG := FCPA_ERR.MSG_BINDER('MGT_ACT_ALC_AMT', I_CALC_CTG, L_WG_CD, I_WG_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M)) ;
			FCPA_ERR.RAISE_APP_ERR('MGBBD0014', L_MSG) ;
		END IF ;
	END IF ;

	IF I_MFG = C_ON OR I_TRAN = C_ON THEN
		FOR FIX_R IN (
			SELECT	DISTINCT
				t1.CALC_GRP_CD
			FROM	MGT_CALC_FIX t1, MGT_ARG t2
			WHERE	0=0
			AND	t1.YM = I_YM
			AND	t1.CALC_NO = t2.CALC_NO
			AND	t1.CALC_GRP_CD = t2.CALC_GRP_CD
			AND	t2.SA_TYP = MAC_SA_TYP.ACT
			)
		LOOP
			IF I_MFG = C_ON THEN
				--配賦費用実績が確定している場合、購買から配賦費用実績へ振り替えた実績が存在するとエラーとする
				SELECT	MAX(t.CALC_CTG_CD)
				INTO	L_CALC_CTG
				FROM	MGT_CTG_FIX t
				WHERE	0=0
				AND	t.CALC_GRP_CD = FIX_R.CALC_GRP_CD
				AND	t.YM = I_YM
				AND	t.CALC_CTG_TYP = MAC_CALC_CTG_TYP.ALC_AMT
				AND	t.CALC_CTG_CD = I_CALC_CTG
				;

				SELECT	MAX(t1.WG_CD)
				INTO	L_WG_CD
				FROM	MGT_ACT_ALC_AMT t1, MGT_WG_FIX t2
				WHERE	0=0
				AND	t1.ALC_REC_TYP = C_ALC_REC_PURC
				AND	t1.TRD_WG_CD = I_WG_CD
				AND	t2.CALC_GRP_CD = FIX_R.CALC_GRP_CD
				AND	t2.YM = I_YM
				AND	t1.WG_CD = t2.WG_CD
				AND	t1.YM = t2.YM
				;

				IF L_CALC_CTG IS NOT NULL AND L_WG_CD IS NOT NULL THEN
					L_MSG := FCPA_ERR.MSG_BINDER('MGT_ACT_ALC_AMT', FIX_R.CALC_GRP_CD, L_CALC_CTG, L_WG_CD, I_WG_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M)) ;
					FCPA_ERR.RAISE_APP_ERR('MGBBD0019', L_MSG) ;
				END IF ;
			END IF ;

			IF I_TRAN = C_ON THEN
				--投入実績が確定している場合、入出庫から投入へ振り替える設定がされているとエラーとする
				SELECT	MAX(t.CALC_CTG_CD)
				INTO	L_CALC_CTG
				FROM	MGT_CTG_FIX t
				WHERE	0=0
				AND	t.CALC_GRP_CD = FIX_R.CALC_GRP_CD
				AND	t.YM = I_YM
				AND	t.CALC_CTG_TYP = MAC_CALC_CTG_TYP.INPT
				AND	t.CALC_CTG_CD = I_CALC_CTG
				;

				SELECT	MAX(t.WG_CD)
				INTO	L_WG_CD
				FROM	MGT_WG_FIX t
				WHERE	0=0
				AND	t.CALC_GRP_CD = FIX_R.CALC_GRP_CD
				AND	t.YM = I_YM
				AND	t.WG_CD = I_WG_CD
				;

				IF L_CALC_CTG IS NOT NULL AND L_WG_CD IS NOT NULL THEN
					SELECT	COUNT(*)
					INTO	L_CNT
					FROM	MAM_ACT_IO m
					WHERE	0=0
					AND	m.CALC_CTG_CD = I_CALC_CTG
					AND	m.WG_CD = I_WG_CD
					AND	m.IO_TRANS_TYP = C_TRANS_INPT
					AND	I_YM BETWEEN m.ST_DT AND m.END_DT
					;

					IF L_CNT > 0 THEN
						L_MSG := FCPA_ERR.MSG_BINDER('MGT_ACT_IO', FIX_R.CALC_GRP_CD, I_CALC_CTG, I_WG_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M)) ;
						FCPA_ERR.RAISE_APP_ERR('MGBXD0025', L_MSG) ;
					END IF ;

					SELECT	COUNT(*)
					INTO	L_CNT
					FROM	MGT_ACT_IO_IF t
					WHERE	0=0
					AND	t.CALC_CTG_CD = I_CALC_CTG
					AND	t.WG_CD = I_WG_CD
					AND	t.YM = I_YM
					AND	t.MFG_ACT_GRP IS NOT NULL
					;

					IF L_CNT > 0 THEN
						L_MSG := FCPA_ERR.MSG_BINDER(FIX_R.CALC_GRP_CD, I_CALC_CTG, I_WG_CD, FCPA_DATE_UTIL.F_TO_CHAR(I_YM, FCPA_DATE_UTIL.Y4M)) ;
						FCPA_ERR.RAISE_APP_ERR('MGBXD0048', L_MSG) ;
					END IF ;
				END IF ;
			END IF ;
		END LOOP ;
	END IF ;

	IF I_DEL = C_ON OR G_CO_PARM.CHK_MST_FLG = C_OFF THEN
		GOTO SKIP_CHK ;
	END IF ;

	G_PARM_ITM_SUB_TYP := MAPA_COMM.F_GET_PARM('ITM_SUB_TYP') ;

	--マスタチェック
	FOR ITM_R IN ITM LOOP
		L_RC := C_ERR1 ;
		FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0011', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2,
					ITM_R.TBL, MAPA_COMM.F_TO_DISP_ITM(ITM_R.ITM_CD, ITM_R.ITM_SUB1, ITM_R.ITM_SUB2, ITM_R.ITM_SUB3, G_PARM_ITM_SUB_TYP)) ;
	END LOOP ;

	FOR LOC_R IN LOC LOOP
		L_RC := C_ERR1 ;
		FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0010', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, LOC_R.TBL, LOC_R.LOC) ;
	END LOOP ;

	FOR BP_R IN BP LOOP
		L_RC := C_ERR1 ;
		FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0009', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, BP_R.TBL, BP_R.BP) ;
	END LOOP ;

	FOR DPT_R IN DPT LOOP
		L_RC := C_ERR1 ;
		FCPA_BATCH_LOG.P_DATA_LOG('MGBBD0008', G_LOG_NO, G_LOG_SUB_KEY1, G_LOG_SUB_KEY2, DPT_R.TBL, DPT_R.DPT, FCPA_DATE_UTIL.F_TO_CHAR(G_TERM, FCPA_DATE_UTIL.Y4M)) ;
	END LOOP ;

	IF L_RC = C_ERR1 THEN
		L_MSG := FCPA_ERR.MSG_BINDER('MGPA_INS_MGTIF2MGT') ;
		--マスタチェックでエラーが発生しました。{1}
		FCPA_ERR.RAISE_APP_ERR('MGBBD0012', L_MSG) ;
	END IF ;

	<<SKIP_CHK>>
		NULL ;

	--該当月のデータは削除
	IF I_MFG = C_ON THEN
		DELETE	MGT_ACT_ALC_AMT t
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.CALC_CTG_CD = I_CALC_CTG
		AND	t.TRD_WG_CD = I_WG_CD
		AND	t.ALC_REC_TYP = C_ALC_REC_PURC
		;

		DELETE	MGT_ACT_INPT_EXPNS t
		WHERE	0=0
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_INPT w
				WHERE	0=0
				AND	w.YM = I_YM
				AND	w.CALC_CTG_CD = I_CALC_CTG
				AND	w.WG_CD = I_WG_CD
				AND	w.ACT_INPT_ID = t.ACT_INPT_ID
				AND	w.ACT_INPT_ID_SUB = t.ACT_INPT_ID_SUB
				)
		;

		DELETE MGT_ACT_MFG 	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
		DELETE MGT_ACT_INST_WIP	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
		DELETE MGT_ACT_PURC	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
		DELETE MGT_ACT_INPT	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD AND t.MFG_ACT_GRP IS NULL ;
		DELETE MGT_ACT_INST_WK	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
		DELETE MGT_ACT_OTHER_WK	t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
	END IF ;

	IF I_TRAN = C_ON THEN
		DELETE	MGT_ACT_INPT t
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.CALC_CTG_CD = I_CALC_CTG
		AND	t.WG_CD = I_WG_CD
		AND	MAC_AC_SLIP_TYP.IS_ACXFER_TYP(t.AC_SLIP_TYP) = '1'
		;

		DELETE	MGT_ACT_INPT t
		WHERE	0=0
		AND	t.YM = I_YM
		AND	t.CALC_CTG_CD = I_CALC_CTG
		AND	t.WG_CD = I_WG_CD
		AND	t.MFG_ACT_GRP IS NOT NULL
		;

		DELETE 	MGT_ACT_IO_EXPNS t
		WHERE	0=0
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_IO w
				WHERE	0=0
				AND	w.YM = I_YM
				AND	w.CALC_CTG_CD = I_CALC_CTG
				AND	w.WG_CD = I_WG_CD
				AND	t.ACT_IO_ID = w.ACT_IO_ID
				AND	t.ACT_IO_ID_SUB = w.ACT_IO_ID_SUB
				)
		;

		DELETE	MGT_ACT_SLS_EXPNS t
		WHERE	0=0
		AND	EXISTS (
				SELECT	'X'
				FROM	MGT_ACT_SLS w
				WHERE	0=0
				AND	w.YM = I_YM
				AND	w.CALC_CTG_CD = I_CALC_CTG
				AND	w.WG_CD = I_WG_CD
				AND	t.ACT_SLS_ID = w.ACT_SLS_ID
				AND	t.ACT_SLS_ID_SUB = w.ACT_SLS_ID_SUB
				)
		;

		DELETE MGT_ACT_IO  t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
		DELETE MGT_ACT_SLS t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
	END IF ;

	IF I_STK = C_ON THEN
		DELETE MGT_ACT_STK t WHERE t.YM = I_YM AND t.CALC_CTG_CD = I_CALC_CTG AND t.WG_CD = I_WG_CD ;
	END IF ;

	IF I_DEL = C_ON THEN
		GOTO PROD_END ;
	END IF ;

	DELETE MGW_WIO w ;
	DELETE MGW_WIO2 w ;
	DELETE MGW_IO w ;

	IF I_MFG = C_OFF THEN
		GOTO SKIP_MFG ;
	END IF ;

	--製造実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_MFG_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_MFG w
			WHERE	0=0
			AND	w.ACT_MFG_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	INSERT INTO MGT_ACT_MFG (
		ACT_MFG_ID,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		LOC_CD, STR_LN_CD,
		AC_SLIP_TYP, AC_RSN_CD,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		MFG_PER,
		MFG_COST_RATIO,
		EXPNS_CD,
		ALC_VAL1, ALC_VAL2, ALC_VAL3, ALC_VAL4, ALC_VAL5
		)
	SELECT	MAX(t.ACT_MFG_ID),
		t.CALC_CTG_CD,
		t.WG_CD,
		t.YM, MAX(t.AC_DT),
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.ITM_MFG_INST_NO,
		t.MFG_ACT_NO,
		t.OPER_ACT_NO,
		t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
		t.LOC_CD, t.STR_LN_CD,
		t.AC_SLIP_TYP, t.AC_RSN_CD,
		SUM(t.QTY), SUM(t.AMT),
		t.TRD_CUR_CD,
		SUM(t.TRD_CUR_AMT),
		t.XRATE,
		MAX(t.MFG_PER),
		SUM(t.MFG_COST_RATIO),
		t.EXPNS_CD,
		SUM(t.ALC_VAL1), SUM(t.ALC_VAL2), SUM(t.ALC_VAL3), SUM(t.ALC_VAL4), SUM(t.ALC_VAL5)
	FROM	(
		SELECT	MAX(TO_CHAR(x.DATA_LNO))	ACT_MFG_ID,
			x.CALC_CTG_CD,
			x.WG_CD,
			x.YM,
			MAX(x.AC_DT)	AC_DT,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.ITM_MFG_INST_NO,
			x.MFG_ACT_NO,
			x.OPER_ACT_NO,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.LOC_CD, x.STR_LN_CD,
			x.AC_SLIP_TYP, x.AC_RSN_CD,
			SUM(x.QTY)	QTY,
			SUM(x.AMT)	AMT,
			x.TRD_CUR_CD,
			SUM(x.TRD_CUR_AMT)	TRD_CUR_AMT,
			x.XRATE,
			x.MFG_PER,
			SUM(x.MFG_COST_RATIO)	MFG_COST_RATIO,
			x.EXPNS_CD,
			SUM(x.ALC_VAL1)	ALC_VAL1,
			SUM(x.ALC_VAL2)	ALC_VAL2,
			SUM(x.ALC_VAL3)	ALC_VAL3,
			SUM(x.ALC_VAL4)	ALC_VAL4,
			SUM(x.ALC_VAL5)	ALC_VAL5
		FROM	MGT_ACT_MFG_IF x
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		GROUP BY x.CALC_CTG_CD,
			x.WG_CD,
			x.YM,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.ITM_MFG_INST_NO,
			x.MFG_ACT_NO,
			x.OPER_ACT_NO,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.LOC_CD, x.STR_LN_CD,
			x.AC_SLIP_TYP, x.AC_RSN_CD,
			x.TRD_CUR_CD,
			x.XRATE,
			x.MFG_PER,
			x.EXPNS_CD
		) t
	WHERE	0=0
	AND	(t.QTY <> 0 OR t.AMT <> 0 OR t.TRD_CUR_AMT <> 0
			OR t.ALC_VAL1 <> 0 OR t.ALC_VAL2 <> 0 OR t.ALC_VAL3 <> 0 OR t.ALC_VAL4 <> 0 OR t.ALC_VAL5 <> 0)
	GROUP BY t.CALC_CTG_CD,
		t.WG_CD,
		t.YM,
		t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.ITM_MFG_INST_NO,
		t.MFG_ACT_NO,
		t.OPER_ACT_NO,
		t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
		t.LOC_CD, t.STR_LN_CD,
		t.AC_SLIP_TYP, t.AC_RSN_CD,
		t.TRD_CUR_CD,
		t.XRATE,
		t.EXPNS_CD
	;

	DELETE	MGT_ACT_MFG x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	AND	NVL(x.AMT, 0) = 0
	AND	NVL(x.TRD_CUR_AMT, 0) = 0
	AND	NVL(x.ALC_VAL1, 0) = 0
	AND	NVL(x.ALC_VAL2, 0) = 0
	AND	NVL(x.ALC_VAL3, 0) = 0
	AND	NVL(x.ALC_VAL4, 0) = 0
	AND	NVL(x.ALC_VAL5, 0) = 0
	;

	--指図仕掛実績の取込
	INSERT INTO MGT_ACT_INST_WIP (
		CALC_CTG_CD,
		WG_CD,
		YM,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		AC_RSN_CD,
		WIP_QTY, WIP_PER
		)
	SELECT	x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		x.OPER_ACT_NO,
		x.LOC_CD, x.STR_LN_CD,
		x.AC_RSN_CD,
		x.WIP_QTY, x.WIP_PER
	FROM	MGT_ACT_INST_WIP_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	;

	DELETE	MGT_ACT_INST_WIP x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.WIP_QTY = 0
	;

	--購買実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_PURC_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_PURC w
			WHERE	0=0
			AND	w.ACT_PURC_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	--経費関連は取込まない
	INSERT INTO MGT_ACT_PURC (
		ACT_PURC_ID,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		SPPL_CD,
		PO_NO, SLO_NO, IV_NO,
		ALC_DPT_CD,
		AC_SLIP_TYP, AC_RSN_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		EXPNS_CD,
		ALC_VAL1, ALC_VAL2, ALC_VAL3, ALC_VAL4, ALC_VAL5
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.SPPL_CD,
		x.PO_NO, x.SLO_NO, x.IV_NO,
		x.ALC_DPT_CD,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.EXPNS_CD,
		SUM(x.ALC_VAL1), SUM(x.ALC_VAL2), SUM(x.ALC_VAL3), SUM(x.ALC_VAL4), SUM(x.ALC_VAL5)
	FROM	MGT_ACT_PURC_IF x, MAM_ITM_SRCH m
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.ITM_CD = m.ITM_CD
	AND	x.ITM_SUB1 = m.ITM_SUB1
	AND	x.ITM_SUB2 = m.ITM_SUB2
	AND	x.ITM_SUB3 = m.ITM_SUB3
	AND	m.ASSET_MNG_TYP = C_ASSET_MNG_MNG
	AND	m.DEL_FLG = C_OFF
	AND	m.RELEASE_FLG = C_ON
	AND	x.AC_SLIP_TYP NOT IN (C_PURC_XPNS, C_PURC_RET_XPNS, C_PURC_DSCNT_XPNS, C_PURC_XTRA_XPNS)
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.SPPL_CD,
		x.PO_NO, x.SLO_NO, x.IV_NO,
		x.ALC_DPT_CD,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.EXPNS_CD
	;

	DELETE	MGT_ACT_PURC x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	AND	x.AMT = 0
	AND	NVL(x.TRD_CUR_AMT, 0) = 0
	AND	NVL(x.ALC_VAL1, 0) = 0
	AND	NVL(x.ALC_VAL2, 0) = 0
	AND	NVL(x.ALC_VAL3, 0) = 0
	AND	NVL(x.ALC_VAL4, 0) = 0
	AND	NVL(x.ALC_VAL5, 0) = 0
	;

	INSERT INTO MGT_ACT_ALC_AMT (
		ACT_ALC_AMT_KEY,
		CALC_CTG_CD,
		ALC_REC_TYP,
		WG_CD,
		YM,
		ALC_AC_CD,
		DPT_CD, LOC_CD, OPER_CD,
		BP_CD, CTG_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		ITM_MFG_INST_NO, IV_NO, PO_NO, SLO_NO,
		AMT,
		TRD_WG_CD, TRD_CALC_GRP_CD, TRD_CALC_NO,
		PRE_ALC_FIN_FLG
		)
	SELECT	MAPA_NUM.F_GET_SEQ(C_NUM_SYS_ALC),
		t.CALC_CTG_CD,
		C_ALC_REC_PURC,
		t.WG_CD,
		t.YM,
		t.ALC_AC_CD,
		t.DPT_CD, t.LOC_CD, t.OPER_CD,
		t.BP_CD, t.CTG_CD, t.ITM_CD, t.ITM_SUB1, t.ITM_SUB2, t.ITM_SUB3,
		t.LOT_NO, t.SUBLOT_NO, t.SNO1, t.SNO2, t.SNO3, t.SNO4,
		t.ITM_MFG_INST_NO, t.IV_NO, t.PO_NO, t.SLO_NO,
		t.AMT,
		t.TRD_WG_CD, t.TRD_CALC_GRP_CD, t.TRD_CALC_NO,
		C_OFF
	FROM	(
		SELECT	x.CALC_CTG_CD	CALC_CTG_CD,
			NVL(m.ALC_WG_CD, x.WG_CD)	WG_CD,
			x.YM	YM,
			m.ALC_AC_CD	ALC_AC_CD,
			DECODE(m.DPT_FLG, C_OFF, m.DPT_CD, x.ALC_DPT_CD)	DPT_CD,
			NVL(x.ALC_LOC_CD, m.LOC_CD)	LOC_CD,
			NVL(x.ALC_OPER_CD, m.OPER_CD)	OPER_CD,
			DECODE(m.BP_FLG, C_OFF, m.BP_CD, x.SPPL_CD)	BP_CD,
			NVL(x.ALC_CTG_CD, m.CTG_CD)	CTG_CD,
			m.ITM_CD	ITM_CD,
			m.ITM_SUB1	ITM_SUB1,
			m.ITM_SUB2	ITM_SUB2,
			m.ITM_SUB3	ITM_SUB3,
			DECODE(m.LOT_NO_FLG, C_OFF, m.LOT_NO, DECODE(x.LOT_NO, C_NULL_VAL, NULL, x.LOT_NO))	LOT_NO,
			DECODE(m.SUBLOT_NO_FLG, C_OFF, m.SUBLOT_NO, DECODE(x.SUBLOT_NO, C_NULL_VAL, NULL, x.SUBLOT_NO))	SUBLOT_NO,
			DECODE(m.SNO1_FLG, C_OFF, m.SNO1, DECODE(x.SNO1, C_NULL_VAL, NULL, x.SNO1))	SNO1,
			DECODE(m.SNO2_FLG, C_OFF, m.SNO2, DECODE(x.SNO2, C_NULL_VAL, NULL, x.SNO2))	SNO2,
			DECODE(m.SNO3_FLG, C_OFF, m.SNO3, DECODE(x.SNO3, C_NULL_VAL, NULL, x.SNO3))	SNO3,
			DECODE(m.SNO4_FLG, C_OFF, m.SNO4, DECODE(x.SNO4, C_NULL_VAL, NULL, x.SNO4))	SNO4,
			NULL	ITM_MFG_INST_NO,
			DECODE(m.IV_NO_FLG, C_OFF, NULL, x.IV_NO)	IV_NO,
			DECODE(m.PO_NO_FLG, C_OFF, NULL, x.PO_NO)	PO_NO,
			DECODE(m.SLO_NO_FLG, C_OFF, NULL, x.SLO_NO)	SLO_NO,
			SUM(x.AMT)	AMT,
			x.WG_CD	TRD_WG_CD,
			NULL	TRD_CALC_GRP_CD,
			NULL	TRD_CALC_NO
		FROM	MGT_ACT_PURC_IF x, MAM_XPNS_PURC_ALC m
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	x.ITM_CD = m.XPNS_ITM_CD
		AND	x.ITM_SUB1 = m.XPNS_ITM_SUB1
		AND	x.ITM_SUB2 = m.XPNS_ITM_SUB2
		AND	x.ITM_SUB3 = m.XPNS_ITM_SUB3
		AND	x.AC_RSN_CD = m.AC_RSN_CD
		AND	x.CALC_CTG_CD = m.CALC_CTG_CD
		AND	x.WG_CD = m.WG_CD
		AND	x.AC_DT BETWEEN m.ST_DT AND m.END_DT
		GROUP BY x.CALC_CTG_CD,
			NVL(m.ALC_WG_CD, x.WG_CD),
			x.YM,
			m.ALC_AC_CD,
			DECODE(m.DPT_FLG, C_OFF, m.DPT_CD, x.ALC_DPT_CD),
			NVL(x.ALC_LOC_CD, m.LOC_CD),
			NVL(x.ALC_OPER_CD, m.OPER_CD),
			DECODE(m.BP_FLG, C_OFF, m.BP_CD, x.SPPL_CD),
			NVL(x.ALC_CTG_CD, m.CTG_CD),
			m.ITM_CD,
			m.ITM_SUB1,
			m.ITM_SUB2,
			m.ITM_SUB3,
			DECODE(m.LOT_NO_FLG, C_OFF, m.LOT_NO, DECODE(x.LOT_NO, C_NULL_VAL, NULL, x.LOT_NO)),
			DECODE(m.SUBLOT_NO_FLG, C_OFF, m.SUBLOT_NO, DECODE(x.SUBLOT_NO, C_NULL_VAL, NULL, x.SUBLOT_NO)),
			DECODE(m.SNO1_FLG, C_OFF, m.SNO1, DECODE(x.SNO1, C_NULL_VAL, NULL, x.SNO1)),
			DECODE(m.SNO2_FLG, C_OFF, m.SNO2, DECODE(x.SNO2, C_NULL_VAL, NULL, x.SNO2)),
			DECODE(m.SNO3_FLG, C_OFF, m.SNO3, DECODE(x.SNO3, C_NULL_VAL, NULL, x.SNO3)),
			DECODE(m.SNO4_FLG, C_OFF, m.SNO4, DECODE(x.SNO4, C_NULL_VAL, NULL, x.SNO4)),
			DECODE(m.IV_NO_FLG, C_OFF, NULL, x.IV_NO),
			DECODE(m.PO_NO_FLG, C_OFF, NULL, x.PO_NO),
			DECODE(m.SLO_NO_FLG, C_OFF, NULL, x.SLO_NO),
			x.WG_CD
		HAVING SUM(x.AMT) <> 0
		) t
	WHERE 0=0
	;

	--投入実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_INPT_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_INPT w
			WHERE	0=0
			AND	w.ACT_INPT_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	INSERT INTO MGT_ACT_INPT (
		ACT_INPT_ID,
		ACT_INPT_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		PAR_ITM_CD, PAR_ITM_SUB1, PAR_ITM_SUB2, PAR_ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		AC_SLIP_TYP, AC_RSN_CD,
		STK_BP_CD, ASST_TYP,
		BP_CD,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		REC_EVAL_TYP,
		EXPNS_CD,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.PAR_ITM_CD, x.PAR_ITM_SUB1, x.PAR_ITM_SUB2, x.PAR_ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		x.OPER_ACT_NO,
		x.LOC_CD, x.STR_LN_CD,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.STK_BP_CD, x.ASST_TYP,
		CASE WHEN x.AC_SLIP_TYP = C_IN_ONR
				AND m.REPURC_OBLI_FLG = C_ON
				AND x.ASST_TYP IN (C_ASST1, C_ASST2) THEN x.STK_BP_CD
			ELSE NULL
		END,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.REC_EVAL_TYP,
		x.EXPNS_CD,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_INPT_IF x
		LEFT OUTER JOIN MAM_BP m ON (x.STK_BP_CD = m.BP_CD)
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.PAR_ITM_CD, x.PAR_ITM_SUB1, x.PAR_ITM_SUB2, x.PAR_ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		x.OPER_ACT_NO,
		x.LOC_CD, x.STR_LN_CD,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.STK_BP_CD, x.ASST_TYP,
		CASE WHEN x.AC_SLIP_TYP = C_IN_ONR
				AND m.REPURC_OBLI_FLG = C_ON
				AND x.ASST_TYP IN (C_ASST1, C_ASST2) THEN x.STK_BP_CD
			ELSE NULL
		END,
		x.TRD_CUR_CD,
		x.XRATE,
		x.REC_EVAL_TYP,
		x.EXPNS_CD,
		x.ZERO_EFFECT_FLG
	;

	DELETE	MGT_ACT_INPT x
	WHERE 	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	AND	NVL(x.AMT, 0) = 0
	AND	NVL(x.TRD_CUR_AMT, 0) = 0
	AND	x.ZERO_EFFECT_FLG = C_OFF
	;

	UPDATE	MGT_ACT_INPT t
	SET	t.STK_BP_CD =
			(
			SELECT	/*+INDEX(w MGT_ITM_MFG_INST_ALL_PK)*/
				MAX(w.SPPL_CD)
			FROM	MGT_ITM_MFG_INST w
			WHERE	0=0
			AND	w.CALC_CTG_CD = t.CALC_CTG_CD
			AND	w.ITM_CD = t.PAR_ITM_CD
			AND	w.ITM_SUB1 = t.PAR_ITM_SUB1
			AND	w.ITM_SUB2 = t.PAR_ITM_SUB2
			AND	w.ITM_SUB3 = t.PAR_ITM_SUB3
			AND	w.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
			AND	w.MFG_ACT_NO = t.MFG_ACT_NO
			AND	w.SPPL_CD IS NOT NULL
			)
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	t.STK_BP_CD IS NULL
	AND	EXISTS (
			SELECT	/*+INDEX(x MGT_ITM_MFG_INST_ALL_PK)*/
				'X'
			FROM	MGT_ITM_MFG_INST x
			WHERE	0=0
			AND	x.CALC_CTG_CD = t.CALC_CTG_CD
			AND	x.ITM_CD = t.PAR_ITM_CD
			AND	x.ITM_SUB1 = t.PAR_ITM_SUB1
			AND	x.ITM_SUB2 = t.PAR_ITM_SUB2
			AND	x.ITM_SUB3 = t.PAR_ITM_SUB3
			AND	x.ITM_MFG_INST_NO = t.ITM_MFG_INST_NO
			AND	x.MFG_ACT_NO = t.MFG_ACT_NO
			AND	x.SPPL_CD IS NOT NULL
		)
	;

	--指図工数実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_INST_WK_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_INST_WK w
			WHERE	0=0
			AND	w.ACT_INST_WK_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	INSERT INTO MGT_ACT_INST_WK (
		ACT_INST_WK_ID,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		ITM_MFG_INST_NO,
		MFG_ACT_NO,
		OPER_ACT_NO,
		LOC_CD, STR_LN_CD,
		WK_COST_CD,
		WK_RSN_CD,
		WK_COST
		)
	SELECT	MAX(x.DATA_LNO),
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		x.OPER_ACT_NO,
		x.LOC_CD, x.STR_LN_CD,
		x.WK_COST_CD,
		x.WK_RSN_CD,
		SUM(x.WK_COST)
	FROM	MGT_ACT_INST_WK_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.ITM_MFG_INST_NO,
		x.MFG_ACT_NO,
		x.OPER_ACT_NO,
		x.LOC_CD, x.STR_LN_CD,
		x.WK_COST_CD,
		x.WK_RSN_CD
	;

	DELETE	MGT_ACT_INST_WK x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.WK_COST = 0
	;

	--指図外工数実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_OTHER_WK_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_OTHER_WK w
			WHERE	0=0
			AND	w.ACT_OTHER_WK_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	--指図外工数実績ＩＦの指図工数実績への振替
	P_OTHER_WK_TO_INST_WK(I_CALC_CTG, I_WG_CD, I_YM) ;

	INSERT INTO MGT_ACT_OTHER_WK (
		ACT_OTHER_WK_ID,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		DPT_CD, CTG_CD,
		LOC_CD, OPER_CD,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		WK_COST_CD,
		WK_RSN_CD,
		WK_COST
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.DPT_CD, x.CTG_CD,
		x.LOC_CD, x.OPER_CD,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.WK_COST_CD,
		x.WK_RSN_CD,
		SUM(x.WK_COST)
	FROM	MGW_ACT_OTHER_WK_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.DPT_CD, x.CTG_CD,
		x.LOC_CD, x.OPER_CD,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.WK_COST_CD,
		x.WK_RSN_CD
	;

	DELETE 	MGT_ACT_OTHER_WK x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.WK_COST = 0
	;

	<<SKIP_MFG>>
		NULL ;

	IF I_TRAN = C_OFF THEN
		GOTO SKIP_TRAN ;
	END IF ;

	--無償支給、有償支給、出荷のデータチェック
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_IO_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	NVL(t.OTHER_WG_CD, t.WG_CD) = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_IO w
			WHERE	0=0
			AND	w.ACT_IO_ID = TO_CHAR(t.DATA_LNO)
			AND	w.ACT_IO_ID_SUB = '0'
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			AND	w.AC_SLIP_TYP IN (
					C_FFR_PROV, C_FFR_PRVR,
					C_ONR_PROV, C_ONR_PRVR,
					C_SHIP, C_SHIP_RET
					)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	--無償支給の取込
	INSERT INTO MGT_ACT_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP,
		AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		REC_EVAL_TYP,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),			--ワーキンググループ違いの支給は部門振替を作成する
		x.YM, MAX(x.AC_DT),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),		--部門違いの支給は部門振替を作成する
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		C_IO_FFR_PROV,		--無償支給
		CASE WHEN SUM(x.QTY) >= 0
			THEN C_FFR_PROV	--無償支給
			ELSE C_FFR_PRVR	--無償支給戻
		END,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.BP_CD, NULL,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_IO_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	NVL(x.OTHER_WG_CD, x.WG_CD) = I_WG_CD
	AND	x.AC_SLIP_TYP IN (C_FFR_PROV, C_FFR_PRVR)
	GROUP BY
		x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		x.YM,
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		x.BP_CD,
		x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	;

	--有償支給の取込
	INSERT INTO MGT_ACT_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP,
		AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		REC_EVAL_TYP,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),			--ワーキンググループ違いの支給は部門振替を作成する
		x.YM, MAX(x.AC_DT),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),		--部門違いの支給は部門振替を作成する
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		C_IO_ONR_PROV,		--有償支給
		CASE WHEN SUM(x.QTY) >= 0
			THEN C_ONR_PROV	--有償支給
			ELSE C_ONR_PRVR	--有償支給戻
		END,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.BP_CD, NULL,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_IO_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	NVL(x.OTHER_WG_CD, x.WG_CD) = I_WG_CD
	AND	x.AC_SLIP_TYP IN (C_ONR_PROV, C_ONR_PRVR)
	GROUP BY
		x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		x.YM,
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		x.BP_CD,
		x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	;

	--出荷の取込
	INSERT INTO MGT_ACT_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP,
		AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		REC_EVAL_TYP,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),			--ワーキンググループ違いの出荷は部門振替を作成する
		x.YM, MAX(x.AC_DT),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),		--部門違いの出荷は部門振替を作成する
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		C_IO_STK_IO,		--入出庫
		CASE WHEN SUM(x.QTY) >= 0
			THEN C_SHIP	--出荷
			ELSE C_SHIP_RET	--出荷返品
		END,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.BP_CD, NULL,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_IO_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	NVL(x.OTHER_WG_CD, x.WG_CD) = I_WG_CD
	AND	x.AC_SLIP_TYP IN (C_SHIP, C_SHIP_RET)
	GROUP BY x.CALC_CTG_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		x.YM,
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_RSN_CD,
		DECODE(x.WG_CD, x.OTHER_WG_CD, NULL, x.OTHER_WG_CD),
		x.BP_CD,
		x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	;

	--ワーキンググループ、部門違いの支給、出荷は部門振替を作成する
	INSERT INTO MGW_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP,
		AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		TRD_GRP,
		REC_EVAL_TYP,
		SML_KEY,
		ITM_JNL_CD,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'1',
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		C_IO_STK_OUT,
		C_DPT_XFR_SO,
		x.AC_RSN_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		NULL, NULL,
		x.ASST_TYP,
		SUM(x.QTY), NULL,
		NULL,
		NULL,
		NULL,
		MAX(TO_CHAR(x.DATA_LNO)),
		x.REC_EVAL_TYP,
		TO_CHAR(x.YM, 'YYYYMMDD'),
		C_NULL_VAL,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_IO_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	(x.WG_CD = I_WG_CD OR x.OTHER_WG_CD = I_WG_CD)
	AND	x.AC_SLIP_TYP IN (
				C_FFR_PROV, C_FFR_PRVR, C_ONR_PROV, C_ONR_PRVR,
				C_SHIP, C_SHIP_RET
				)
	AND	(x.WG_CD <> x.OTHER_WG_CD OR x.MNG_DPT_CD <> x.OTHER_DPT_CD)
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_RSN_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.ASST_TYP,
		x.REC_EVAL_TYP,
		TO_CHAR(x.YM, 'YYYYMMDD'),
		x.ZERO_EFFECT_FLG
	;

	--生販連携、部門振替、在庫振替の出庫、入庫実績の取込
	INSERT INTO MGW_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		TRD_GRP, TRD_RATIO,
		REC_EVAL_TYP,
		SML_KEY,
		ITM_JNL_CD,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		CASE
		WHEN x.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO)
			THEN C_IO_STK_OUT	--出庫
		WHEN x.AC_SLIP_TYP = C_STK_SW_GR
			THEN C_IO_STK_IN	--入庫
		END,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.BP_CD, x.STK_BP_CD,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.TRD_GRP, SUM(x.TRD_RATIO),
		x.REC_EVAL_TYP,
		TO_CHAR(x.YM, 'YYYYMMDD'),
		m.ITM_JNL_CD,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_IO_IF x, MAM_ITM_SRCH m
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	(
		x.WG_CD = I_WG_CD
		OR
		x.AC_SLIP_TYP IN (C_DPT_XFR_SO, C_PROD_ITM_SO, C_PROD_ITM_RET_SO)
			AND x.OTHER_WG_CD = I_WG_CD
		)
	AND	x.ITM_CD = m.ITM_CD
	AND	x.ITM_SUB1 = m.ITM_SUB1
	AND	x.ITM_SUB2 = m.ITM_SUB2
	AND	x.ITM_SUB3 = m.ITM_SUB3
	AND	m.DEL_FLG = C_OFF
	AND	m.RELEASE_FLG = C_ON
	AND	x.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO, C_STK_SW_GR)
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		CASE
		WHEN x.AC_SLIP_TYP IN (C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO)
			THEN C_IO_STK_OUT	--出庫
		WHEN x.AC_SLIP_TYP = C_STK_SW_GR
			THEN C_IO_STK_IN	--入庫
		END,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		NVL(x.OTHER_WG_CD, x.WG_CD),
		NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
		x.BP_CD,
		x.STK_BP_CD, x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.TRD_GRP,
		x.REC_EVAL_TYP,
		TO_CHAR(x.YM, 'YYYYMMDD'),
		m.ITM_JNL_CD,
		x.ZERO_EFFECT_FLG
	;

	--検査抜取、廃棄・除却、棚卸、他勘定の出庫実績の取込
	INSERT INTO MGW_IO (
		ACT_IO_ID,
		ACT_IO_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP,
		AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD,
		BP_CD, STK_BP_CD,
		ASST_TYP,
		QTY,
		AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		ALC_AC_CD,
		ALC_AMT_FLG,
		ALC_WG_CD,
		ALC_DPT_CD, ALC_LOC_CD, ALC_OPER_CD, ALC_BP_CD,
		ALC_CTG_CD, ALC_ITM_CD, ALC_ITM_SUB1, ALC_ITM_SUB2, ALC_ITM_SUB3,
		ALC_LOT_NO, ALC_SUBLOT_NO, ALC_SNO1, ALC_SNO2, ALC_SNO3, ALC_SNO4,
		ALC_ITM_MFG_INST_NO,
		REC_EVAL_TYP,
		SML_KEY,
		ITM_JNL_CD,
		ZERO_EFFECT_FLG,
		MFG_ACT_GRP
		)
	SELECT	x2.ACT_IO_ID,
		'0',
		x2.CALC_CTG_CD,
		x2.WG_CD,
		x2.YM, x2.AC_DT,
		x2.MNG_DPT_CD,
		x2.ITM_CD, x2.ITM_SUB1, x2.ITM_SUB2, x2.ITM_SUB3,
		x2.LOT_NO, x2.SUBLOT_NO, x2.SNO1, x2.SNO2, x2.SNO3, x2.SNO4,
		C_IO_STK_OUT,	--出庫
		CASE
			WHEN L_STKTK_SUM = C_OFF AND x2.AC_SLIP_TYP = C_SO_STKTK THEN
				CASE
					WHEN x2.QTY >= 0 THEN C_SO_STKTK	--棚卸出庫
					WHEN x2.QTY < 0 THEN C_IN_STKTK		--棚卸入庫
				END
			WHEN L_OTH_CCN_SUM = C_OFF AND x2.AC_SLIP_TYP = C_OTH_CCN_SO THEN
				CASE
					WHEN x2.QTY >= 0 THEN C_OTH_CCN_SO	--他勘定出庫
					WHEN x2.QTY < 0 THEN C_OTH_CCN_GR	--他勘定入庫
				END
			ELSE x2.AC_SLIP_TYP
		END, x2.AC_RSN_CD,
		x2.OTHER_WG_CD,
		x2.OTHER_DPT_CD,
		x2.BP_CD, x2.STK_BP_CD,
		x2.ASST_TYP,
		x2.QTY,
		x2.AMT,
		x2.TRD_CUR_CD,
		x2.TRD_CUR_AMT,
		x2.XRATE,
		x2.ALC_AC_CD,
		x2.ALC_AMT_FLG,
		x2.ALC_WG_CD,
		x2.ALC_DPT_CD, x2.ALC_LOC_CD, x2.ALC_OPER_CD, x2.ALC_BP_CD,
		x2.ALC_CTG_CD, x2.ALC_ITM_CD, x2.ALC_ITM_SUB1, x2.ALC_ITM_SUB2, x2.ALC_ITM_SUB3,
		x2.ALC_LOT_NO, x2.ALC_SUBLOT_NO, x2.ALC_SNO1, x2.ALC_SNO2, x2.ALC_SNO3, x2.ALC_SNO4,
		x2.ALC_ITM_MFG_INST_NO,
		x2.REC_EVAL_TYP,
		x2.SML_KEY,
		m.ITM_JNL_CD,
		x2.ZERO_EFFECT_FLG,
		x2.MFG_ACT_GRP
	FROM (
		SELECT	MAX(TO_CHAR(x.DATA_LNO))	ACT_IO_ID,
			x.CALC_CTG_CD,
			x.WG_CD,
			x.YM, MAX(x.AC_DT)		AC_DT,
			x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			CASE
				WHEN L_STKTK_SUM = C_OFF AND x.AC_SLIP_TYP = C_IN_STKTK THEN C_SO_STKTK
				WHEN L_OTH_CCN_SUM = C_OFF AND x.AC_SLIP_TYP = C_OTH_CCN_GR THEN C_OTH_CCN_SO
				ELSE x.AC_SLIP_TYP
			END AC_SLIP_TYP, x.AC_RSN_CD,
			NVL(x.OTHER_WG_CD, x.WG_CD)	OTHER_WG_CD,
			NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD)	OTHER_DPT_CD,
			x.BP_CD, x.STK_BP_CD,
			x.ASST_TYP,
			SUM(x.QTY * CASE WHEN x.AC_SLIP_TYP IN (C_IN_STKTK, C_OTH_CCN_GR) THEN -1 ELSE 1 END)	QTY,
			SUM(x.AMT * CASE WHEN x.AC_SLIP_TYP IN (C_IN_STKTK, C_OTH_CCN_GR) THEN -1 ELSE 1 END)	AMT,
			x.TRD_CUR_CD,
			SUM(x.TRD_CUR_AMT * CASE WHEN x.AC_SLIP_TYP IN (C_IN_STKTK, C_OTH_CCN_GR) THEN -1 ELSE 1 END)	TRD_CUR_AMT,
			x.XRATE,
			x.ALC_AC_CD,
			x.ALC_AMT_FLG,
			x.ALC_WG_CD,
			x.ALC_DPT_CD, x.ALC_LOC_CD, x.ALC_OPER_CD, x.ALC_BP_CD,
			x.ALC_CTG_CD, x.ALC_ITM_CD, x.ALC_ITM_SUB1, x.ALC_ITM_SUB2, x.ALC_ITM_SUB3,
			x.ALC_LOT_NO, x.ALC_SUBLOT_NO, x.ALC_SNO1, x.ALC_SNO2, x.ALC_SNO3, x.ALC_SNO4,
			x.ALC_ITM_MFG_INST_NO,
			x.REC_EVAL_TYP,
			TO_CHAR(x.YM, 'YYYYMMDD')	SML_KEY,
			x.ZERO_EFFECT_FLG,
			x.MFG_ACT_GRP
		FROM	MGT_ACT_IO_IF x
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	x.AC_SLIP_TYP IN (C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO, C_IN_STKTK, C_OTH_CCN_GR)
		GROUP BY x.CALC_CTG_CD,
			x.WG_CD,
			x.YM,
			x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			CASE
				WHEN L_STKTK_SUM = C_OFF AND x.AC_SLIP_TYP = C_IN_STKTK THEN C_SO_STKTK
				WHEN L_OTH_CCN_SUM = C_OFF AND x.AC_SLIP_TYP = C_OTH_CCN_GR THEN C_OTH_CCN_SO
				ELSE x.AC_SLIP_TYP
			END, x.AC_RSN_CD,
			NVL(x.OTHER_WG_CD, x.WG_CD),
			NVL(x.OTHER_DPT_CD, x.MNG_DPT_CD),
			x.BP_CD,
			x.STK_BP_CD, x.ASST_TYP,
			x.TRD_CUR_CD,
			x.XRATE,
			x.ALC_AC_CD,
			x.ALC_AMT_FLG,
			x.ALC_WG_CD,
			x.ALC_DPT_CD, x.ALC_LOC_CD, x.ALC_OPER_CD, x.ALC_BP_CD,
			x.ALC_CTG_CD, x.ALC_ITM_CD, x.ALC_ITM_SUB1, x.ALC_ITM_SUB2, x.ALC_ITM_SUB3,
			x.ALC_LOT_NO, x.ALC_SUBLOT_NO, x.ALC_SNO1, x.ALC_SNO2, x.ALC_SNO3, x.ALC_SNO4,
			x.ALC_ITM_MFG_INST_NO,
			x.REC_EVAL_TYP,
			TO_CHAR(x.YM, 'YYYYMMDD'),
			x.ZERO_EFFECT_FLG,
			x.MFG_ACT_GRP
		) x2, MAM_ITM_SRCH m
	WHERE	0=0
	AND	x2.ITM_CD = m.ITM_CD
	AND	x2.ITM_SUB1 = m.ITM_SUB1
	AND	x2.ITM_SUB2 = m.ITM_SUB2
	AND	x2.ITM_SUB3 = m.ITM_SUB3
	AND	m.DEL_FLG = C_OFF
	AND	m.RELEASE_FLG = C_ON
	;

	DELETE	MGW_IO w
	WHERE	0=0
	AND	w.YM = I_YM
	AND	w.CALC_CTG_CD = I_CALC_CTG
	AND	w.QTY = 0
	AND	(NVL(w.AMT, 0) = 0
		AND	NVL(w.TRD_CUR_AMT, 0) = 0
		AND	w.AC_SLIP_TYP IN (C_ONR_PROV, C_ONR_PRVR)
		OR	w.AC_SLIP_TYP NOT IN (C_ONR_PROV, C_ONR_PRVR)
		)
	AND	w.ZERO_EFFECT_FLG = C_OFF
	;

	--出庫配賦費用の設定もしくは投入・入庫への振替の作成
	P_IFSUB(I_WG_CD, I_YM) ;

	-- 入出庫から投入への振替の作成
	P_IO_TO_INPT(I_CALC_CTG, I_WG_CD, I_YM) ;

	--販売倉入・生産戻入の集計
	P_IFSUB2(I_WG_CD, I_YM) ;

	--部門間移動の集計
	P_IFSUB3(I_WG_CD, I_YM) ;

	--品目間振替の集計
	P_IFSUB4(I_YM) ;

	--配賦科目ＣＤがNULLのときはALC_XXX項目をクリアする
	UPDATE	MGW_IO w
	SET	w.ALC_AMT_FLG	= C_OFF,
		w.ALC_WG_CD = NULL,
		w.ALC_DPT_CD	= NULL,
		w.ALC_LOC_CD	= NULL,
		w.ALC_OPER_CD	= NULL,
		w.ALC_BP_CD	= NULL,
		w.ALC_CTG_CD	= NULL,
		w.ALC_ITM_CD	= NULL,
		w.ALC_ITM_SUB1	= NULL,
		w.ALC_ITM_SUB2	= NULL,
		w.ALC_ITM_SUB3	= NULL,
		w.ALC_LOT_NO	= NULL,
		w.ALC_SUBLOT_NO	= NULL,
		w.ALC_SNO1	= NULL,
		w.ALC_SNO2	= NULL,
		w.ALC_SNO3	= NULL,
		w.ALC_SNO4	= NULL,
		w.ALC_ITM_MFG_INST_NO = NULL
	WHERE	0=0
	AND	w.ALC_AC_CD IS NULL
	;

	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGW_IO t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_IO w
			WHERE	0=0
			AND	w.ACT_IO_ID = t.ACT_IO_ID
			AND	w.ACT_IO_ID_SUB = t.ACT_IO_ID_SUB
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			AND	w.AC_SLIP_TYP IN (
					C_INSP_SMPL, C_DISP_SCRP, C_SO_STKTK, C_OTH_CCN_SO,
					C_PROD_ITM_SO, C_PROD_ITM_RET_SO, C_DPT_XFR_SO, C_STK_SW_SO,
					C_IN_STKTK, C_OTH_CCN_GR, C_STK_SW_GR
					)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	--入出庫実績の作成
	INSERT INTO MGT_ACT_IO (
		ACT_IO_ID, ACT_IO_ID_SUB,
		CALC_CTG_CD, WG_CD, YM, AC_DT,
		MNG_DPT_CD, ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		COST_IO_TYP, AC_SLIP_TYP, AC_RSN_CD,
		OTHER_WG_CD,
		OTHER_DPT_CD, BP_CD, STK_BP_CD, ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD, TRD_CUR_AMT, XRATE,
		TRD_GRP, TRD_RATIO,
		ALC_AC_CD, ALC_AMT_FLG, ALC_WG_CD, ALC_DPT_CD, ALC_LOC_CD,
		ALC_OPER_CD, ALC_BP_CD, ALC_CTG_CD, ALC_ITM_CD, ALC_ITM_SUB1, ALC_ITM_SUB2, ALC_ITM_SUB3,
		ALC_LOT_NO, ALC_SUBLOT_NO, ALC_SNO1, ALC_SNO2, ALC_SNO3, ALC_SNO4,
		ALC_ITM_MFG_INST_NO, REC_EVAL_TYP, ZERO_EFFECT_FLG
		)
	SELECT	x.ACT_IO_ID, x.ACT_IO_ID_SUB,
		x.CALC_CTG_CD, x.WG_CD, x.YM, x.AC_DT,
		x.MNG_DPT_CD, x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.COST_IO_TYP,
		CASE
			WHEN L_STKTK_SUM = C_OFF AND x.AC_SLIP_TYP = C_SO_STKTK THEN
				CASE
					WHEN x.COST_IO_TYP = C_IO_STK_OUT AND x.QTY >= 0 THEN C_SO_STKTK	--棚卸払出
					WHEN x.COST_IO_TYP = C_IO_STK_OUT AND x.QTY < 0 THEN C_IN_STKTK		--棚卸入庫
					WHEN x.COST_IO_TYP = C_IO_STK_IN AND x.QTY >= 0 THEN C_IN_STKTK		--棚卸入庫
					WHEN x.COST_IO_TYP = C_IO_STK_IN AND x.QTY < 0 THEN C_SO_STKTK		--棚卸払出
				END
			WHEN L_OTH_CCN_SUM = C_OFF AND x.AC_SLIP_TYP = C_OTH_CCN_SO THEN
				CASE
					WHEN x.COST_IO_TYP = C_IO_STK_OUT AND x.QTY >= 0 THEN C_OTH_CCN_SO	--他勘定払出
					WHEN x.COST_IO_TYP = C_IO_STK_OUT AND x.QTY < 0 THEN C_OTH_CCN_GR	--他勘定入庫
					WHEN x.COST_IO_TYP = C_IO_STK_IN AND x.QTY >= 0 THEN C_OTH_CCN_GR	--他勘定入庫
					WHEN x.COST_IO_TYP = C_IO_STK_IN AND x.QTY < 0 THEN C_OTH_CCN_SO	--他勘定払出
				END
			ELSE x.AC_SLIP_TYP
		END,
		x.AC_RSN_CD,
		x.OTHER_WG_CD,
		x.OTHER_DPT_CD, x.BP_CD, x.STK_BP_CD, x.ASST_TYP,
		x.QTY, x.AMT,
		x.TRD_CUR_CD, x.TRD_CUR_AMT, x.XRATE,
		x.TRD_GRP, x.TRD_RATIO,
		x.ALC_AC_CD, x.ALC_AMT_FLG, x.ALC_WG_CD, x.ALC_DPT_CD, x.ALC_LOC_CD,
		x.ALC_OPER_CD, x.ALC_BP_CD, x.ALC_CTG_CD, x.ALC_ITM_CD, x.ALC_ITM_SUB1, x.ALC_ITM_SUB2, x.ALC_ITM_SUB3,
		x.ALC_LOT_NO, x.ALC_SUBLOT_NO, x.ALC_SNO1, x.ALC_SNO2, x.ALC_SNO3, x.ALC_SNO4,
		x.ALC_ITM_MFG_INST_NO, x.REC_EVAL_TYP, x.ZERO_EFFECT_FLG
	FROM (
		SELECT	MAX(w.ACT_IO_ID)	ACT_IO_ID, MAX(w.ACT_IO_ID_SUB)	ACT_IO_ID_SUB,
			w.CALC_CTG_CD, w.WG_CD, w.YM, MAX(w.AC_DT)	AC_DT,
			w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.COST_IO_TYP,
			CASE
				WHEN L_STKTK_SUM = C_OFF AND w.AC_SLIP_TYP = C_IN_STKTK THEN C_SO_STKTK
				WHEN L_OTH_CCN_SUM = C_OFF AND w.AC_SLIP_TYP = C_OTH_CCN_GR THEN C_OTH_CCN_SO
				ELSE w.AC_SLIP_TYP
			END	AC_SLIP_TYP,
			w.AC_RSN_CD,
			DECODE(w.WG_CD, w.OTHER_WG_CD, NULL, w.OTHER_WG_CD)	OTHER_WG_CD,
			w.OTHER_DPT_CD, w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
			SUM(w.QTY)	QTY, SUM(w.AMT)	AMT,
			w.TRD_CUR_CD, SUM(w.TRD_CUR_AMT)	TRD_CUR_AMT, w.XRATE,
			w.TRD_GRP, SUM(w.TRD_RATIO)	TRD_RATIO,
			w.ALC_AC_CD, w.ALC_AMT_FLG, w.ALC_WG_CD, w.ALC_DPT_CD, w.ALC_LOC_CD,
			w.ALC_OPER_CD, w.ALC_BP_CD, w.ALC_CTG_CD, w.ALC_ITM_CD, w.ALC_ITM_SUB1, w.ALC_ITM_SUB2, w.ALC_ITM_SUB3,
			w.ALC_LOT_NO, w.ALC_SUBLOT_NO, w.ALC_SNO1, w.ALC_SNO2, w.ALC_SNO3, w.ALC_SNO4,
			w.ALC_ITM_MFG_INST_NO, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG
		FROM	MGW_IO w
		WHERE	0=0
		GROUP BY w.CALC_CTG_CD, w.WG_CD, w.YM,
			w.MNG_DPT_CD, w.ITM_CD, w.ITM_SUB1, w.ITM_SUB2, w.ITM_SUB3,
			w.LOT_NO, w.SUBLOT_NO, w.SNO1, w.SNO2, w.SNO3, w.SNO4,
			w.COST_IO_TYP,
			CASE
				WHEN L_STKTK_SUM = C_OFF AND w.AC_SLIP_TYP = C_IN_STKTK THEN C_SO_STKTK
				WHEN L_OTH_CCN_SUM = C_OFF AND w.AC_SLIP_TYP = C_OTH_CCN_GR THEN C_OTH_CCN_SO
				ELSE w.AC_SLIP_TYP
			END,
			w.AC_RSN_CD,
			DECODE(w.WG_CD, w.OTHER_WG_CD, NULL, w.OTHER_WG_CD),
			w.OTHER_DPT_CD, w.BP_CD, w.STK_BP_CD, w.ASST_TYP,
			w.TRD_CUR_CD, w.XRATE,
			w.TRD_GRP,
			w.ALC_AC_CD, w.ALC_AMT_FLG, w.ALC_WG_CD, w.ALC_DPT_CD, w.ALC_LOC_CD,
			w.ALC_OPER_CD, w.ALC_BP_CD, w.ALC_CTG_CD, w.ALC_ITM_CD, w.ALC_ITM_SUB1, w.ALC_ITM_SUB2, w.ALC_ITM_SUB3,
			w.ALC_LOT_NO, w.ALC_SUBLOT_NO, w.ALC_SNO1, w.ALC_SNO2, w.ALC_SNO3, w.ALC_SNO4,
			w.ALC_ITM_MFG_INST_NO, w.REC_EVAL_TYP, w.ZERO_EFFECT_FLG, w.SML_KEY
		) x
	;

	DELETE	MGT_ACT_IO x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	AND	(
		NVL(x.AMT, 0) = 0 AND NVL(x.TRD_CUR_AMT, 0) = 0 AND x.AC_SLIP_TYP IN (C_ONR_PROV, C_ONR_PRVR)
		OR
		x.AC_SLIP_TYP NOT IN (C_ONR_PROV, C_ONR_PRVR)
		)
	AND	x.ZERO_EFFECT_FLG = C_OFF
	;

	--売上実績の取込
	SELECT	MAX(t.YM), MAX(t.CALC_CTG_CD), MAX(t.WG_CD)
	INTO	L_YM, L_CALC_CTG, L_WG_CD
	FROM	MGT_ACT_SLS_IF t
	WHERE	0=0
	AND	t.YM = I_YM
	AND	t.CALC_CTG_CD = I_CALC_CTG
	AND	t.WG_CD = I_WG_CD
	AND	EXISTS (
			SELECT	'X'
			FROM	MGT_ACT_SLS w
			WHERE	0=0
			AND	w.ACT_SLS_ID = TO_CHAR(t.DATA_LNO)
			AND	(w.CALC_CTG_CD <> I_CALC_CTG OR w.WG_CD <> I_WG_CD OR w.YM <> I_YM)
			)
	AND	ROWNUM = 1
	;

	IF L_CALC_CTG IS NOT NULL THEN
		P_CTG_WG_YM_ERR() ;
	END IF ;

	INSERT INTO MGT_ACT_SLS (
		ACT_SLS_ID,
		ACT_SLS_ID_SUB,
		CALC_CTG_CD,
		WG_CD,
		YM, AC_DT,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		AC_SLIP_TYP, AC_RSN_CD,
		ASST_TYP,
		QTY, AMT,
		TRD_CUR_CD,
		TRD_CUR_AMT,
		XRATE,
		CST_CD, DLV_CD,
		SLS_DPT_CD, SLS_USR_CD,
		SLO_NO, IV_NO,
		STK_BP_CD,
		ALC_DPT_CD,
		DEST_CD1, DEST_CD2, DEST_CD3,
		COST_SLS_CD1, COST_SLS_CD2, COST_SLS_CD3, COST_SLS_CD4, COST_SLS_CD5,
		ALC_VAL1, ALC_VAL2, ALC_VAL3, ALC_VAL4, ALC_VAL5,
		REC_EVAL_TYP,
		ZERO_EFFECT_FLG
		)
	SELECT	MAX(TO_CHAR(x.DATA_LNO)),
		'0',
		x.CALC_CTG_CD,
		x.WG_CD,
		x.YM, MAX(x.AC_DT),
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.ASST_TYP,
		SUM(x.QTY), SUM(x.AMT),
		x.TRD_CUR_CD,
		SUM(x.TRD_CUR_AMT),
		x.XRATE,
		x.CST_CD, x.DLV_CD,
		x.SLS_DPT_CD, x.SLS_USR_CD,
		x.SLO_NO, x.IV_NO,
		x.STK_BP_CD,
		x.ALC_DPT_CD,
		x.DEST_CD1, x.DEST_CD2, x.DEST_CD3,
		x.COST_SLS_CD1, x.COST_SLS_CD2, x.COST_SLS_CD3, x.COST_SLS_CD4, x.COST_SLS_CD5,
		SUM(x.ALC_VAL1), SUM(x.ALC_VAL2), SUM(x.ALC_VAL3), SUM(x.ALC_VAL4), SUM(x.ALC_VAL5),
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	FROM	MGT_ACT_SLS_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.AC_SLIP_TYP, x.AC_RSN_CD,
		x.ASST_TYP,
		x.TRD_CUR_CD,
		x.XRATE,
		x.CST_CD, x.DLV_CD,
		x.SLS_DPT_CD, x.SLS_USR_CD,
		x.SLO_NO, x.IV_NO,
		x.STK_BP_CD,
		x.ALC_DPT_CD,
		x.DEST_CD1, x.DEST_CD2, x.DEST_CD3,
		x.COST_SLS_CD1, x.COST_SLS_CD2, x.COST_SLS_CD3, x.COST_SLS_CD4, x.COST_SLS_CD5,
		x.REC_EVAL_TYP,
		x.ZERO_EFFECT_FLG
	;

	DELETE	MGT_ACT_SLS x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	AND	x.AMT = 0
	AND	NVL(x.TRD_CUR_AMT, 0) = 0
	AND	NVL(x.ALC_VAL1, 0) = 0
	AND	NVL(x.ALC_VAL2, 0) = 0
	AND	NVL(x.ALC_VAL3, 0) = 0
	AND	NVL(x.ALC_VAL4, 0) = 0
	AND	NVL(x.ALC_VAL5, 0) = 0
	AND	x.ZERO_EFFECT_FLG = C_OFF
	;

	<<SKIP_TRAN>>
		NULL ;

	IF I_STK = C_OFF THEN
		GOTO SKIP_STK ;
	END IF ;

	--在庫実績の取込
	INSERT INTO MGT_ACT_STK (
		CALC_CTG_CD,
		WG_CD,
		YM,
		MNG_DPT_CD,
		ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
		LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
		BP_CD,
		ASST_TYP,
		QTY,
		FIRST_GR_DT, VLD_DT, LMT_DT,
		NON_MOV_BASE_DT
		)
	SELECT	x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.BP_CD,
		x.ASST_TYP,
		SUM(x.QTY),
		MIN(x.FIRST_GR_DT), MIN(x.VLD_DT), MIN(x.LMT_DT),
		MAX(x.NON_MOV_BASE_DT)
	FROM	MGT_ACT_STK_IF x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	GROUP BY x.CALC_CTG_CD,
		x.WG_CD,
		x.YM,
		x.MNG_DPT_CD,
		x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
		x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
		x.BP_CD,
		x.ASST_TYP
	;

	DELETE	MGT_ACT_STK x
	WHERE	0=0
	AND	x.YM = I_YM
	AND	x.CALC_CTG_CD = I_CALC_CTG
	AND	x.WG_CD = I_WG_CD
	AND	x.QTY = 0
	;

	<<SKIP_STK>>
		NULL ;

	IF I_MFG = C_ON OR I_TRAN = C_ON THEN
		--明細データ設定（投入）
		DELETE MGW_EXPNS_INPT ;
		INSERT INTO MGW_EXPNS_INPT (
			ACT_INPT_ID, ACT_INPT_ID_SUB, YM, MNG_DPT_CD,
			ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
			LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
			STK_BP_CD, ASST_TYP, QTY, AMT_SET_TYP, CALC_GRP_CD, WG_CD
			)
		SELECT	x.ACT_INPT_ID, x.ACT_INPT_ID_SUB, x.YM, x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.STK_BP_CD, x.ASST_TYP, x.QTY, m.AMT_SET_TYP, m.CALC_GRP_CD, x.WG_CD
		FROM	MGT_ACT_INPT x, MAM_REC_EVAL_SET m
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	m.SET_TGT_TYP = C_SET_TGT_INPT
		AND	x.AC_SLIP_TYP = m.AC_SLIP_TYP
		AND	(x.AC_RSN_CD = m.AC_RSN_CD OR x.AC_RSN_CD IS NULL AND m.AC_RSN_CD IS NULL)
		AND	x.CALC_CTG_CD = m.CALC_CTG_CD
		AND	x.WG_CD = m.WG_CD
		AND	x.AC_DT BETWEEN m.ST_DT AND m.END_DT
		AND	x.INS_USR_ID = L_USR
		AND	x.INS_TS >= L_TS
		;

		SELECT COUNT(*) INTO L_CNT FROM MGW_EXPNS_INPT x ;

		IF L_CNT > 0 THEN
			MGPA_SET_EXPNS.P_INPT('0') ;
		END IF ;
	END IF ;

	IF I_TRAN = C_ON THEN
		--明細データ設定（入出庫）
		DELETE MGW_EXPNS_IO ;
		INSERT INTO MGW_EXPNS_IO (
			ACT_IO_ID, ACT_IO_ID_SUB, YM, MNG_DPT_CD,
			ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
			LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
			STK_BP_CD, ASST_TYP, QTY, AMT_SET_TYP, CALC_GRP_CD, WG_CD
			)
		SELECT	x.ACT_IO_ID, x.ACT_IO_ID_SUB, x.YM, x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.STK_BP_CD, x.ASST_TYP, x.QTY, m.AMT_SET_TYP, m.CALC_GRP_CD, x.WG_CD
		FROM	MGT_ACT_IO x, MAM_REC_EVAL_SET m
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	m.SET_TGT_TYP = C_SET_TGT_IO
		AND	x.AC_SLIP_TYP = m.AC_SLIP_TYP
		AND	(x.AC_RSN_CD = m.AC_RSN_CD OR x.AC_RSN_CD IS NULL AND m.AC_RSN_CD IS NULL)
		AND	x.CALC_CTG_CD = m.CALC_CTG_CD
		AND	x.WG_CD = m.WG_CD
		AND	x.AC_DT BETWEEN m.ST_DT AND m.END_DT
		;

		INSERT INTO MGW_EXPNS_IO (
			ACT_IO_ID, ACT_IO_ID_SUB, YM, MNG_DPT_CD,
			ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
			LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
			STK_BP_CD, ASST_TYP, QTY, AMT_SET_TYP, CALC_GRP_CD, WG_CD
			)
		SELECT	x.ACT_IO_ID, x.ACT_IO_ID_SUB, x.YM, x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.STK_BP_CD, x.ASST_TYP, x.QTY, m.AMT_SET_TYP, m.CALC_GRP_CD, x.WG_CD
		FROM	MGT_ACT_IO x, MAM_REC_EVAL_SET m
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	m.SET_TGT_TYP IN (MAC_SET_TGT_TYP.IO_IN, MAC_SET_TGT_TYP.IO_OUT)
		AND	(
			x.COST_IO_TYP = C_IO_STK_IN AND m.SET_TGT_TYP = MAC_SET_TGT_TYP.IO_IN
			OR
			x.COST_IO_TYP = C_IO_STK_OUT AND m.SET_TGT_TYP = MAC_SET_TGT_TYP.IO_OUT
			)
		AND	x.AC_SLIP_TYP = m.AC_SLIP_TYP
		AND	(x.AC_RSN_CD = m.AC_RSN_CD OR x.AC_RSN_CD IS NULL AND m.AC_RSN_CD IS NULL)
		AND	x.CALC_CTG_CD = m.CALC_CTG_CD
		AND	x.WG_CD = m.WG_CD
		AND	x.AC_DT BETWEEN m.ST_DT AND m.END_DT
		AND	NOT EXISTS (
				SELECT	'X'
				FROM	MGW_EXPNS_IO w
				WHERE	0=0
				AND	w.ACT_IO_ID = x.ACT_IO_ID
				AND	w.ACT_IO_ID_SUB = x.ACT_IO_ID_SUB
			)
		;

		SELECT COUNT(*) INTO L_CNT FROM MGW_EXPNS_IO x ;

		IF L_CNT > 0 THEN
			MGPA_SET_EXPNS.P_IO('0') ;
		END IF ;

		--明細データ設定（売上）
		DELETE MGW_EXPNS_SLS ;
		INSERT INTO MGW_EXPNS_SLS (
			ACT_SLS_ID, ACT_SLS_ID_SUB, YM, MNG_DPT_CD,
			ITM_CD, ITM_SUB1, ITM_SUB2, ITM_SUB3,
			LOT_NO, SUBLOT_NO, SNO1, SNO2, SNO3, SNO4,
			STK_BP_CD, ASST_TYP, QTY, AMT_SET_TYP, CALC_GRP_CD, WG_CD
			)
		SELECT	x.ACT_SLS_ID, x.ACT_SLS_ID_SUB, x.YM, x.MNG_DPT_CD,
			x.ITM_CD, x.ITM_SUB1, x.ITM_SUB2, x.ITM_SUB3,
			x.LOT_NO, x.SUBLOT_NO, x.SNO1, x.SNO2, x.SNO3, x.SNO4,
			x.STK_BP_CD, x.ASST_TYP, x.QTY, m.AMT_SET_TYP, m.CALC_GRP_CD, x.WG_CD
		FROM	MGT_ACT_SLS x, MAM_REC_EVAL_SET m
		WHERE	0=0
		AND	x.YM = I_YM
		AND	x.CALC_CTG_CD = I_CALC_CTG
		AND	x.WG_CD = I_WG_CD
		AND	m.SET_TGT_TYP = C_SET_TGT_SLS
		AND	x.AC_SLIP_TYP = m.AC_SLIP_TYP
		AND	(x.AC_RSN_CD = m.AC_RSN_CD OR x.AC_RSN_CD IS NULL AND m.AC_RSN_CD IS NULL)
		AND	x.CALC_CTG_CD = m.CALC_CTG_CD
		AND	x.WG_CD = m.WG_CD
		AND	x.AC_DT BETWEEN m.ST_DT AND m.END_DT
		;

		SELECT COUNT(*) INTO L_CNT FROM MGW_EXPNS_SLS x ;

		IF L_CNT > 0 THEN
			MGPA_SET_EXPNS.P_SLS('0') ;
		END IF ;
	END IF ;

	IF L_RC = C_ERR1 THEN
		COMMIT ; --正常データは取込済みにするため
		L_MSG := FCPA_ERR.MSG_BINDER('MGPA_INS_MGTIF2MGT.P_IF') ;
		FCPA_ERR.RAISE_APP_ERR('MGBXD0037', L_MSG) ;
	END IF ;

	<<PROD_END>>
		NULL ;

	--処理が終了しました。{1}
	FCPA_BATCH_LOG.P_PROC_LOG('MGBXD0002', 'MGPA_INS_MGTIF2MGT.P_IF') ;

END P_IF ;

END MGPA_INS_MGTIF2MGT ;
/
